LAKESHORE_STOP_SETTLE_S = 2.0
LAKESHORE_SETPOINT_READBACK_A = 0.0005
LAKESHORE_RATE_READBACK_A_S = 0.00015
LAKESHORE_CLOSE_MIN_RATE_A_S = 0.01
LAKESHORE_OPST_COMPLIANCE = 1
