STFMR_LOCKIN_SR830_TIME_CONSTANTS = {'1 ms': 4, '3 ms': 5, '10 ms': 6, '30 ms': 7, '100 ms': 8, '300 ms': 9, '1 s': 10, '3 s': 11, '10 s': 12}
PPMS_SR830_DEFAULT_TIME_CONSTANT = "1 s"
