STFMR_LOCKIN_SR830_DEFAULT_REFERENCE_INPUT = "Sine"
_INSTRUMENT_LEASE_LOCK = threading.RLock()
_INSTRUMENT_LEASES: dict[str, tuple[object, str]] = {}
_SHARED_VISA_MANAGER_LOCK = threading.RLock()
_SHARED_VISA_MANAGER = None
_SHARED_VISA_MANAGER_USERS = 0
def acquire_shared_visa_manager():
    global _SHARED_VISA_MANAGER, _SHARED_VISA_MANAGER_USERS
    if pyvisa is None:
        raise RuntimeError('pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py')
    with _SHARED_VISA_MANAGER_LOCK:
        manager = _SHARED_VISA_MANAGER
        if manager is not None:
            try:
                manager.session
            except BaseException as error:
                if _SHARED_VISA_MANAGER_USERS:
                    raise RuntimeError('The shared VISA resource manager session became invalid unexpectedly; please close the instruments that still show as connected and reconnect') from error
                _SHARED_VISA_MANAGER = None
                manager = None
        if manager is None:
            manager = pyvisa.ResourceManager()
            manager.session
            _SHARED_VISA_MANAGER = manager
        _SHARED_VISA_MANAGER_USERS += 1
        return manager
def release_shared_visa_manager(manager) -> None:
    global _SHARED_VISA_MANAGER, _SHARED_VISA_MANAGER_USERS
    if manager is None:
        return
    with _SHARED_VISA_MANAGER_LOCK:
        if manager is not _SHARED_VISA_MANAGER:
            return
        _SHARED_VISA_MANAGER_USERS = max(0, _SHARED_VISA_MANAGER_USERS - 1)
        if _SHARED_VISA_MANAGER_USERS == 0:
            try:
                manager.close()
            except BaseException:
                pass
            finally:
                _SHARED_VISA_MANAGER = None
def instrument_lease_key(resource: str) -> str:
    key = str(resource).strip().upper()
    match = re.fullmatch(r"GPIB(\d*)::(\d+)(?:::(\d+))?(?:::INSTR)?", key)
    if match:
        board, primary, secondary = match.groups()
        key = f"GPIB{int(board or '0')}::{int(primary)}"
        if secondary is not None:
            key += f"::{int(secondary)}"
        key += "::INSTR"
    return key
INSTRUMENT_LEASE_TEXT_BYTES = 512
INSTRUMENT_LEASE_PROGRAM = Path(sys.argv[0]).stem or 'Transport'
def _process_instrument_leases() -> dict:
    return sys.__dict__.setdefault('_transport_instrument_process_leases', {})
def _process_instrument_lease_lock():
    return sys.__dict__.setdefault('_transport_instrument_process_lease_lock', threading.RLock())
def _instrument_lease_object_name(key: str) -> str:
    return 'TransportInstrumentLease_' + re.sub('[^A-Za-z0-9]+', '_', key)
def hold_instrument_for_this_process(key: str, owner_label: str):
    text = f'{INSTRUMENT_LEASE_PROGRAM} / {owner_label} (process {os.getpid()})'.encode('utf-8')[:INSTRUMENT_LEASE_TEXT_BYTES - 1]
    name = _instrument_lease_object_name(key)
    holder = None
    if sys.platform == 'win32':
        try:
            kernel = ctypes.WinDLL('kernel32', use_last_error=True)
            kernel.CreateFileMappingW.restype = ctypes.c_void_p
            kernel.CreateFileMappingW.argtypes = (ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_wchar_p)
            kernel.MapViewOfFile.restype = ctypes.c_void_p
            kernel.MapViewOfFile.argtypes = (ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_size_t)
            kernel.UnmapViewOfFile.argtypes = (ctypes.c_void_p,)
            kernel.CloseHandle.argtypes = (ctypes.c_void_p,)
            ctypes.set_last_error(0)
            handle = kernel.CreateFileMappingW(ctypes.c_void_p(-1), None, 4, 0, INSTRUMENT_LEASE_TEXT_BYTES, 'Local\\' + name)
            error = ctypes.get_last_error()
        except Exception:
            return None
        if not handle:
            if error == 5:
                raise RuntimeError('a program run with other Windows rights, e.g. as administrator')
            return None
        if error != 183:
            view = kernel.MapViewOfFile(handle, 6, 0, 0, INSTRUMENT_LEASE_TEXT_BYTES)
            if view:
                ctypes.memmove(view, text + b'\0', len(text) + 1)
                kernel.UnmapViewOfFile(view)
            return ('win32', handle)
        holder = ''
        try:
            view = kernel.MapViewOfFile(handle, 4, 0, 0, INSTRUMENT_LEASE_TEXT_BYTES)
            if view:
                try:
                    holder = ctypes.string_at(view, INSTRUMENT_LEASE_TEXT_BYTES).split(b'\0', 1)[0].decode('utf-8', 'replace')
                finally:
                    kernel.UnmapViewOfFile(view)
        finally:
            kernel.CloseHandle(handle)
    else:
        try:
            import fcntl
            import tempfile
            folder = Path(tempfile.gettempdir()) / 'Transport_instrument_leases'
            folder.mkdir(parents=True, exist_ok=True)
            handle = open(folder / (name + '.lock'), 'a+', encoding='utf-8')
        except (OSError, ImportError):
            return None
        try:
            fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            try:
                handle.seek(0)
                holder = handle.read(INSTRUMENT_LEASE_TEXT_BYTES).strip()
            except OSError:
                holder = ''
            handle.close()
        else:
            try:
                handle.seek(0)
                handle.truncate()
                handle.write(text.decode('utf-8', 'replace'))
                handle.flush()
            except OSError:
                pass
            return ('file', handle)
    raise RuntimeError(holder or 'another program')
def let_go_of_instrument_for_this_process(token) -> None:
    if token is None:
        return
    kind, handle = token
    try:
        if kind == 'win32':
            ctypes.WinDLL('kernel32').CloseHandle(ctypes.c_void_p(handle))
        else:
            handle.close()
    except (OSError, AttributeError):
        pass
def acquire_instrument_lease(resource: str, owner: object, owner_label: str) -> str:
    key = instrument_lease_key(resource)
    if not key:
        raise ValueError("The instrument resource address cannot be empty")
    with _INSTRUMENT_LEASE_LOCK:
        current = _INSTRUMENT_LEASES.get(key)
        if current is not None:
            raise RuntimeError(f'{resource} is already connected by "{current[1]}"; please disconnect it in that module first, then connect from "{owner_label}"')
        with _process_instrument_lease_lock():
            held = _process_instrument_leases()
            entry = held.get(key)
            if entry is None:
                try:
                    entry = held[key] = [hold_instrument_for_this_process(key, str(owner_label)), 0]
                except RuntimeError as other:
                    raise RuntimeError(f'{resource} is in use by another Transport program on this PC ({other}); disconnect it there or close that program first (if no such window is open, end that process in Task Manager), then connect from "{owner_label}"') from None
            entry[1] += 1
        _INSTRUMENT_LEASES[key] = (owner, str(owner_label))
    return key
def release_instrument_lease(resource: str, owner: object) -> None:
    key = instrument_lease_key(resource)
    if not key:
        return
    with _INSTRUMENT_LEASE_LOCK:
        current = _INSTRUMENT_LEASES.get(key)
        if current is not None and current[0] is owner:
            _INSTRUMENT_LEASES.pop(key, None)
            with _process_instrument_lease_lock():
                held = _process_instrument_leases()
                entry = held.get(key)
                if entry is not None:
                    entry[1] -= 1
                    if entry[1] <= 0:
                        held.pop(key, None)
                        let_go_of_instrument_for_this_process(entry[0])
class SafeVisaIdentityController:
    def __init__(
        self,
        logger: Callable[[str], None],
        label: str,
        identity_token: str,
        safe_off_commands: tuple[str, ...] = (),
        owner_scope: str = "PPMS",
        preserve_visa_io_defaults: bool = False,
        safe_off_on_connect: bool = True,
        enumerate_before_open: bool = False,
        connect_settle_seconds: float = 0.0,
    ) -> None:
        self.logger = logger
        self.label = str(label)
        self.identity_token = str(identity_token).upper()
        self.safe_off_commands = tuple(safe_off_commands)
        self.owner_scope = str(owner_scope)
        self.preserve_visa_io_defaults = bool(preserve_visa_io_defaults)
        self.safe_off_on_connect = bool(safe_off_on_connect)
        self.enumerate_before_open = bool(enumerate_before_open)
        self.connect_settle_seconds = max(0.0, float(connect_settle_seconds))
        self.resource_manager = None
        self.instrument = None
        self.resource_name = ""
        self.identity = ""
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    def connect(self, resource_name: str) -> str:
        if pyvisa is None:
            raise RuntimeError('pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py')
        resource_name = str(resource_name).strip()
        with self.lock:
            if self.instrument is not None:
                return self.identity
            acquire_instrument_lease(resource_name, self, f'{self.owner_scope} / {self.label}')
            manager = None
            instrument = None
            identity_verified = False
            try:
                manager = acquire_shared_visa_manager()
                if self.enumerate_before_open:
                    manager.list_resources()
                instrument = manager.open_resource(resource_name)
                instrument.timeout = 3000 if self.preserve_visa_io_defaults else 5000
                if not self.preserve_visa_io_defaults:
                    instrument.write_termination = "\n"
                    instrument.read_termination = "\n"
                    try:
                        instrument.query_delay = 0.05
                    except (AttributeError, ValueError):
                        pass
                else:
                    instrument.write_termination = "\r\n"
                    instrument.read_termination = None
                    instrument.send_end = True
                if self.connect_settle_seconds > 0:
                    time.sleep(self.connect_settle_seconds)
                try:
                    identity = instrument.query("*IDN?").strip()
                except BaseException as error:
                    raise RuntimeError(f'{self.label} identity query *IDN? failed: {error}; no output/setting command was sent to the device this time; the VISA session has been closed') from error
                if self.identity_token not in identity.upper():
                    raise RuntimeError(f'The device returned by {resource_name} is not {self.label}: {identity}')
                identity_verified = True
                if self.safe_off_on_connect:
                    for command in self.safe_off_commands:
                        try:
                            instrument.write(command)
                        except BaseException as error:
                            raise RuntimeError(f'{self.label} connection safety command {command!r} failed: {error}') from error
                self.resource_manager = manager
                self.instrument = instrument
                self.resource_name = resource_name
                self.identity = identity
                self.logger(f'{self.owner_scope} {self.label} connected: {identity}')
                return identity
            except BaseException:
                if instrument is not None:
                    if identity_verified and self.safe_off_on_connect:
                        for command in self.safe_off_commands:
                            try:
                                instrument.write(command)
                            except BaseException:
                                pass
                    try:
                        instrument.close()
                    except BaseException:
                        pass
                release_shared_visa_manager(manager)
                release_instrument_lease(resource_name, self)
                raise
    def safe_output_off(self) -> None:
        with self.lock:
            if self.instrument is None:
                return
            errors = []
            for command in self.safe_off_commands:
                try:
                    self.instrument.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            if errors:
                raise RuntimeError(f'{self.label} failed to turn output off: ' + '; '.join(errors))
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            manager = self.resource_manager
            resource_name = self.resource_name
            if instrument is None and manager is None:
                return
            shutdown_error = None
            try:
                self.safe_output_off()
            except BaseException as error:
                shutdown_error = error
            if instrument is not None:
                try:
                    instrument.write("SYST:LOC")
                except BaseException:
                    pass
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = None
            self.resource_manager = None
            self.resource_name = ""
            self.identity = ""
            release_instrument_lease(resource_name, self)
            self.logger(f"{self.owner_scope} {self.label} disconnected")
            if shutdown_error is not None:
                raise shutdown_error
class AvtechPulseError(RuntimeError):
    def __init__(self, message: str, *, fired: bool=False, amplitude_v: float=math.nan, width_s: float=math.nan, overload: bool | None=False) -> None:
        super().__init__(message)
        self.fired = fired
        self.amplitude_v = amplitude_v
        self.width_s = width_s
        self.overload = overload
class AvtechPulserController(SafeVisaIdentityController):
    OVERLOAD_ERROR = 1001
    def __init__(self, logger: Callable[[str], None]) -> None:
        super().__init__(logger, 'Avtech pulse generator', 'AVTECH', safe_off_commands=('trigger:source hold', 'output off'), owner_scope='CIDWM')
    def connect(self, resource_name: str) -> str:
        identity = super().connect(resource_name)
        with self.lock:
            try:
                self.instrument.write("*CLS")
                problem = self._off_problem()
            except BaseException as error:
                problem = f"*CLS after connecting failed: {error}"
            if problem is not None:
                try:
                    self.disconnect()
                except BaseException as error:
                    problem += f"; {error}"
                raise RuntimeError(f"{self.label}: {problem}; check the generator")
        return identity
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            manager = self.resource_manager
            resource_name = self.resource_name
            if instrument is None and manager is None:
                return
            problem = self._off_problem() if instrument is not None else None
            if instrument is not None:
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = None
            self.resource_manager = None
            self.resource_name = ""
            self.identity = ""
            release_instrument_lease(resource_name, self)
            self.logger(f"{self.owner_scope} {self.label} disconnected")
            if problem is not None:
                raise RuntimeError(f"{self.label}: {problem}; check the generator")
    @property
    def polarities(self) -> tuple[int, ...] | None:
        fields = self.identity.split(",")
        model = fields[1].strip().upper() if len(fields) > 1 else ""
        match = re.search(r"-(PN|P|N)(?=-|$)", model)
        if match is None:
            return None
        return {"PN": (1, -1), "P": (1,), "N": (-1,)}[match.group(1)]
    @staticmethod
    def validate(amplitude_v, width_s) -> tuple[float, float]:
        amplitude_v, width_s = float(amplitude_v), float(width_s)
        if not (math.isfinite(amplitude_v) and 0 < abs(amplitude_v) <= AVTECH_MAX_AMPLITUDE_V):
            raise ValueError(f'The Avtech amplitude must be above 0 and at most {AVTECH_MAX_AMPLITUDE_V:g} V')
        AvtechPulserController.validate_width(width_s)
        return amplitude_v, width_s
    @staticmethod
    def validate_width(width_s) -> float:
        width_s = float(width_s)
        if not (math.isfinite(width_s) and AVTECH_MIN_WIDTH_S * 0.999 <= width_s <= AVTECH_MAX_WIDTH_S * 1.001):
            raise ValueError("The Avtech pulse width must be within 1 ns - 5 us")
        return width_s
    def _number(self, query: str) -> float:
        reply = str(self.instrument.query(query)).strip()
        try:
            value = float(reply)
        except ValueError as error:
            raise RuntimeError(f"{self.label}: {query} returned {reply!r}") from error
        if not math.isfinite(value):
            raise RuntimeError(f"{self.label}: {query} returned {reply!r}")
        return value
    def _errors(self, found: list | None = None) -> list[tuple[int, str]]:
        found = [] if found is None else found
        for _ in range(32):
            reply = str(self.instrument.query("syst:err?")).strip()
            try:
                code = int(float(reply.split(",", 1)[0]))
            except ValueError:
                found.append((-1, reply))
                continue
            if code == 0:
                break
            found.append((code, reply))
        return found
    def _off_problem(self) -> str | None:
        failures = []
        def clear() -> None:
            try:
                self.instrument.clear()
            except BaseException as error:
                failures.append(f"device clear: {error}")
        def send(command: str) -> bool:
            try:
                self.instrument.write(command)
                return True
            except BaseException as error:
                failures.append(f"{command}: {error}")
                return False
        clear()
        for command in ("trigger:source hold", "output off"):
            if not send(command):
                clear()
                send(command)
        for attempt in range(2):
            try:
                if self._number("output?") == 0:
                    if failures:
                        self.logger(f"{self.label}: output read back off, after: " + "; ".join(failures))
                    return None
                failures.append("its output did not read back off")
            except BaseException as error:
                failures.append(f"output? failed: {error}")
            if attempt == 0:
                clear()
                send("output off")
        return "; ".join(failures)
    def switch_off(self) -> None:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError(f"{self.label} is not connected; its output state is unknown")
            problem = self._off_problem()
            if problem is not None:
                raise RuntimeError(f"{self.label}: {problem}; check the generator")
    def single_pulse(self, amplitude_v: float, width_s: float) -> dict:
        amplitude_v, width_s = self.validate(amplitude_v, width_s)
        sign = 1 if amplitude_v > 0 else -1
        with self.lock:
            if self.instrument is None:
                raise AvtechPulseError(f"{self.label} is not connected; no pulse fired")
            allowed = self.polarities
            if allowed is not None and sign not in allowed:
                raise AvtechPulseError(f"This {self.label} gives {('positive' if allowed == (1,) else 'negative')} pulses only (its polarity option); no pulse fired")
            failure = None
            fired = trigger_sent = False
            amplitude_read = width_read = math.nan
            after: list[tuple[int, str]] = []
            others: list[str] = []
            try:
                self.instrument.clear()
                self.instrument.write("*CLS")
                self.instrument.write("trigger:source hold")
                self.instrument.write("output off")
                errors = self._errors()
                if errors:
                    raise RuntimeError(f'{self.label} refused hold or output off: ' + '; '.join((text for _code, text in errors)))
                if self._number("output?") != 0:
                    raise RuntimeError(f"{self.label}'s output did not read back off before the pulse")
                self.instrument.write("pulse:delay 0")
                if not abs(self._number("pulse:delay?")) <= 1e-9:
                    raise RuntimeError(f"{self.label} did not take a delay of 0")
                self.instrument.write(f"pulse:width {width_s:.6g}")
                width_read = self._number("pulse:width?")
                if not abs(width_read - width_s) <= max(0.05 * width_s, 0.2e-9):
                    raise RuntimeError(f"{self.label} took a width of {width_read:.4g} s for {width_s:.4g} s")
                self.instrument.write(f"volt:ampl {amplitude_v:.6g}")
                amplitude_read = self._number("volt:ampl?")
                tolerance = max(0.02 * abs(amplitude_v), 0.5)
                if not (amplitude_read * sign > 0 and abs(amplitude_read - amplitude_v) <= tolerance):
                    raise RuntimeError(f'{self.label} took {amplitude_read:+g} V for {amplitude_v:+g} V (its polarity option?)')
                errors = self._errors()
                if errors:
                    raise RuntimeError(f"{self.label} reported " + "; ".join(text for _code, text in errors))
                self.instrument.write("output on")
                if self._number("output?") != 1:
                    raise RuntimeError(f"{self.label}'s output did not switch on")
                fired = True
                self.instrument.write("trigger:source immediate")
                trigger_sent = True
                self.instrument.write("trigger:source hold")
                self._errors(after)
            except BaseException as error:
                failure = error
            problem = self._off_problem()
            try:
                self._errors(after)
            except BaseException as error:
                others.append(f"its error queue could not be read: {error}")
            overload: bool | None = any(code == self.OVERLOAD_ERROR for code, _text in after)
            others += [text for code, text in after if code != self.OVERLOAD_ERROR]
            try:
                overload = overload or self._number("output:protection:tripped?") != 0
            except BaseException as error:
                others.append(f"its overload state could not be read: {error}")
                overload = True if overload else None
            parts = []
            if failure is not None:
                parts.append(str(failure))
            parts += [f"it reported {text}" for text in others]
            if problem is not None:
                parts.append(f"{problem}; check the generator")
            if parts:
                if overload:
                    parts.append("OVERLOAD: output protection tripped (short or too-low load impedance)")
                if trigger_sent:
                    prefix = "pulse fired, then: "
                elif fired:
                    prefix = "the trigger may have been sent (a pulse may have fired), then: "
                else:
                    prefix = "no pulse fired: "
                raise AvtechPulseError(prefix + '; '.join(parts), fired=fired, amplitude_v=amplitude_read, width_s=width_read, overload=overload) from failure
            return {'amplitude_v': amplitude_read, 'width_s': width_read, 'overload': overload, 'pulse_end': time.monotonic()}
    @staticmethod
    def validate_count(count) -> int:
        if isinstance(count, str):
            text = count.strip()
            if not re.fullmatch(r"[0-9]+", text):
                raise ValueError(f'The Avtech pulse count must be a whole number from 1 to {AVTECH_MAX_PULSE_COUNT}')
            count = int(text)
        if isinstance(count, bool) or not isinstance(count, int) or not 1 <= count <= AVTECH_MAX_PULSE_COUNT:
            raise ValueError(f'The Avtech pulse count must be a whole number from 1 to {AVTECH_MAX_PULSE_COUNT}')
        return count
    def pulse_train(self, amplitude_v: float, width_s: float, count, *, gap_s: float = AVTECH_PULSE_GAP_S,
                    stop_event: threading.Event | None = None,
                    progress: Callable[[int, int], None] | None = None) -> dict:
        amplitude_v, width_s = self.validate(amplitude_v, width_s)
        count = self.validate_count(count)
        gap_s = float(gap_s)
        if not (math.isfinite(gap_s) and 0.0 <= gap_s <= 3600.0):
            raise ValueError("The Avtech pulse gap must be within 0 - 3600 s")
        done = 0
        result: dict = {'amplitude_v': math.nan, 'width_s': math.nan, 'overload': False, 'pulse_end': time.monotonic()}
        stopped = False
        for index in range(1, count + 1):
            if stop_event is not None and stop_event.is_set():
                stopped = True
                break
            if progress is not None:
                progress(index, count)
            try:
                result = self.single_pulse(amplitude_v, width_s)
            except AvtechPulseError as error:
                error.pulse_index, error.pulses_done = index, done
                raise
            done += 1
            if result["overload"]:
                break
            if index < count:
                if stop_event is not None:
                    if stop_event.wait(gap_s):
                        stopped = True
                        break
                else:
                    time.sleep(gap_s)
        if stopped:
            try:
                self.switch_off()
            except BaseException as error:
                stop_error = AvtechPulseError(f'stopped after {done}/{count} pulses, then: {error}', amplitude_v=result['amplitude_v'], width_s=result['width_s'], overload=result['overload'])
                stop_error.pulse_index, stop_error.pulses_done = done, done
                stop_error.output_unknown = True
                raise stop_error from error
        return dict(result, pulses=done, count=count, stopped=stopped)
class STFMRKepco4886Controller:
    def __init__(self, logger: Callable[[str], None], owner_scope: str='STFMR') -> None:
        self.logger = logger
        self.owner_scope = str(owner_scope)
        self.resource_manager = None
        self.instrument = None
        self.resource_name = ""
        self.identity = ""
        self.lock = threading.RLock()
        self.active_mode = ""
        self.output_owned = False
        self.last_command = ""
        self.cached_current_a = 0.0
        self.cached_voltage_v = 0.0
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    def connect(self, resource_name: str) -> str:
        if pyvisa is None:
            raise RuntimeError("pyvisa is missing; please run: py -m pip install pyvisa")
        resource_name = str(resource_name).strip()
        if not resource_name:
            raise ValueError("The KEPCO VISA resource address cannot be empty")
        with self.lock:
            if self.instrument is not None:
                return self.identity
            acquire_instrument_lease(resource_name, self, f'{self.owner_scope} / KEPCO BOP 4886 20-10')
            manager = None
            instrument = None
            try:
                manager = acquire_shared_visa_manager()
                instrument = manager.open_resource(resource_name)
                instrument.timeout = 3000
                instrument.write_termination = None
                instrument.read_termination = None
                instrument.send_end = True
                self.resource_manager = manager
                self.instrument = instrument
                self.resource_name = resource_name
                self.identity = "KEPCO BOP 4886 20-10 (not queried)"
                self.last_command = ""
                self.logger('STFMR KEPCO VISA session opened; no query or output command sent')
                return self.identity
            except BaseException:
                if instrument is not None:
                    try:
                        instrument.close()
                    except BaseException:
                        pass
                release_shared_visa_manager(manager)
                release_instrument_lease(resource_name, self)
                raise
    def _write_exact(self, command: str) -> None:
        if self.instrument is None:
            raise RuntimeError("KEPCO is not connected")
        payload = str(command).encode("ascii")
        writer = getattr(self.instrument, "write_raw", None)
        if callable(writer):
            writer(payload)
        else:
            self.instrument.write(str(command))
    def _send_output_sequence(self, commands) -> None:
        for command in commands:
            if command == "OUTP ON":
                self.output_owned = True
            self.last_command = command
            self._write_exact(command)
    def _cached_state(self) -> dict[str, object]:
        return {
            "mode": self.active_mode or "CURR",
            "current_a": self.cached_current_a,
            "voltage_v": self.cached_voltage_v,
            "output": self.output_owned,
            "programmed_current_a": self.cached_current_a,
            "programmed_voltage_v": self.cached_voltage_v,
        }
    def readback(self) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("KEPCO is not connected")
            return self._cached_state()
    def set_output(self, mode: str, target: float, complementary_limit: float) -> dict[str, object]:
        selected = str(mode).strip().upper()
        target = float(target)
        limit = abs(float(complementary_limit))
        if not math.isfinite(target) or not math.isfinite(limit):
            raise ValueError("KEPCO target value and limit must be finite numbers")
        if selected == "CURR":
            if abs(target) > STFMR_KEPCO_MAX_CURRENT_A:
                raise ValueError("BOP 20-10 current target must be within ±10 A")
            if not 0.0 < limit <= STFMR_KEPCO_MAX_VOLTAGE_V:
                raise ValueError("Voltage limit in current mode must be within 0–20 V")
        elif selected == "VOLT":
            if abs(target) > STFMR_KEPCO_MAX_VOLTAGE_V:
                raise ValueError("BOP 20-10 voltage target must be within ±20 V")
            if not 0.0 < limit <= STFMR_KEPCO_MAX_CURRENT_A:
                raise ValueError("Current limit in voltage mode must be within 0–10 A")
        else:
            raise ValueError(f"Unsupported KEPCO mode: {mode}")
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("KEPCO is not connected")
            commands = [f"FUNC:MODE {selected}"]
            if selected == "CURR":
                commands.extend((f'CURR 0;VOLT {limit:.12g}', 'VOLT:RANG:AUTO 1;CURR:RANG:AUTO 1', 'OUTP ON', f'CURR {target:.6f}'))
            else:
                commands.extend((f'VOLT 0;CURR {limit:.12g}', 'VOLT:RANG:AUTO 1;CURR:RANG:AUTO 1', 'OUTP ON', f'VOLT {target:.6f}'))
            self.active_mode = selected
            try:
                self._send_output_sequence(commands)
            except BaseException:
                if self.output_owned:
                    try:
                        self.safe_output_off()
                    except BaseException:
                        pass
                raise
            if selected == "CURR":
                self.cached_current_a = target
                self.cached_voltage_v = limit
            else:
                self.cached_voltage_v = target
                self.cached_current_a = limit
            return self._cached_state()
    def set_scan_current(self, current_a: float) -> dict[str, object]:
        current = float(current_a)
        if not math.isfinite(current):
            raise ValueError("KEPCO sweep current must be a finite number")
        if abs(current) > STFMR_KEPCO_MAX_CURRENT_A:
            raise ValueError("BOP 20-10 sweep current must be within ±10 A")
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("KEPCO is not connected")
            if not self.output_owned or self.active_mode != "CURR":
                raise RuntimeError("KEPCO is not in the current-output mode enabled by this program")
            self._write_exact(f"CURR {current:.6f}")
            self.cached_current_a = current
            return self._cached_state()
    def safe_output_off(self) -> None:
        with self.lock:
            if self.instrument is None or not self.output_owned:
                return
            zero = 'VOLT 0.000000' if self.active_mode == 'VOLT' else 'CURR 0.000000'
            failures = []
            for command in (zero, "OUTP OFF"):
                self.last_command = command
                try:
                    self._write_exact(command)
                except BaseException as error:
                    failures.append((command, error))
            if failures:
                raise RuntimeError('KEPCO 4886 zero/OFF not confirmed: ' + '; '.join((f'{command!r} {short_status_error(error, 70)}' for command, error in failures))) from failures[0][1]
            self.output_owned = False
            self.cached_current_a = 0.0
            self.cached_voltage_v = 0.0
    def zero_output(self) -> dict[str, object]:
        self.safe_output_off()
        return self._cached_state()
    def force_output_off(self) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("KEPCO is not connected")
            zeros = {'CURR': ('CURR 0.000000',), 'VOLT': ('VOLT 0.000000',)}.get(self.active_mode, ('CURR 0.000000', 'VOLT 0.000000'))
            failures = []
            for command in (*zeros, "OUTP OFF"):
                self.last_command = command
                try:
                    self._write_exact(command)
                except BaseException as error:
                    failures.append((command, error))
            if failures:
                self.output_owned = True
                raise RuntimeError('KEPCO 4886 zero/OFF not confirmed: ' + '; '.join((f'{command!r} {short_status_error(error, 70)}' for command, error in failures))) from failures[0][1]
            self.output_owned = False
            self.cached_current_a = 0.0
            self.cached_voltage_v = 0.0
            return self._cached_state()
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            manager = self.resource_manager
            resource_name = self.resource_name
            if instrument is None and manager is None:
                return
            shutdown_error = None
            try:
                self.safe_output_off()
            except BaseException as error:
                shutdown_error = error
            if instrument is not None:
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = None
            self.resource_manager = None
            self.resource_name = ""
            self.identity = ""
            self.active_mode = ""
            release_instrument_lease(resource_name, self)
            self.logger("STFMR KEPCO VISA session closed")
            if shutdown_error is not None:
                raise shutdown_error
class LakeShoreRampStopped(RuntimeError):
    def __init__(self, message: str, current_a: float = math.nan) -> None:
        super().__init__(message)
        self.current_a = current_a
class LakeShoreRampError(RuntimeError):
    def __init__(self, message: str, current_a: float = math.nan) -> None:
        super().__init__(message)
        self.current_a = current_a
class LakeShoreZeroError(LakeShoreRampError):
    pass
def lakeshore_current_tolerance_a(current_a, model: str = "648") -> float:
    info = LAKESHORE_MAGNET_MODELS[str(model)]
    return max(float(info["tolerance_a"]), float(info["tolerance_rel"]) * abs(float(current_a)))
def lakeshore_tolerance_text(model: str = "648") -> str:
    info = LAKESHORE_MAGNET_MODELS[str(model)]
    return f"max({info['tolerance_a']:g} A, {100 * info['tolerance_rel']:g} % of |I|)"
def lakeshore_scan_ramp_seconds(currents, rate_a_s) -> float:
    values = list(currents)
    return lakeshore_ramp_seconds(values, rate_a_s) + max(len(values) - 1, 0) * LAKESHORE_SETPOINT_OVERHEAD_S
def parse_lakeshore_rate(text) -> float:
    try:
        rate = float(str(text).strip())
    except (TypeError, ValueError):
        rate = math.nan
    if not math.isfinite(rate) or not LAKESHORE_MIN_RATE_A_S <= rate <= LAKESHORE_MAX_RATE_A_S:
        raise ValueError(f"Rate A/s must be from {LAKESHORE_MIN_RATE_A_S:g} to {LAKESHORE_MAX_RATE_A_S:g} A/s")
    return rate
def lakeshore_error_names(hardware: int, operational: int) -> list[str]:
    names = [name for bit, name in LAKESHORE_HARDWARE_ERRORS.items() if int(hardware) >> bit & 1]
    names += [name for bit, name in LAKESHORE_OPERATIONAL_ERRORS.items() if int(operational) >> bit & 1]
    return names
def lakeshore_blocking_errors(hardware: int, operational: int) -> list[str]:
    names = [name for bit, name in LAKESHORE_HARDWARE_ERRORS.items() if int(hardware) >> bit & 1]
    names += [name for bit, name in LAKESHORE_OPERATIONAL_ERRORS.items() if int(operational) >> bit & 1 and bit not in LAKESHORE_WARNING_OPERATIONAL_BITS]
    return names
def lakeshore_live_text(reading) -> str:
    if not reading:
        return "-- A"
    current, setpoint = float(reading.get("current_a", math.nan)), float(reading.get("setpoint_a", math.nan))
    voltage = float(reading.get("voltage_v", math.nan))
    largest = max((abs(value) for value in (current, setpoint) if math.isfinite(value)), default=0.0)
    digits = 3 if largest < 9.9995 else 2 if largest < 99.995 else 1
    def number(value, form):
        return f"{value:{form}}" if math.isfinite(value) else "--"
    return f"{number(current, f'+.{digits}f')} A (set {number(setpoint, f'+.{digits}f')}) {number(voltage, '.2f')} V"
def lakeshore_state_word(reading, arm_problem: str = "") -> str:
    if not reading:
        return "Connected"
    if reading.get("errors_blocking"):
        return "ERROR"
    if reading.get("compliance") or reading.get("power_limit"):
        return "Compliance" if reading.get("compliance") else "Power limit"
    if arm_problem:
        return "NOT ARMED"
    if reading.get("output_on") is False:
        return "At 0 A"
    if reading.get("at_setpoint"):
        return "At setpoint"
    return "Ramping" if reading.get("ramping") else "Connected"
class LakeShoreMagnetSupplyController(SafeVisaIdentityController):
    def __init__(self, logger: Callable[[str], None], model: str, owner_scope: str = "STFMR") -> None:
        info = LAKESHORE_MAGNET_MODELS[str(model)]
        super().__init__(logger, info['label'], info['model'], owner_scope=owner_scope, safe_off_on_connect=False)
        self.model = str(model)
        self.short_label = info["short"]
        self.model_token = info["model"]
        self.program_max_a = float(info["max_current_a"])
        self.connect_rate_a_s = math.nan
        self.clock = time.monotonic
        self.sleep = time.sleep
        self._next_io_at = 0.0
        self._stop_request = threading.Event()
        self.reading: dict[str, object] = {}
        self.limit_current_a = math.nan
        self.limit_rate_a_s = math.nan
        self.rate_a_s = math.nan
        self.program_rate_a_s: float | None = None
        self.setpoint_a = math.nan
        self.current_a = math.nan
        self.voltage_v = math.nan
        self.output_on = False
        self.arm_problem = ""
        self.xpgm = None
        self.magnet_water = None
        self.internal_water = None
        self.ramp_segments = None
        self.ramp_segment_table: tuple[tuple[int, float, float], ...] = ()
        self.ramp_segment_problem = ""
        self.last_ramp: dict[str, object] = {}
        self.last_zero_notes: list[str] = []
    @property
    def effective_max_a(self) -> float:
        limit = self.limit_current_a
        return min(self.program_max_a, limit) if math.isfinite(limit) else self.program_max_a
    @property
    def effective_max_rate_a_s(self) -> float:
        limit = self.limit_rate_a_s
        return min(LAKESHORE_MAX_RATE_A_S, limit) if math.isfinite(limit) else LAKESHORE_MAX_RATE_A_S
    def check_current(self, current_a) -> float:
        value = float(current_a)
        if not math.isfinite(value):
            raise ValueError(f"The {self.short_label} current must be a finite number")
        if abs(value) > self.program_max_a + 1e-9:
            raise ValueError(f"The {self.short_label} current must be within ±{self.program_max_a:g} A (the program's limit); {value:+g} A was refused and nothing was sent")
        limit = self.limit_current_a
        if math.isfinite(limit) and abs(value) > limit + 1e-9:
            raise ValueError(f"{value:+g} A is above the {self.short_label}'s LIMIT? maximum current of {limit:g} A (its front-panel limit); nothing was sent")
        return value
    def check_rate(self, rate_a_s) -> float:
        value = parse_lakeshore_rate(rate_a_s)
        limit = self.limit_rate_a_s
        if math.isfinite(limit) and value > limit + 1e-9:
            raise ValueError(f"{value:g} A/s is above the {self.short_label}'s LIMIT? maximum rate of {limit:g} A/s (its front-panel limit); nothing was sent")
        return value
    def _require(self) -> None:
        if self.instrument is None:
            raise RuntimeError(f"The {self.label} is not connected")
    def _pace(self) -> None:
        wait = self._next_io_at - self.clock()
        if wait > 0:
            self.sleep(wait)
    def _query(self, command: str) -> str:
        self._require()
        self._pace()
        try:
            return str(self.instrument.query(command)).strip()
        finally:
            self._next_io_at = self.clock() + LAKESHORE_IO_GAP_S
    def _write(self, command: str) -> None:
        self._require()
        self._pace()
        try:
            self.instrument.write(command)
        finally:
            self._next_io_at = self.clock() + LAKESHORE_IO_GAP_S
    def _numbers(self, command: str, count: int) -> list[float]:
        reply = self._query(command)
        try:
            values = [float(part) for part in reply.split(",") if part.strip()]
        except ValueError:
            values = []
        if len(values) != count or not all(math.isfinite(value) for value in values):
            raise RuntimeError(f"{self.short_label} {command} answered {reply!r}, not {count} number(s)")
        return values
    def _number(self, command: str) -> float:
        return self._numbers(command, 1)[0]
    def _optional_number(self, command: str):
        try:
            return self._number(command)
        except Exception as error:
            self.logger(f"{self.owner_scope} {self.short_label}: {command} not answered ({short_status_error(error, 60)})")
            return None
    def tolerance_a(self, current_a) -> float:
        return lakeshore_current_tolerance_a(current_a, self.model)
    def _stopped(self, stop_event) -> bool:
        return self._stop_request.is_set() or (stop_event is not None and stop_event.is_set())
    def request_stop(self) -> None:
        self._stop_request.set()
    def clear_stop_request(self) -> None:
        self._stop_request.clear()
    def connect(self, resource_name: str) -> str:
        with self.lock:
            if self.instrument is not None:
                return self.identity
            identity = super().connect(resource_name)
            self._next_io_at = self.clock() + LAKESHORE_IO_GAP_S
            try:
                fields = [part.strip().upper() for part in identity.split(",")]
                if len(fields) < 2 or fields[0] != "LSCI" or fields[1] != self.model_token:
                    raise RuntimeError(f'{resource_name} answered *IDN? with {identity!r}, not the {self.label} (LSCI,{self.model_token}); nothing else was sent')
                self._stop_request.clear()
                self._read_connect_state()
            except BaseException:
                self._close_session()
                raise
            reading = self.reading
            self.logger(
                f"{self.owner_scope} {self.short_label}: SETI? {reading['setpoint_a']:+.3f} A, RDGI? "
                f"{reading['current_a']:+.4f} A, RDGV? {reading['voltage_v']:+.4f} V, RATE? {self.rate_a_s:g} A/s, "
                f"LIMIT? {self.limit_current_a:g} A / {self.limit_rate_a_s:g} A/s, XPGM? "
                f"{LAKESHORE_XPGM_MODES.get(self.xpgm, self.xpgm)}, OPST? {reading['opst']}, ERST? "
                f"{reading['hardware_errors']},{reading['operational_errors']}; usable up to "
                f"±{self.effective_max_a:g} A at {LAKESHORE_MIN_RATE_A_S:g} to {self.effective_max_rate_a_s:g} A/s"
                + (f"; NOT ARMED: {self.arm_problem}" if self.arm_problem else "")
                + ("" if not reading["output_on"] else "; the output is NOT at zero"))
            return identity
    def _read_connect_state(self) -> None:
        setpoint = self._number("SETI?")
        current = self._number("RDGI?")
        voltage = self._number("RDGV?")
        self.rate_a_s = self.connect_rate_a_s = self._number("RATE?")
        self.limit_current_a, self.limit_rate_a_s = self._numbers("LIMIT?", 2)
        self.xpgm = int(self._number("XPGM?"))
        opst = int(self._number("OPST?"))
        hardware, operational = (int(value) for value in self._numbers("ERST?", 2))
        water = self._optional_number("MAGWTR?")
        self.magnet_water = None if water is None else int(water)
        water = self._optional_number("INTWTR?")
        self.internal_water = None if water is None else int(water)
        self._check_ramp_segments(first=True)
        self.setpoint_a = setpoint
        self._update_reading(current, voltage, opst, hardware, operational)
        self._update_arm_problem(self.xpgm, hardware, operational)
    def _check_ramp_segments(self, first: bool = False) -> str:
        if not first and self.ramp_segments is None:
            return self.ramp_segment_problem
        segments = self._optional_number("RSEG?")
        self.ramp_segments = None if segments is None else int(segments)
        if self.ramp_segments == 0:
            self.ramp_segment_problem = ""
            return ""
        if first or not self.ramp_segment_table:
            table = []
            for segment in range(1, 6):
                try:
                    current, rate = self._numbers(f"RSEGS? {segment}", 2)
                except Exception as error:
                    self.logger(f'{self.owner_scope} {self.short_label}: RSEGS? {segment} not answered ({short_status_error(error, 60)})')
                    continue
                table.append((segment, current, rate))
            self.ramp_segment_table = tuple(table)
        active = [(segment, current, rate) for segment, current, rate in self.ramp_segment_table if current > 0]
        if not active:
            self.ramp_segment_problem = ""
            return ""
        state = "RSEG? 1" if self.ramp_segments == 1 else "RSEG? not answered"
        listed = ", ".join(f"segment {segment} up to {current:g} A at {rate:g} A/s" for segment, current, rate in active)
        self.ramp_segment_problem = f'ramp segments may be on ({state}; {listed}): disable Ramp Segments on the front panel (the program uses one rate)'
        return self.ramp_segment_problem
    def _update_arm_problem(self, xpgm, hardware: int, operational: int) -> str:
        problems = []
        if xpgm != 0:
            problems.append(f'its programming mode is {LAKESHORE_XPGM_MODES.get(xpgm, xpgm)} (XPGM? {xpgm}), not Internal: set it to Internal on the front panel')
        blocking = lakeshore_blocking_errors(hardware, operational)
        if blocking:
            problems.append(f"an error is latched (ERST? {hardware},{operational}: {', '.join(blocking)}): remove its cause and clear it on the front panel (Status)")
        if self.ramp_segment_problem:
            problems.append(self.ramp_segment_problem)
        self.arm_problem = "; ".join(problems)
        return self.arm_problem
    def _require_armed(self) -> None:
        self.xpgm = int(self._number("XPGM?"))
        hardware, operational = (int(value) for value in self._numbers("ERST?", 2))
        self._check_ramp_segments()
        if self._update_arm_problem(self.xpgm, hardware, operational):
            raise RuntimeError(f"The {self.short_label} is not armed: {self.arm_problem}; no setpoint was sent")
    def _update_reading(self, current, voltage, opst, hardware, operational) -> dict[str, object]:
        setpoint = self.setpoint_a
        self.current_a, self.voltage_v = current, voltage
        at_zero = math.isfinite(setpoint) and abs(setpoint) < LAKESHORE_SETPOINT_READBACK_A and (abs(current) <= self.tolerance_a(0.0))
        self.output_on = not at_zero
        at_setpoint = math.isfinite(setpoint) and abs(current - setpoint) <= self.tolerance_a(setpoint)
        self.reading = dict(
            model=self.short_label, setpoint_a=setpoint, current_a=current, voltage_v=voltage, opst=int(opst),
            ramping=not at_setpoint, at_setpoint=at_setpoint,
            compliance=bool(opst & LAKESHORE_OPST_COMPLIANCE), power_limit=bool(opst & LAKESHORE_OPST_POWER_LIMIT),
            hardware_errors=int(hardware), operational_errors=int(operational),
            errors=lakeshore_error_names(hardware, operational),
            errors_blocking=lakeshore_blocking_errors(hardware, operational), output_on=self.output_on)
        return dict(self.reading)
    def read_state(self) -> dict[str, object]:
        with self.lock:
            self.setpoint_a = self._number("SETI?")
            current = self._number("RDGI?")
            voltage = self._number("RDGV?")
            opst = int(self._number("OPST?"))
            hardware, operational = (int(value) for value in self._numbers("ERST?", 2))
            return self._update_reading(current, voltage, opst, hardware, operational)
    def read_current(self) -> float:
        with self.lock:
            self.current_a = self._number("RDGI?")
            return self.current_a
    def describe(self) -> dict[str, object]:
        return dict(model=self.short_label, label=self.label, identity=self.identity, resource=self.resource_name,
                    connected=self.connected, program_max_a=self.program_max_a,
                    limit_current_a=self.limit_current_a, limit_rate_a_s=self.limit_rate_a_s,
                    effective_max_a=self.effective_max_a, effective_max_rate_a_s=self.effective_max_rate_a_s,
                    instrument_rate_a_s=self.rate_a_s,
                    programming_mode=LAKESHORE_XPGM_MODES.get(self.xpgm, self.xpgm),
                    magnet_water=LAKESHORE_WATER_MODES.get(self.magnet_water, self.magnet_water),
                    internal_water=LAKESHORE_WATER_MODES.get(self.internal_water, self.internal_water),
                    instrument_rate_at_connect_a_s=self.connect_rate_a_s,
                    ramp_segments=self.ramp_segments,
                    ramp_segment_table=[list(entry) for entry in self.ramp_segment_table],
                    setpoint_tolerance=lakeshore_tolerance_text(self.model),
                    arm_problem=self.arm_problem, reading=dict(self.reading))
    def _set_rate(self, rate: float) -> None:
        present = self._number("RATE?")
        if abs(present - rate) > LAKESHORE_RATE_READBACK_A_S:
            self._write(f"RATE {rate:.4f}")
            present = self._number("RATE?")
            if abs(present - rate) > LAKESHORE_RATE_READBACK_A_S:
                self.rate_a_s = present
                raise LakeShoreRampError(f'{self.short_label} RATE? read back {present:g} A/s after RATE {rate:.4f}; no setpoint was sent', self.current_a)
        self.rate_a_s = present
        self.program_rate_a_s = rate
    def _stop_ramp(self, target: float) -> tuple[float, str]:
        try:
            self._write("STOP")
            said = "STOP sent"
        except Exception as error:
            self.logger(f"{self.owner_scope} {self.short_label}: STOP failed: {error}")
            said = f'STOP could not be sent: {short_status_error(error, 60)}; the supply may still be ramping to {target:+g} A'
        self.output_on = True
        self.sleep(LAKESHORE_STOP_SETTLE_S)
        try:
            self.current_a = self._number("RDGI?")
        except Exception as error:
            self.logger(f"{self.owner_scope} {self.short_label}: RDGI? after STOP failed: {error}")
            return math.nan, said
        return self.current_a, said
    def ramp_to(self, target_a, rate_a_s, stop_event=None, on_progress=None) -> dict[str, object]:
        target = round(self.check_current(target_a), 3)
        rate = self.check_rate(rate_a_s)
        with self.lock:
            self._require()
            if self._stopped(stop_event):
                raise LakeShoreRampStopped(f'{self.short_label} ramp to {target:+g} A not started: Stop requested; nothing was sent', self.current_a)
            self._require_armed()
            setpoint = self._number("SETI?")
            start = self._number("RDGI?")
            self.current_a = start
            if abs(setpoint - target) < LAKESHORE_SETPOINT_READBACK_A and abs(start - target) <= self.tolerance_a(target):
                self.setpoint_a = setpoint
                voltage = self._number("RDGV?")
                opst = int(self._number("OPST?"))
                hardware, operational = (int(value) for value in self._numbers("ERST?", 2))
                reading = self._update_reading(start, voltage, opst, hardware, operational)
                self.last_ramp = dict(target_a=target, start_a=start, rate_a_s=rate, seconds=0.0, current_a=start, voltage_v=voltage, sent=False)
                return reading
            self._set_rate(rate)
            if self._stopped(stop_event):
                raise LakeShoreRampStopped(f'{self.short_label} ramp to {target:+g} A not started: Stop requested; no setpoint was sent', start)
            self._number("OPST?")
            self.output_on = True
            self._write(f"SETI {target:.3f}")
            try:
                readback = self._number("SETI?")
            except Exception as error:
                where, said = self._stop_ramp(target)
                raise LakeShoreRampError(f'{self.short_label} SETI? after SETI {target:.3f} failed ({error}); {said}, output at {where:+.3f} A', where) from error
            if abs(readback - target) >= LAKESHORE_SETPOINT_READBACK_A:
                self.setpoint_a = readback
                where, said = self._stop_ramp(target)
                raise LakeShoreRampError(f'{self.short_label} SETI? read back {readback:+.3f} A after SETI {target:.3f}; {said}, output at {where:+.3f} A', where)
            self.setpoint_a = readback
            return self._wait_for(target, start, rate, stop_event, on_progress, zeroing=False)
    def _wait_for(self, target, start, rate, stop_event, on_progress, *, zeroing: bool) -> dict[str, object]:
        timeout = self.ramp_timeout_s(start, target, rate)
        began = self.clock()
        tolerance = self.tolerance_a(target)
        notes = []
        ramp_done_seen = False
        while True:
            if not zeroing and self._stopped(stop_event):
                where, said = self._stop_ramp(target)
                raise LakeShoreRampStopped(f'{self.short_label} ramp to {target:+g} A stopped: {said}, output at {where:+.3f} A', where)
            current = self._number("RDGI?")
            voltage = self._number("RDGV?")
            opst = int(self._number("OPST?"))
            hardware, operational = (int(value) for value in self._numbers("ERST?", 2))
            reading = self._update_reading(current, voltage, opst, hardware, operational)
            if on_progress is not None:
                try:
                    on_progress(dict(reading))
                except Exception:
                    pass
            problems = list(reading["errors_blocking"])
            if reading["compliance"]:
                problems.append("in compliance (OPST?)")
            if reading["power_limit"]:
                problems.append("in power limit (OPST?)")
            if problems and not zeroing:
                where, said = self._stop_ramp(target)
                raise LakeShoreRampError(
                    f"{self.short_label} ramp to {target:+g} A ended: {', '.join(problems)} (OPST? {opst}, ERST? "
                    f"{hardware},{operational}); {said}, output at {where:+.3f} A; no further setpoint is "
                    "sent", where)
            if problems:
                note = ", ".join(problems)
                if note not in notes:
                    notes.append(note)
            ramp_done_seen = ramp_done_seen or bool(opst & LAKESHORE_OPST_RAMP_DONE)
            if abs(current - target) <= tolerance and (zeroing or ramp_done_seen):
                self.last_ramp = dict(target_a=target, start_a=start, rate_a_s=rate, seconds=self.clock() - began, current_a=current, voltage_v=voltage)
                if zeroing:
                    self.last_zero_notes = notes
                return reading
            if self.clock() - began > timeout:
                if zeroing:
                    raise LakeShoreZeroError(f'{self.short_label} zero not confirmed: RDGI? {current:+.3f} A after {timeout:.0f} s' + (f" ({'; '.join(notes)})" if notes else ''), current)
                where, said = self._stop_ramp(target)
                raise LakeShoreRampError(
                    f"{self.short_label} did not reach {target:+g} A within {timeout:.0f} s (RDGI? {current:+.3f} A, "
                    f"OPST? {opst}{'' if ramp_done_seen else ', ramp done never seen'}); {said}, "
                    f"output at {where:+.3f} A", where)
            self.sleep(LAKESHORE_POLL_S)
    def ramp_timeout_s(self, start, target, rate) -> float:
        distance = abs(target - start) if math.isfinite(start) else self.effective_max_a
        return distance / rate * LAKESHORE_RAMP_TIME_FACTOR + LAKESHORE_RAMP_MARGIN_S
    def zero_rate_a_s(self, rate_a_s=None, minimum_rate_a_s=None) -> float:
        try:
            rate = float(rate_a_s if rate_a_s is not None else self.program_rate_a_s or LAKESHORE_DEFAULT_RATE_A_S)
        except (TypeError, ValueError):
            rate = LAKESHORE_DEFAULT_RATE_A_S
        if not math.isfinite(rate) or rate < LAKESHORE_MIN_RATE_A_S:
            rate = LAKESHORE_DEFAULT_RATE_A_S
        if math.isfinite(self.connect_rate_a_s) and self.connect_rate_a_s > 0:
            rate = min(rate, self.connect_rate_a_s)
        rate = min(rate, self.effective_max_rate_a_s)
        if minimum_rate_a_s is not None:
            rate = max(rate, float(minimum_rate_a_s))
        return max(rate, LAKESHORE_MIN_RATE_A_S)
    def zero(self, rate_a_s=None, minimum_rate_a_s=None) -> dict[str, object]:
        with self.lock:
            self._stop_request.clear()
            self._require()
            rate = self.zero_rate_a_s(rate_a_s, minimum_rate_a_s)
            problems = []
            start = math.nan
            try:
                self.setpoint_a = self._number("SETI?")
                start = self.current_a = self._number("RDGI?")
            except Exception as error:
                problems.append(f"read before the zero: {short_status_error(error, 60)}")
            if not problems and abs(self.setpoint_a) < LAKESHORE_SETPOINT_READBACK_A and (abs(start) <= self.tolerance_a(0.0)):
                self.output_on = False
                self.last_zero_notes = []
                self.reading = dict(self.reading, setpoint_a=self.setpoint_a, current_a=start, output_on=False, at_setpoint=True, ramping=False)
                return dict(self.reading)
            self.output_on = True
            expected = abs(start) / rate if math.isfinite(start) else math.nan
            self.logger(f"{self.owner_scope} {self.short_label}: ramping to 0 A at {rate:g} A/s"
                        + (f" from {start:+.3f} A, about {expected:.0f} s" if math.isfinite(expected) else "")
                        + f" (waited for at most {self.ramp_timeout_s(start, 0.0, rate):.0f} s)")
            try:
                self._set_rate(rate)
            except Exception as error:
                problems.append(f"RATE: {short_status_error(error, 60)}")
            try:
                self._write("SETI 0.000")
                self.setpoint_a = self._number("SETI?")
            except Exception as error:
                problems.append(f"SETI 0: {short_status_error(error, 60)}")
            try:
                reading = self._wait_for(0.0, start, rate, None, None, zeroing=True)
                self.setpoint_a = self._number("SETI?")
            except Exception as error:
                raise LakeShoreZeroError(f'{error}' + (f"; {'; '.join(problems)}" if problems else ''), getattr(error, 'current_a', self.current_a)) from error
            if abs(self.setpoint_a) >= LAKESHORE_SETPOINT_READBACK_A:
                self.output_on = True
                raise LakeShoreZeroError(f'{self.short_label} zero not confirmed: SETI? reads {self.setpoint_a:+.3f} A', self.current_a)
            reading = self._update_reading(reading['current_a'], reading['voltage_v'], reading['opst'], reading['hardware_errors'], reading['operational_errors'])
            if problems:
                self.logger(f"{self.owner_scope} {self.short_label} zeroed, after: {'; '.join(problems)}")
            return reading
    def _close_session(self) -> None:
        instrument, manager, resource_name = self.instrument, self.resource_manager, self.resource_name
        if instrument is not None:
            try:
                instrument.close()
            except BaseException:
                pass
        release_shared_visa_manager(manager)
        self.instrument = None
        self.resource_manager = None
        self.resource_name = ""
        self.identity = ""
        release_instrument_lease(resource_name, self)
    def safe_output_off(self) -> None:
        if self.instrument is not None:
            self.zero()
    def disconnect(self, closing: bool = False) -> None:
        with self.lock:
            if self.instrument is None and self.resource_manager is None:
                return
            failure = None
            if self.instrument is not None:
                try:
                    self.zero(minimum_rate_a_s=LAKESHORE_CLOSE_MIN_RATE_A_S if closing else None)
                except BaseException as error:
                    failure = error
            self._close_session()
            self.logger(f'{self.owner_scope} {self.label} disconnected' + ('' if failure is None else '; its zero was NOT confirmed'))
            if failure is not None:
                raise RuntimeError(f"{self.label} disconnected, but zero FAILED: {failure}: check it") from failure
class MagnetSupply:
    def __init__(self, kepco, lakeshore=None, *, use_lakeshore: bool=False, rate_a_s=None, stop_event=None, stopped=None, on_progress=None) -> None:
        self.kepco = kepco
        self.lakeshore_controller = lakeshore
        self.use_lakeshore = bool(use_lakeshore and lakeshore is not None)
        self.rate_a_s = LAKESHORE_DEFAULT_RATE_A_S if rate_a_s is None else float(rate_a_s)
        self.stop_event = stop_event
        self.stopped = stopped
        self.on_progress = on_progress
    @property
    def lakeshore(self) -> bool:
        return self.use_lakeshore
    @property
    def controller(self):
        return self.lakeshore_controller if self.use_lakeshore else self.kepco
    @property
    def name(self) -> str:
        return self.lakeshore_controller.short_label if self.use_lakeshore else MAGNET_SUPPLY_KEPCO
    @property
    def label(self) -> str:
        return self.lakeshore_controller.short_label if self.use_lakeshore else "KEPCO"
    @property
    def connected(self) -> bool:
        controller = self.controller
        return controller is not None and bool(getattr(controller, "connected", False))
    @property
    def output_on(self) -> bool:
        controller = self.controller
        if controller is None:
            return False
        return bool(getattr(controller, "output_on" if self.use_lakeshore else "output_owned", False))
    def max_current_a(self) -> float:
        if self.use_lakeshore:
            return float(self.lakeshore_controller.effective_max_a)
        return STFMR_KEPCO_MAX_CURRENT_A
    def _ramp(self, current_a):
        try:
            return self.lakeshore_controller.ramp_to(current_a, self.rate_a_s, self.stop_event, self.on_progress)
        except LakeShoreRampStopped as error:
            if self.stopped is not None:
                raise self.stopped(error) from error
            raise
    def start(self, current_a, voltage_limit_v):
        if self.use_lakeshore:
            return self._ramp(current_a)
        return self.kepco.set_output("CURR", current_a, voltage_limit_v)
    def step(self, current_a):
        if self.use_lakeshore:
            return self._ramp(current_a)
        return self.kepco.set_scan_current(current_a)
    def zero(self):
        if self.use_lakeshore:
            return self.lakeshore_controller.zero(self.rate_a_s)
        return self.kepco.force_output_off()
    def programmed_current_a(self):
        if self.use_lakeshore:
            value = getattr(self.lakeshore_controller, "setpoint_a", math.nan)
            return value if isinstance(value, (int, float)) and math.isfinite(value) else ""
        return self.kepco.cached_current_a if self.kepco.output_owned else ""
    def measured_current_a(self, fresh: bool = False):
        if not self.use_lakeshore:
            return ""
        value = self.lakeshore_controller.read_current() if fresh else getattr(self.lakeshore_controller, 'current_a', math.nan)
        return value if isinstance(value, (int, float)) and math.isfinite(value) else ""
class MagnetFieldError(RuntimeError):
    pass
class MagnetFieldStopped(RuntimeError):
    pass
class MagnetFieldPID:
    def __init__(self, target_g, tolerance_g, max_current_a, *, supply: str='magnet supply', kp: float=MAGNET_FIELD_SET_KP, ki: float=MAGNET_FIELD_SET_KI, kd: float=MAGNET_FIELD_SET_KD) -> None:
        self.target_g, self.tolerance_g = float(target_g), abs(float(tolerance_g))
        self.max_current_a = abs(float(max_current_a))
        if not math.isfinite(self.target_g):
            raise ValueError("The target field must be a finite number of G")
        if not math.isfinite(self.tolerance_g) or self.tolerance_g <= 0.0:
            raise ValueError("The field tolerance must be above 0 G")
        if not math.isfinite(self.max_current_a) or self.max_current_a <= 0.0:
            raise ValueError("The magnet supply's maximum current is not known")
        self.supply = str(supply)
        self.kp, self.ki, self.kd = float(kp), float(ki), float(kd)
        self.slope_g_per_a: float | None = None
        self.anchor: tuple[float, float, float] | None = None
        self.errors: list[float] = []
        self.steps = 0
        self.corrections = 0
        self.probes = 0
        self.reached = False
        self.reached_current_a: float | None = None
        self.hold_travel_a = math.inf
        self.span_g = abs(self.target_g)
        self.confirmed = False
        self.step_limit_a = MAGNET_FIELD_SET_MAX_STEP_A
        self.step_limit_max_a = max(MAGNET_FIELD_SET_MAX_STEP_A, MAGNET_FIELD_SET_MAX_STEP_FRACTION * self.max_current_a)
        self.max_steps = MAGNET_FIELD_SET_EXTRA_STEPS + math.ceil(self.max_current_a / MAGNET_FIELD_SET_MAX_STEP_A)
    def update(self, current_a, field_g, scatter_g: float = 0.0) -> float | None:
        current, field = float(current_a), float(field_g)
        if not math.isfinite(current) or not math.isfinite(field):
            raise MagnetFieldError(f"The gaussmeter reading at {current:+g} A is not a number ({field!r})")
        scatter = abs(float(scatter_g))
        if not math.isfinite(scatter):
            scatter = 0.0
        error = self.target_g - field
        self.errors = (self.errors + [error])[-3:]
        if abs(error) <= self.tolerance_g:
            self.reached, self.corrections = True, 0
            if self.reached_current_a is None:
                self.reached_current_a = current
                self.hold_travel_a = max(MAGNET_FIELD_HOLD_MIN_TRAVEL_A, MAGNET_FIELD_HOLD_TRAVEL_FRACTION * abs(current))
            self.anchor = (current, field, scatter)
            self.step_limit_a = MAGNET_FIELD_SET_MAX_STEP_A
            return None
        if self.reached and self.anchor is not None and (abs(current - self.anchor[0]) < 0.5 * MAGNET_FIELD_SET_RESOLUTION_A) and (abs(field - self.anchor[1]) > self._jump_g(self.anchor[1])):
            raise MagnetFieldError(
                f"The field reading changed by {field - self.anchor[1]:+.4g} G (from {self.anchor[1]:+.6g} G to "
                f"{field:+.6g} G) while the {self.supply} current stayed at {current:+g} A. The current is not "
                "changed. The gaussmeter may not be working, or its probe has moved or changed range: check it "
                "before setting the field again")
        if self.corrections >= self.max_steps:
            raise MagnetFieldError(f'Target {self.target_g:+g} G ± {self.tolerance_g:g} G not reached after {self.corrections} corrections; the field at {current:+g} A is {field:+.6g} G')
        self.steps += 1
        self.corrections += 1
        if self.anchor is None:
            self.anchor = (current, field, scatter)
            self.span_g = max(self.span_g, abs(field))
        else:
            self._learn(current, field, scatter)
        if self.slope_g_per_a is None:
            return self._probe(current, field, scatter)
        return self._correct(current, field, error)
    def _jump_g(self, field: float) -> float:
        return max(MAGNET_FIELD_HOLD_JUMP_TOLERANCES * self.tolerance_g, MAGNET_FIELD_HOLD_JUMP_SCATTERS * max(self.tolerance_g, MAGNET_FIELD_SET_SETTLE_REL_TOLERANCE * abs(field)))
    def _learn(self, current: float, field: float, scatter: float) -> None:
        anchor_a, anchor_g, anchor_scatter = self.anchor
        delta_a, delta_g = current - anchor_a, field - anchor_g
        if abs(delta_a) < 0.5 * MAGNET_FIELD_SET_RESOLUTION_A:
            self.anchor = (current, field, scatter)
            return
        floor = max(MAGNET_FIELD_SET_MIN_RESPONSE_G, 5.0 * max(scatter, anchor_scatter))
        if self.slope_g_per_a is None:
            if abs(delta_g) < floor:
                return
            slope = delta_g / delta_a
            if abs(slope) < MAGNET_FIELD_SET_MIN_G_PER_A:
                raise MagnetFieldError(
                    f"The gaussmeter sees only {abs(slope):.3g} G per A of the {self.supply} current ({delta_g:+.3g} G "
                    f"for {delta_a:+.3f} A), under the {MAGNET_FIELD_SET_MIN_G_PER_A:g} G per A a probe in the "
                    "magnet's gap gives. The gaussmeter may not be working, or its probe is not in this magnet's gap")
            self.slope_g_per_a, self.anchor = slope, (current, field, scatter)
            return
        expected = self.slope_g_per_a * delta_a
        here_g = min(max(abs(field), abs(anchor_g)), self.span_g)
        enough = max(2.0 * floor, 5.0 * self.tolerance_g, MAGNET_FIELD_SET_CHECK_FIELD_FRACTION * here_g)
        if abs(expected) < enough:
            return
        self.anchor = (current, field, scatter)
        ratio = delta_g / expected
        if ratio < MAGNET_FIELD_SET_MIN_RESPONSE_RATIO:
            raise MagnetFieldError(
                f"The {self.supply} current was changed by {delta_a:+.3f} A and the field did not respond: it "
                f"should have changed by about {expected:+.4g} G and changed by {delta_g:+.4g} G. The current is not "
                "changed further. The gaussmeter may not be working: check that it is on, on a range that holds "
                "this field, and that its probe is in this magnet's gap (or the magnet is saturating, or the "
                "supply's output is limited at its front panel)")
        slope = delta_g / delta_a
        if abs(slope) < MAGNET_FIELD_SET_MIN_G_PER_A:
            raise MagnetFieldError(
                f"The field now changes by only {abs(slope):.3g} G per A of the {self.supply} current ({delta_g:+.4g} G "
                f"for {delta_a:+.3f} A), under the {MAGNET_FIELD_SET_MIN_G_PER_A:g} G per A a probe in the magnet's "
                "gap gives. The gaussmeter may not be working, its probe is not in this magnet's gap, or the "
                "magnet is saturating")
        if ratio < 0.7:
            self.step_limit_a = MAGNET_FIELD_SET_MAX_STEP_A
            return
        self.slope_g_per_a = slope
        if ratio <= 1.3:
            self.confirmed = True
            self.step_limit_a = min(2.0 * self.step_limit_a, self.step_limit_max_a)
        else:
            self.step_limit_a = MAGNET_FIELD_SET_MAX_STEP_A
    def _probe(self, current: float, field: float, scatter: float) -> float:
        if self.probes >= len(MAGNET_FIELD_SET_PROBES_A):
            floor = max(MAGNET_FIELD_SET_MIN_RESPONSE_G, 5.0 * max(scatter, self.anchor[2]))
            raise MagnetFieldError(
                f"The {self.supply} current was changed by {current - self.anchor[0]:+.3f} A and the field did not "
                f"respond: it changed by {field - self.anchor[1]:+.3g} G (it reads {field:+.6g} G at {current:+g} A; "
                f"a change under {floor:.3g} G does not count). The current is not changed further. The gaussmeter "
                "may not be working: check that it is on, on a range that holds this field, and that its probe "
                "is in this magnet's gap (or the magnet's wiring, or the supply's front panel)")
        size = MAGNET_FIELD_SET_PROBES_A[self.probes]
        self.probes += 1
        target = current + size
        if target > self.max_current_a:
            target = current - size
        if target < -self.max_current_a:
            raise MagnetFieldError(f"The {self.supply}'s ±{self.max_current_a:g} A leaves no room for a {size:g} A probe step from {current:+g} A")
        return round(target, 3)
    def _correct(self, current: float, field: float, error: float) -> float:
        previous = self.errors[-2] if len(self.errors) >= 2 else error
        before = self.errors[-3] if len(self.errors) >= 3 else previous
        action_g = self.kp * (error - previous) + self.ki * error + self.kd * (error - 2.0 * previous + before)
        slope = self.slope_g_per_a
        whole = error / slope
        if self.confirmed and abs(current + whole) > 1.25 * self.max_current_a:
            raise MagnetFieldError(
                f"Target {self.target_g:+g} G needs about {current + whole:+.3g} A at the measured "
                f"{slope:.4g} G/A, more than the {self.supply}'s ±{self.max_current_a:g} A; the field at "
                f"{current:+g} A is {field:+.6g} G")
        delta = max(-self.step_limit_a, min(self.step_limit_a, action_g / slope))
        resolution = MAGNET_FIELD_SET_RESOLUTION_A
        if abs(delta) < resolution:
            if abs(whole) < resolution:
                raise MagnetFieldError(
                    f"±{self.tolerance_g:g} G is finer than one setpoint step of the {self.supply}: 1 mA changes "
                    f"the field by about {abs(slope) * resolution:.3g} G. The field at {current:+g} A is "
                    f"{field:+.6g} G; use a larger tolerance")
            delta = math.copysign(resolution, whole)
        target = round(max(-self.max_current_a, min(self.max_current_a, current + delta)), 3)
        if self.reached_current_a is not None and abs(target - self.reached_current_a) > self.hold_travel_a:
            raise MagnetFieldError(
                f"While the field was held, the {self.supply} current has moved from the {self.reached_current_a:+g} A "
                f"at which {self.target_g:+g} G was first reached to {current:+g} A, and the next step would take it "
                f"more than {self.hold_travel_a:.3g} A away. A magnet's field does not drift that far at a constant "
                "current. The current is not changed further. The gaussmeter may not be working: its reading is "
                f"drifting or fading (it reads {field:+.6g} G), or its probe is moving out of the gap. Check it, "
                "then set the field again")
        if abs(target - current) < 0.5 * resolution:
            raise MagnetFieldError(f"Target {self.target_g:+g} G needs more than the {self.supply}'s ±{self.max_current_a:g} A; the field at {current:+g} A is {field:+.6g} G")
        return target
def magnet_field_stop_checks(stop_event, closing=None):
    def check() -> None:
        if stop_event.is_set() or (closing is not None and closing()):
            raise MagnetFieldStopped("the field setting was stopped")
    def wait(seconds: float) -> None:
        check()
        stop_event.wait(seconds)
        check()
    return check, wait
def read_settled_magnet_field(read_field_g, wait, tolerance_g) -> tuple[float, float]:
    group_s = (MAGNET_FIELD_SET_READINGS - 1) * MAGNET_FIELD_SET_READ_INTERVAL_S + MAGNET_FIELD_SET_GROUP_GAP_S
    groups = max(2, math.ceil(MAGNET_FIELD_SET_SETTLE_TIMEOUT_S / group_s))
    wait(MAGNET_FIELD_SET_SETTLE_S)
    before, change = None, math.nan
    for group in range(groups):
        if group:
            wait(MAGNET_FIELD_SET_GROUP_GAP_S)
        values = []
        for index in range(MAGNET_FIELD_SET_READINGS):
            if index:
                wait(MAGNET_FIELD_SET_READ_INTERVAL_S)
            values.append(float(read_field_g()))
        if not all(math.isfinite(value) for value in values):
            raise MagnetFieldError(f"The gaussmeter reading is not a number ({values!r})")
        mean, spread = sum(values) / len(values), max(values) - min(values)
        allowed = max(float(tolerance_g), MAGNET_FIELD_SET_SETTLE_REL_TOLERANCE * abs(mean))
        if before is not None:
            change = abs(mean - before[0])
            scatter = max(spread, before[1], change)
            if scatter <= allowed:
                return mean, scatter
        before = (mean, spread)
    readings = ", ".join(f"{value:+.6g}" for value in values)
    raise MagnetFieldError(
        f"The gaussmeter field did not settle within {MAGNET_FIELD_SET_SETTLE_TIMEOUT_S:g} s: the last readings are "
        f"{readings} G (a spread of {spread:.3g} G, and {change:.3g} G from the readings before them). It is still "
        f"changing, or noisier than the ±{float(tolerance_g):g} G tolerance: a larger tolerance, or less filtering "
        "or a steadier range on the gaussmeter, may be needed")
def magnet_field_reading(pid: MagnetFieldPID, current: float, field: float, scatter: float, target) -> dict:
    return dict(current_a=current, field_g=field, scatter_g=scatter, target_g=pid.target_g,
                tolerance_g=pid.tolerance_g, step=pid.steps, g_per_a=pid.slope_g_per_a,
                reached=target is None, holding=pid.reached, next_current_a=target)
def set_magnet_field(pid: MagnetFieldPID, start_current_a: float, set_current, read_field_g, wait, progress=None, hold: bool=False) -> dict[str, object]:
    current = float(start_current_a)
    while True:
        field, scatter = read_settled_magnet_field(read_field_g, wait, pid.tolerance_g)
        target = pid.update(current, field, scatter)
        reading = magnet_field_reading(pid, current, field, scatter, target)
        if progress is not None:
            progress(dict(reading))
        if target is None:
            if not hold:
                return reading
            wait(MAGNET_FIELD_HOLD_INTERVAL_S)
            continue
        set_current(target)
        current = target
def run_magnet_field_set(supply: MagnetSupply, gauss, target_g, tolerance_g, voltage_limit_v, stop_event, closing=None, progress=None, hold: bool=False) -> dict[str, object]:
    pid = MagnetFieldPID(target_g, tolerance_g, supply.max_current_a(), supply=supply.label)
    check, wait = magnet_field_stop_checks(stop_event, closing)
    def read_field_g() -> float:
        return float(STFMRGauss475Controller.value_in_gauss(gauss.read_field()))
    def set_current(value: float) -> None:
        if supply.lakeshore:
            check()
            supply.step(value)
            return
        with supply.kepco.lock:
            check()
            supply.step(value)
    try:
        if supply.lakeshore:
            check()
            state = supply.lakeshore_controller.read_state()
            start = float(state["setpoint_a"])
            if not math.isfinite(start):
                raise MagnetFieldError(f"The {supply.label}'s setpoint (SETI?) is not a number; nothing was sent")
            if not state.get("at_setpoint", False):
                raise MagnetFieldError(
                    f"The {supply.label} is not at its setpoint (SETI? {start:+.3f} A, output "
                    f"{float(state['current_a']):+.3f} A): Apply output or Zero / OFF it first, then set the "
                    "field; nothing was sent")
        else:
            kepco = supply.kepco
            with kepco.lock:
                check()
                if not kepco.output_owned:
                    supply.start(0.0, voltage_limit_v)
                elif kepco.active_mode != "CURR":
                    raise MagnetFieldError('The KEPCO 4886 output is on in voltage mode: Zero / OFF it first, then set the field; nothing was sent')
                start = float(kepco.cached_current_a)
        return set_magnet_field(pid, start, set_current, read_field_g, wait, progress, hold=hold)
    except LakeShoreRampStopped as stopped:
        raise MagnetFieldStopped(str(stopped)) from stopped
def magnet_field_reading_text(reading: dict) -> str:
    return f"I {float(reading['current_a']):+.4g} A, B {float(reading['field_g']):+.6g} G"
MAGNET_FIELD_SET_BUTTON_TEXT = "Set field"
MAGNET_FIELD_STOP_BUTTON_TEXT = "Stop hold"
MAGNET_FIELD_JUST_STOPPED_TEXT = "Field regulation has just stopped: press Set field again to start a new one"
def magnet_field_just_stopped(ended_at) -> bool:
    return ended_at is not None and time.monotonic() - float(ended_at) < MAGNET_FIELD_RESTART_LOCKOUT_S
class STFMRGauss475Controller(SafeVisaIdentityController):
    UNIT_LABELS = {1: "G", 2: "T", 3: "Oe", 4: "A/m"}
    def __init__(self, logger: Callable[[str], None]) -> None:
        super().__init__(logger, 'Lake Shore 475 gaussmeter', 'MODEL475', owner_scope='STFMR')
    def read_field(self) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("Lake Shore 475 is not connected")
            value = float(self.instrument.query("RDGFIELD?"))
            unit_code = int(float(self.instrument.query("UNIT?")))
            if not math.isfinite(value):
                raise RuntimeError("Lake Shore 475 readback contains non-finite values")
            return {'field': value, 'unit_code': unit_code, 'unit': self.UNIT_LABELS.get(unit_code, f'UNIT {unit_code}')}
    @staticmethod
    def value_in_gauss(result: dict[str, object]) -> float:
        value = float(result["field"])
        unit_code = int(result["unit_code"])
        factors = {1: 1.0, 2: 10000.0, 3: 1.0, 4: 4.0 * math.pi / 1000.0}
        if unit_code not in factors:
            raise RuntimeError(f"Cannot convert Lake Shore UNIT {unit_code} to G")
        return value * factors[unit_code]
SR830_DISPLAY_XY_COMMANDS = ("DDEF 1,0,0", "DDEF 2,0,0")
def show_sr830_x_and_y(instrument, logger=None, label: str = "SR830") -> bool:
    try:
        for command in SR830_DISPLAY_XY_COMMANDS:
            instrument.write(command)
        return True
    except Exception as error:
        if logger is not None:
            logger(f"{label}: the display was not set to X and Y: {error}")
        return False
class STFMRSR830Controller(SafeVisaIdentityController):
    def __init__(self, logger: Callable[[str], None]) -> None:
        super().__init__(logger, 'Stanford SR830', 'SR830', owner_scope='STFMR')
        self.reference_input = STFMR_LOCKIN_SR830_DEFAULT_REFERENCE_INPUT
        self.sensitivity_index = STFMR_LOCKIN_SR830_SENSITIVITY_CODE
        self.auto_range_enabled = True
        self.low_range_count = 0
        self.range_cooldown = 0
        self.overload_floor = 0
    def connect(self, resource_name: str) -> str:
        identity = super().connect(resource_name)
        with self.lock:
            if self.instrument is not None:
                show_sr830_x_and_y(self.instrument, self.logger, "STFMR SR830")
        return identity
    @staticmethod
    def _numbers(response: str, expected: int) -> list[float]:
        values = [float(item.strip()) for item in str(response).split(",")]
        if len(values) != expected or not all(math.isfinite(v) for v in values):
            raise RuntimeError(f"SR830 readback cannot be parsed: {response!r}")
        return values
    def configure(self, reference_input: str=STFMR_LOCKIN_SR830_DEFAULT_REFERENCE_INPUT, auto_range: bool=True, time_constant_code: int=STFMR_LOCKIN_SR830_TIME_CONSTANT_CODE) -> dict[str, object]:
        reference_input = str(reference_input).strip()
        if reference_input not in STFMR_LOCKIN_SR830_REFERENCE_INPUTS:
            choices = ", ".join(STFMR_LOCKIN_SR830_REFERENCE_INPUTS)
            raise ValueError(f"SR830 REF IN must be one of: {choices}")
        reference_slope = STFMR_LOCKIN_SR830_REFERENCE_INPUTS[reference_input]
        if time_constant_code not in STFMR_LOCKIN_SR830_TIME_CONSTANTS.values():
            raise ValueError(f"SR830 time constant code {time_constant_code!r} is not an 'SR830 TC' choice")
        time_constant_code = int(time_constant_code)
        auto_range = bool(auto_range)
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("SR830 is not connected")
            for command in (
                "*CLS",
                "FMOD 0",
                f"RSLP {reference_slope}",
                "HARM 1",
                "ISRC 0",
                "IGND 0",
                "ICPL 0",
                "ILIN 0",
                "SYNC 0",
                *((f"SENS {STFMR_LOCKIN_SR830_SENSITIVITY_CODE}",) if auto_range else ()),
                f"OFLT {time_constant_code}",
                "OFSL 1",
                "RMOD 1",
                *SR830_DISPLAY_XY_COMMANDS,
            ):
                self.instrument.write(command)
            actual_reference_mode = int(round(float(self.instrument.query('FMOD?').strip())))
            actual_reference_slope = int(round(float(self.instrument.query('RSLP?').strip())))
            actual_harmonic = int(round(float(self.instrument.query('HARM?').strip())))
            actual_sensitivity = int(round(float(self.instrument.query('SENS?').strip())))
            actual_time_constant = int(round(float(self.instrument.query('OFLT?').strip())))
            if actual_reference_mode != 0 or actual_reference_slope != reference_slope or actual_harmonic != 1:
                raise RuntimeError(f'SR830 REF IN configuration readback mismatch: FMOD={actual_reference_mode}, RSLP={actual_reference_slope}, HARM={actual_harmonic}')
            if auto_range and actual_sensitivity != STFMR_LOCKIN_SR830_SENSITIVITY_CODE:
                raise RuntimeError(f'SR830 initial sensitivity readback mismatch: requested SENS {STFMR_LOCKIN_SR830_SENSITIVITY_CODE}, readback {actual_sensitivity}')
            if not 0 <= actual_sensitivity < len(NONLOCAL_SR830_FULL_SCALE_V):
                raise RuntimeError(f"SR830 SENS? read back {actual_sensitivity}, not a sensitivity index (0-26)")
            if actual_time_constant != time_constant_code:
                raise RuntimeError(f'SR830 time constant readback mismatch: requested OFLT {time_constant_code}, readback {actual_time_constant}')
            self.reference_input = reference_input
            self.sensitivity_index = actual_sensitivity
            self.auto_range_enabled = auto_range
            self.low_range_count = 0
            self.range_cooldown = 0
            self.overload_floor = 0
            self.lias_clear_pending = True
            return {
                "reference_input": reference_input,
                "reference_slope": actual_reference_slope,
                "sensitivity_index": actual_sensitivity,
                "time_constant_index": actual_time_constant,
                "auto_range": self.auto_range_enabled,
            }
    def wait_for_reference(self, expected_frequency_hz: float, timeout_s: float=5.0, previous_frequency_hz: float | None=None) -> dict[str, object]:
        expected = float(expected_frequency_hz)
        if not math.isfinite(expected) or expected <= 0:
            raise ValueError("SR830 expected reference frequency must be a finite positive number")
        previous = None
        if previous_frequency_hz is not None:
            previous = float(previous_frequency_hz)
            if not math.isfinite(previous) or previous == expected:
                previous = None
        deadline = time.monotonic() + max(float(timeout_s), 0.1)
        frequency = math.nan
        status = 8
        while time.monotonic() < deadline:
            with self.lock:
                if self.instrument is None:
                    raise RuntimeError("SR830 is not connected")
                frequency = float(self.instrument.query("FREQ?").strip())
                status = int(round(float(self.instrument.query('LIAS?').strip())))
            left_previous = previous is None or abs(frequency - expected) < abs(frequency - previous)
            if not status & 8 and left_previous and math.isclose(frequency, expected, rel_tol=0.005, abs_tol=0.1):
                return {'frequency_hz': frequency, 'status': status, 'reference_input': self.reference_input}
            time.sleep(0.1)
        raise RuntimeError(
            f"SR830 REF IN not locked: selected {self.reference_input}, "
            f"expected {expected:g} Hz"
            + (f" (previous {previous:g} Hz)" if previous is not None else "")
            + f", readback {frequency:g} Hz, LIAS={status}; "
            "please confirm that SMB100A LFO OUTPUT is connected to SR830 REF IN, "
            "and select the Sine/TTL edge matching the waveform"
        )
    def _auto_range_locked(self, r_value: float, status: int, allow_down: bool=True) -> str:
        if not self.auto_range_enabled:
            return ""
        old = int(self.sensitivity_index)
        if not 0 <= old < len(NONLOCAL_SR830_FULL_SCALE_V):
            raise RuntimeError(f"SR830 current SENS index is invalid: {old}")
        utilization = abs(float(r_value)) / NONLOCAL_SR830_FULL_SCALE_V[old]
        requested = old
        reason = ""
        overloaded = bool(status & 0x07)
        floor = int(self.__dict__.get("overload_floor") or 0)
        if overloaded or utilization >= LOCKIN_UPRANGE_FRACTION:
            requested = min(old + 1, len(NONLOCAL_SR830_FULL_SCALE_V) - 1)
            reason = "overload/high"
            self.low_range_count = 0
        elif not allow_down:
            pass
        elif self.range_cooldown > 0:
            self.range_cooldown -= 1
            self.low_range_count = 0
        elif (utilization < LOCKIN_DOWNRANGE_FRACTION and old > floor and not status & 0x08):
            self.low_range_count += 1
            if self.low_range_count >= 3:
                requested = old - 1
                reason = "low"
                self.low_range_count = 0
        else:
            self.low_range_count = 0
        if requested == old:
            return ""
        self.instrument.write(f"SENS {requested}")
        actual = int(round(float(self.instrument.query('SENS?').strip())))
        if actual != requested:
            raise RuntimeError(f'SR830 auto-range readback mismatch: requested {requested}, readback {actual}')
        self.sensitivity_index = actual
        self.range_cooldown = 3
        self.lias_clear_pending = True
        if overloaded and actual > old and utilization < LOCKIN_UPRANGE_FRACTION:
            self.overload_floor = max(floor, actual)
        return f"SENS {old}->{actual} ({reason})"
    def new_pass(self) -> None:
        with self.lock:
            self.overload_floor = 0
            self.lias_clear_pending = True
    def auto_phase(self) -> float:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("SR830 is not connected")
            self.instrument.write("APHS")
            time.sleep(0.25)
            return float(self.instrument.query("PHAS?").strip())
    def read_sample(self, expected_frequency_hz: float, auto_range: bool=True, allow_down: bool=True) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("SR830 is not connected")
            x, y, r_value, theta, frequency = self._numbers(self.instrument.query('SNAP? 1,2,3,4,9'), 5)
            if self.__dict__.pop("lias_clear_pending", False):
                self.instrument.query("LIAS?")
            lias = int(round(float(self.instrument.query("LIAS?").strip())))
            sensitivity_used = int(self.sensitivity_index)
            auto_range_action = self._auto_range_locked(r_value, lias, allow_down) if auto_range else ''
        reference_valid = not lias & 8 and math.isclose(frequency, float(expected_frequency_hz), rel_tol=0.005, abs_tol=0.1)
        return {
            "x_v": x,
            "y_v": y,
            "r_v": r_value,
            "phase_deg": theta,
            "reference_frequency_hz": frequency,
            "reference_valid": reference_valid,
            "status": lias,
            "sensitivity_index": sensitivity_used,
            "sensitivity_full_scale_v": NONLOCAL_SR830_FULL_SCALE_V[
                sensitivity_used
            ],
            "auto_range": auto_range_action,
            "measurement_valid": bool(
                reference_valid and not (lias & 0x07) and not auto_range_action
            ),
        }
class QDCommandUncertain(RuntimeError):
    pass
class PPMSQDInstrumentReadbackController:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.instrument = None
        self.host = ""
        self.port = 0
        self.dll_path = ""
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    @staticmethod
    def candidate_dll_paths(explicit_path: str = "") -> tuple[Path, ...]:
        candidates: list[Path] = []
        for raw_path in (explicit_path, os.environ.get(PPMS_QDINSTRUMENT_DLL_ENV, '')):
            if str(raw_path).strip():
                candidates.append(Path(str(raw_path).strip().strip('"')))
        script_directory = Path(_PROGRAM_FILE).resolve().parent
        executable_directory = Path(sys.executable).resolve().parent
        working_directory = Path.cwd()
        candidates.extend(
            (
                script_directory / "QDInstrument.dll",
                script_directory / "QDInstrument" / "QDInstrument.dll",
                executable_directory / "QDInstrument.dll",
                executable_directory / "QDInstrument" / "QDInstrument.dll",
                working_directory / "QDInstrument.dll",
                working_directory / "QDInstrument" / "QDInstrument.dll",
                Path(r"C:\QDLabVIEW\QDInstrument.dll"),
                Path(r"C:\QDInstrument\QDInstrument.dll"),
                Path(r"C:\ProgramData\Quantum Design\QDInstrument\QDInstrument.dll"),
                Path(r"C:\Program Files\Quantum Design\QDInstrument\QDInstrument.dll"),
                Path(r"C:\Program Files (x86)\Quantum Design\QDInstrument\QDInstrument.dll"),
                Path(r"C:\Program Files\National Instruments\LabVIEW 2020\instr.lib\QDInstrument_LabView\QDInstrument.dll"),
                Path(r"C:\Program Files (x86)\National Instruments\LabVIEW 2020\instr.lib\QDInstrument_LabView\QDInstrument.dll"),
                Path(r"C:\Program Files\National Instruments\LabVIEW 2025\QDInstrument.dll"),
                Path(r"C:\Program Files (x86)\National Instruments\LabVIEW 2025\QDInstrument.dll"),
                Path(r"D:\user data\Niu Heng\QDInstrument.dll"),
                Path(r"D:\user data\Niu Heng\QDInstrument\QDInstrument.dll"),
            )
        )
        for raw_directory in (*sys.path, *os.environ.get('PATH', '').split(os.pathsep)):
            if str(raw_directory).strip():
                candidates.append(Path(str(raw_directory).strip().strip('"')) / 'QDInstrument.dll')
        unique: list[Path] = []
        seen: set[str] = set()
        for path in candidates:
            key = str(path).casefold()
            if key not in seen:
                seen.add(key)
                unique.append(path)
        return tuple(unique)
    @staticmethod
    def _windows_discovery_roots() -> tuple[Path, ...]:
        roots: list[Path] = []
        for variable in ('USERPROFILE', 'PUBLIC', 'PROGRAMDATA', 'ProgramFiles', 'ProgramFiles(x86)'):
            raw = os.environ.get(variable, "").strip()
            if not raw:
                continue
            base = Path(raw)
            if variable in ("USERPROFILE", "PUBLIC"):
                roots.extend((base / "Desktop", base / "Documents"))
            elif variable == "PROGRAMDATA":
                roots.append(base / "Quantum Design")
            else:
                roots.extend((base / 'Quantum Design', base / 'National Instruments'))
        roots.extend((Path('C:\\QDInstrument'), Path('C:\\QDLabVIEW'), Path('D:\\user data\\Niu Heng')))
        unique: list[Path] = []
        seen: set[str] = set()
        for root in roots:
            key = str(root).casefold()
            if key not in seen:
                seen.add(key)
                unique.append(root)
        return tuple(unique)
    @classmethod
    def discover_dll_paths(cls, explicit_path: str='', *, recursive: bool=False, time_limit_s: float=8.0, max_results: int=8) -> tuple[Path, ...]:
        matches: list[Path] = []
        seen: set[str] = set()
        def add(path: Path) -> bool:
            try:
                if not path.is_file():
                    return False
                resolved = path.resolve()
            except (OSError, RuntimeError):
                return False
            key = str(resolved).casefold()
            if key in seen:
                return False
            seen.add(key)
            matches.append(resolved)
            return len(matches) >= max(1, int(max_results))
        for path in cls.candidate_dll_paths(explicit_path):
            if add(path):
                return tuple(matches)
        if not recursive or not sys.platform.startswith("win"):
            return tuple(matches)
        deadline = time.monotonic() + max(0.5, float(time_limit_s))
        skipped_names = {'$recycle.bin', '.git', '.svn', 'appdata', 'cache', 'node_modules', 'site-packages', 'temp', 'windowsapps'}
        for root in cls._windows_discovery_roots():
            if time.monotonic() >= deadline:
                break
            try:
                if not root.is_dir():
                    continue
                root_depth = len(root.parts)
                for current, directory_names, file_names in os.walk(root):
                    if time.monotonic() >= deadline:
                        break
                    current_path = Path(current)
                    depth = len(current_path.parts) - root_depth
                    directory_names[:] = [name for name in directory_names if name.casefold() not in skipped_names and (not name.startswith('.'))]
                    if depth >= 7:
                        directory_names[:] = []
                    for file_name in file_names:
                        if file_name.casefold() == "qdinstrument.dll":
                            if add(current_path / file_name):
                                return tuple(matches)
            except (OSError, PermissionError):
                continue
        return tuple(matches)
    @classmethod
    def locate_dll(cls, explicit_path: str = "") -> Path:
        candidates = cls.candidate_dll_paths(explicit_path)
        matches = cls.discover_dll_paths(explicit_path)
        if matches:
            return matches[0]
        checked = "\n".join(f"  - {path}" for path in candidates)
        raise RuntimeError(
            "QDInstrument.dll was not found. Please select that DLL from the currently available LabVIEW QDInstrument "
            "directory, or set the environment variable "
            f"{PPMS_QDINSTRUMENT_DLL_ENV}. Checked:\n{checked}"
        )
    @staticmethod
    def _import_qdinstrument_api():
        from QuantumDesign.QDInstrument import QDInstrumentBase, QDInstrumentFactory
        return QDInstrumentBase, QDInstrumentFactory
    @classmethod
    def _load_qdinstrument_api(cls, clr, explicit_path: str = ""):
        attempts: list[str] = []
        for dll in cls.discover_dll_paths(explicit_path):
            try:
                clr.AddReference(str(dll))
                api = cls._import_qdinstrument_api()
                return (*api, str(dll))
            except BaseException as error:
                attempts.append(f"{dll}: {error}")
        try:
            clr.AddReference("QDInstrument")
            api = cls._import_qdinstrument_api()
            return (*api, ".NET auto-resolved: QDInstrument")
        except BaseException as error:
            attempts.append(f".NET assembly name QDInstrument: {error}")
        for dll in cls.discover_dll_paths(explicit_path, recursive=True, time_limit_s=8.0):
            try:
                clr.AddReference(str(dll))
                api = cls._import_qdinstrument_api()
                return (*api, str(dll))
            except BaseException as error:
                detail = f"{dll}: {error}"
                if detail not in attempts:
                    attempts.append(detail)
        explicit_note = ""
        if str(explicit_path).strip():
            explicit_note = f"\nManually entered path: {explicit_path}"
        attempt_text = "\n".join(f"  - {item}" for item in attempts[-8:])
        raise RuntimeError(
            "TCP 11000 being reachable only means QDInstrument_Server is listening; the local Python "
            "still needs the same QDInstrument.dll set as LabVIEW. The program tried loading by .NET assembly name, "
            "common program/LabVIEW directories and a time-limited automatic search, but did not succeed.\n"
            "Please locate QDInstrument.dll in an available LabVIEW project directory, or copy the DLL matching "
            "the LabVIEW/Server set into the main program directory."
            f"{explicit_note}\nLoad log:\n{attempt_text}"
        )
    @staticmethod
    def _normalize_readback(raw_result, quantity: str) -> tuple[float, str]:
        if isinstance(raw_result, tuple):
            values = list(raw_result)
        elif isinstance(raw_result, list):
            values = raw_result
        else:
            try:
                values = list(raw_result)
            except TypeError:
                values = [raw_result]
        if len(values) < 2:
            raise RuntimeError(f'QDInstrument {quantity} returned an unexpected format: {raw_result!r}')
        physical_value, status = values[-2], values[-1]
        try:
            physical_value = float(physical_value)
        except (TypeError, ValueError) as error:
            raise RuntimeError(f'QDInstrument {quantity} reading is not numeric: {physical_value!r}') from error
        if not math.isfinite(physical_value):
            raise RuntimeError(f'QDInstrument {quantity} returned a non-finite reading: {physical_value!r}')
        if len(values) >= 3:
            return_code = values[0]
            try:
                numeric_code = int(return_code)
            except (TypeError, ValueError):
                numeric_code = 0
            if numeric_code != 0:
                raise RuntimeError(f'QDInstrument {quantity} read failed, return code {numeric_code}')
        status_text = getattr(status, "name", None)
        if not status_text:
            try:
                status_text = status.ToString()
            except BaseException:
                status_text = str(status)
        return physical_value, str(status_text)
    @staticmethod
    def _reflection_signature(method) -> str:
        try:
            parameters = method.GetParameters()
            parts = []
            for parameter in parameters:
                parameter_type = parameter.ParameterType
                if bool(getattr(parameter_type, "IsByRef", False)):
                    parameter_type = parameter_type.GetElementType()
                    prefix = "ref "
                else:
                    prefix = ""
                type_name = getattr(parameter_type, "FullName", None)
                if not type_name:
                    type_name = str(parameter_type)
                parts.append(f"{prefix}{type_name}")
            return f"{method.Name}({', '.join(parts)})"
        except BaseException:
            return str(method)
    @classmethod
    def _invoke_ref_readback(cls, instrument, method_name: str):
        try:
            import System
        except ImportError as error:
            raise RuntimeError('pythonnet loaded QDInstrument.dll, but the System reflection interface cannot be imported') from error
        try:
            methods = [method for method in instrument.GetType().GetMethods() if str(method.Name) == str(method_name)]
        except BaseException as error:
            raise RuntimeError(f'Cannot reflect QDInstrument method {method_name}: {error}') from error
        if not methods:
            raise RuntimeError(f'The current QDInstrument.dll has no method {method_name}')
        def rank(method) -> tuple[int, int]:
            try:
                parameters = list(method.GetParameters())
            except BaseException:
                return (99, 99)
            ref_count = sum((bool(getattr(item.ParameterType, 'IsByRef', False)) for item in parameters))
            return (0 if len(parameters) == 2 else 1, -ref_count)
        errors: list[str] = []
        for method in sorted(methods, key=rank):
            signature = cls._reflection_signature(method)
            try:
                parameters = list(method.GetParameters())
                if len(parameters) != 2:
                    errors.append(f"{signature}: parameter count is not 2")
                    continue
                arguments = System.Array[System.Object](len(parameters))
                for index, parameter in enumerate(parameters):
                    parameter_type = parameter.ParameterType
                    if bool(getattr(parameter_type, "IsByRef", False)):
                        value_type = parameter_type.GetElementType()
                    else:
                        value_type = parameter_type
                    if bool(getattr(value_type, "IsEnum", False)):
                        value = System.Enum.ToObject(value_type, 0)
                    elif bool(getattr(value_type, "IsValueType", False)):
                        value = System.Activator.CreateInstance(value_type)
                    else:
                        value = None
                    arguments[index] = value
                return_value = method.Invoke(instrument, arguments)
                output_values = list(arguments)
                if return_value is not None:
                    output_values.insert(0, return_value)
                return tuple(output_values)
            except BaseException as error:
                errors.append(f"{signature}: {error}")
        details = "\n".join(f"  - {item}" for item in errors)
        raise RuntimeError(f'QDInstrument {method_name} ref/out call failed:\n{details}')
    @classmethod
    def _invoke_typed_command(cls, instrument, method_name: str, values):
        try:
            import System
        except ImportError as error:
            raise RuntimeError('pythonnet loaded QDInstrument.dll, but the System reflection interface cannot be imported') from error
        methods = [method for method in instrument.GetType().GetMethods() if str(method.Name) == str(method_name)]
        if not methods:
            raise RuntimeError(f"The current QDInstrument.dll has no method {method_name}")
        errors: list[str] = []
        for method in methods:
            invoked = False
            signature = cls._reflection_signature(method)
            try:
                parameters = list(method.GetParameters())
                if len(parameters) != len(values):
                    continue
                arguments = System.Array[System.Object](len(parameters))
                for index, (parameter, raw_value) in enumerate(zip(parameters, values)):
                    value_type = parameter.ParameterType
                    if bool(getattr(value_type, "IsByRef", False)):
                        value_type = value_type.GetElementType()
                    if bool(getattr(value_type, "IsEnum", False)):
                        converted = System.Enum.ToObject(value_type, int(raw_value))
                    else:
                        try:
                            converted = System.Convert.ChangeType(raw_value, value_type, System.Globalization.CultureInfo.InvariantCulture)
                        except BaseException:
                            converted = value_type(raw_value)
                    arguments[index] = converted
                invoked = True
                return_value = method.Invoke(instrument, arguments)
                return_type = getattr(method, "ReturnType", None)
                if str(getattr(return_type, "FullName", "")) == "System.Boolean":
                    if not bool(return_value):
                        raise RuntimeError("returned Boolean False")
                elif return_value is not None and int(return_value) != 0:
                    if int(return_value) == 1 and method_name in ("SetTemperature", "SetField"):
                        raise QDCommandUncertain(f"{method_name} return code 1; the command may have taken effect, not resending")
                    raise RuntimeError(f'return code {int(return_value)} (return type {return_type}); the command may have taken effect; please verify the MultiVu target and rate and do not resubmit')
                return return_value
            except BaseException as error:
                if invoked:
                    raise
                errors.append(f"{signature}: {error}")
        details = "\n".join(f"  - {item}" for item in errors)
        raise RuntimeError(f'QDInstrument {method_name} call failed:\n{details}')
    def connect(self, host: str, port: int, dll_path: str = "") -> dict[str, object]:
        host, port = PPMSMultiVuReadbackController.validate_endpoint(host, port)
        with self.lock:
            if self.instrument is not None:
                return self.read_environment()
            if not sys.platform.startswith("win"):
                raise RuntimeError("The QDInstrument remote interface can only be loaded on Windows")
            try:
                import clr
            except ImportError as error:
                raise RuntimeError('The current Python lacks pythonnet; please run:\npy -m pip install pythonnet') from error
            try:
                QDInstrumentBase, QDInstrumentFactory, load_source = self._load_qdinstrument_api(clr, dll_path)
                instrument = QDInstrumentFactory.GetQDInstrument(QDInstrumentBase.QDInstrumentType.PPMS, True, host, int(port))
            except BaseException as error:
                raise RuntimeError(
                    "Loading QDInstrument.dll or creating the remote PPMS session failed. Please confirm the DLL is not "
                    "blocked by Windows, that .NET Framework 3.5 is enabled on the ThinkPad, and that the same set of "
                    f"QDInstrument files as the lab PC is used. Original error: {error}"
                ) from error
            self.instrument = instrument
            self.host = host
            self.port = port
            self.dll_path = str(load_source)
            try:
                result = self.read_environment()
            except BaseException:
                self.disconnect()
                raise
            self.logger(f'PPMS QDInstrument connected: {host}:{port}; assembly={load_source}')
            return result
    def read_environment(self) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("PPMS QDInstrument is not connected")
            temperature_raw = self._invoke_ref_readback(self.instrument, 'GetTemperature')
            field_raw = self._invoke_ref_readback(self.instrument, "GetField")
        temperature_k, temperature_status = self._normalize_readback(temperature_raw, 'temperature')
        field_oe, field_status = self._normalize_readback(field_raw, "magnetic field")
        data = {'temperature_k': temperature_k, 'temperature_status': temperature_status, 'field_oe': field_oe, 'field_status': field_status}
        self._verify_environment_command(data)
        return data
    def _verify_environment_command(self, data):
        pending = getattr(self, "pending_environment_command", None)
        if not pending:
            return
        kind, target, deadline = pending
        temperature = kind == "SetTemperature"
        label = "Temperature" if temperature else "Magnetic field"
        measured = float(data["temperature_k" if temperature else "field_oe"])
        status = str(data["temperature_status" if temperature else "field_status"]).lower().replace(" ", "")
        stable = status in ('stable', 'stableattarget') if temperature else status in ('stable', 'holding', 'persistent', 'stablepersistent', 'stabledriven', 'standby')
        tolerance = .1 if temperature else max(PPMS_FIELD_TOLERANCE_OE, abs(target)*PPMS_FIELD_RELATIVE_TOLERANCE)
        if stable and abs(measured-target) <= tolerance:
            text = f"{label} reply uncertain; readback now confirms the target {target:g} was reached and is stable (rate not confirmed by readback)"
            self.pending_environment_command = None
        elif time.monotonic() >= deadline:
            text = f"{label} readback confirmation timed out; current {measured:g}, target {target:g}, please check MultiVu; not resent"
            self.pending_environment_command = None
        else:
            text = f"{label} reply uncertain, confirming by readback; target {target:g}, current {measured:g}; not resent"
        self.environment_command_status = text
        data["command_verification"] = text
    def _send_environment_command(self, name, values):
        self.pending_environment_command = None
        try:
            self._invoke_typed_command(self.instrument, name, values)
        except QDCommandUncertain as error:
            self.logger(str(error))
            self.pending_environment_command = (name, float(values[0]), time.monotonic() + (14400 if name == "SetTemperature" else 3600))
    def set_temperature(self, target_k: float, rate_k_min: float, approach_code: int) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("PPMS QDInstrument is not connected")
            current = self.read_environment()
            target_k, rate_k_min = validate_ppms_temperature_command(target_k, rate_k_min, float(current['temperature_k']))
            if int(approach_code) not in (0, 1):
                raise ValueError("PPMS temperature approach parameter is invalid")
            self._send_environment_command('SetTemperature', (target_k, rate_k_min, int(approach_code)))
            self.logger(f'PPMS temperature setpoint: {target_k:g} K, {rate_k_min:g} K/min')
            return self.read_environment()
    def set_field(self, target_oe: float, rate_oe_s: float, approach_code: int, mode_code: int) -> dict[str, object]:
        target_oe, rate_oe_s = validate_ppms_field_command(target_oe, rate_oe_s)
        if int(approach_code) not in (0, 1, 2):
            raise ValueError("PPMS field approach parameter is invalid")
        if int(mode_code) not in (0, 1):
            raise ValueError("PPMS field end mode parameter is invalid")
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("PPMS QDInstrument is not connected")
            self._send_environment_command('SetField', (target_oe, rate_oe_s, int(approach_code), int(mode_code)))
            self.logger(f'PPMS field setpoint: {target_oe:+g} Oe, {rate_oe_s:g} Oe/s, mode={int(mode_code)}')
            return self.read_environment()
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            self.instrument = None
            self.host = ""
            self.port = 0
            self.dll_path = ""
            if instrument is None:
                return
            for method_name in ("Dispose", "Close"):
                method = getattr(instrument, method_name, None)
                if callable(method):
                    try:
                        method()
                    except BaseException:
                        pass
                    break
            self.logger('PPMS QDInstrument client disconnected (current setpoints unchanged)')
class PPMSFieldScanError(RuntimeError):
    pass
class PPMSMotorScanError(RuntimeError):
    pass
class PPMSLockinRangeError(RuntimeError):
    pass
class PPMSScanCancelled(RuntimeError):
    pass
class PPMSMotorDebug:
    AXIS = "Horizontal Rotator"
    def __init__(self, controller):
        self.controller = controller
    def _method(self, name, count):
        instrument = self.controller.instrument
        if instrument is None:
            raise RuntimeError("Please connect QDInstrument first")
        methods = [m for m in instrument.GetType().GetMethods() if str(m.Name) == name and len(list(m.GetParameters())) == count]
        if len(methods) != 1:
            raise RuntimeError(f"{name}: no unique compatible interface found; please use 'Interface info' and send the log")
        return methods[0]
    def describe(self):
        with self.controller.lock:
            if self.controller.instrument is None:
                raise RuntimeError("Please connect QDInstrument first")
            lines = []
            for method in self.controller.instrument.GetType().GetMethods():
                if any(word in str(method.Name).lower() for word in ("position", "ppmsitem", "ppmscommand")):
                    lines.append(str(method))
                    for parameter in method.GetParameters():
                        typ = parameter.ParameterType
                        if getattr(typ, "IsByRef", False):
                            typ = typ.GetElementType()
                        if getattr(typ, "IsEnum", False):
                            import System
                            lines.append(f"  {typ}: " + ", ".join(str(n) for n in System.Enum.GetNames(typ)))
            return "\n".join(lines) or "No motor-related interface found"
    @staticmethod
    def _check_return(method, value):
        typ = str(getattr(getattr(method, "ReturnType", None), "FullName", ""))
        if typ == "System.Boolean":
            good = bool(value)
        else:
            good = value is None or int(value) == 0
        if not good:
            raise RuntimeError(f"{method}: returned {value!r} ({typ}); not resending, please verify in MultiVu whether it was executed")
    def _read_item(self, channel):
        import System
        with self.controller.lock:
            method = self._method("GetPPMSItem", 3)
            params = list(method.GetParameters())
            if (str(params[0].ParameterType.FullName) != "System.Int32"
                    or not getattr(params[1].ParameterType, "IsByRef", False)
                    or str(params[1].ParameterType.GetElementType().FullName) != "System.Double"
                    or str(params[2].ParameterType.FullName) != "System.Boolean"):
                raise RuntimeError(f"GetPPMSItem signature incompatible: {method}")
            arguments = System.Array[System.Object](3)
            arguments[0] = System.Int32(channel)
            arguments[1] = System.Double(0)
            arguments[2] = System.Boolean(True)
            result = method.Invoke(self.controller.instrument, arguments)
            self.controller.logger(f"PPMS motor GetPPMSItem({channel}): return={result!r}; value={arguments[1]!r}")
            self._check_return(method, result)
            value = float(arguments[1])
            if not math.isfinite(value):
                raise RuntimeError("PPMS data item is not a finite value")
            return value
    def read(self):
        with self.controller.lock:
            angle = self._read_item(3)
            status = "PositionUnknown"
            try:
                word = self._read_item(0)
                if not word.is_integer() or not 0 <= word <= 65535:
                    raise ValueError(f"Invalid status word: {word}")
                code = (int(word) >> 12) & 15
                status = {1: "AtTarget", 5: "Moving", 8: "AtLimitSwitch", 9: "AtIndexSwitch", 15: "PositionFailure"}.get(code, "PositionUnknown")
            except Exception as error:
                self.controller.logger(f"PPMS motor status unavailable: {error}")
            if not math.isfinite(angle):
                raise RuntimeError("Motor angle readback is not finite")
            self.controller.logger(f"PPMS motor: angle={angle:.6f} deg; status={status}")
            data = {"angle_deg": angle, "status": status}
            on_read = getattr(self, "on_read", None)
            if on_read is not None:
                on_read(dict(data))
            return data
    @staticmethod
    def validate_move(target, speed, current, allow_large=False):
        target, speed = float(target), float(speed)
        if not all(math.isfinite(v) for v in (target, speed, float(current))):
            raise ValueError("Motor parameters must be finite values")
        if not -370 <= target <= 370:
            raise ValueError("PPMS target angle must be within −370 to 370°")
        if abs(target - current) > 370.0 and not allow_large:
            raise ValueError("Each move must not exceed 370°; please enter the target based on the latest angle")
        if not speed.is_integer() or not 0 <= speed <= 14:
            raise ValueError("Deceleration code must be an integer 0–14; 0 fastest, 14 slowest")
        return target, int(speed)
    def move(self, target, speed, allow_large=False, _index_retry=False):
        import System
        self.movement_attempted = False
        with self.controller.lock:
            before = self.read()
            target, slowdown = self.validate_move(target, speed, before["angle_deg"], allow_large)
            if before["status"] not in ("AtTarget", "AtIndexSwitch"):
                raise RuntimeError(f"Motion status is not AtTarget: {before['status']}; MOVE not sent")
            method = self._method("SendPPMSCommand", 5)
            params = list(method.GetParameters())
            types_ = [p.ParameterType for p in params]
            expected = ["System.String", "System.String", "System.String", "System.Int32", "System.Double"]
            actual = [str((t.GetElementType() if getattr(t, "IsByRef", False) else t).FullName) for t in types_]
            if actual != expected or [bool(getattr(t, "IsByRef", False)) for t in types_] != [False, True, True, False, False]:
                raise RuntimeError(f"SendPPMSCommand signature incompatible: {method}")
            command = f"MOVE {target:.6f} 0 {slowdown}"
            args = System.Array[System.Object](5)
            args[0], args[1], args[2] = command, "", ""
            args[3], args[4] = System.Int32(0), System.Double(0)
            self.controller.logger(f"PPMS motor SEND ONCE: {command}")
            self.movement_attempted = True
            result = method.Invoke(self.controller.instrument, args)
            self.controller.logger(f"PPMS motor reply: return={result!r}; reply={args[1]!r}; error={args[2]!r}")
            return_type = str(getattr(method.ReturnType, "FullName", ""))
            ambiguous = return_type == "System.Int32" and int(result) == 1
            if not ambiguous:
                self._check_return(method, result)
            if str(args[1] or "").strip() or str(args[2] or "").strip():
                ambiguous = True
                self.controller.logger("MOVE reply is non-empty, execution result pending readback confirmation; MOVE not resent")
            return {'target_deg': target, 'return_code': result, 'ambiguous': ambiguous, 'raw_reply': str(args[1] or ''), 'raw_error': str(args[2] or '')}
    def move_and_verify(self, target, speed, cancelled=lambda: False, timeout=90.0, interval=0.5, allow_large=False, index_target=None):
        if cancelled():
            raise PPMSScanCancelled("Cancelled before moving, MOVE not sent; this does not mean the motor is stopped")
        submission = self.move(target, speed, allow_large=True) if allow_large else self.move(target, speed)
        deadline = time.monotonic() + timeout
        consecutive = 0
        last = None
        while time.monotonic() < deadline:
            if cancelled():
                raise PPMSScanCancelled("Arrival readback cancelled; this does not mean the motor is stopped, please check MultiVu")
            try:
                last = self.read()
            except Exception as error:
                raise RuntimeError(f"MOVE was sent, but the arrival readback failed and the motion status is unconfirmed; MOVE not resent, please check MultiVu: {error}") from error
            if last["status"] in ("AtLimitSwitch", "PositionFailure", "PositionUnknown"):
                raise RuntimeError(f"Abnormal motor status: {last}; MOVE not resent, please check MultiVu")
            if last["status"] in ("AtTarget", "AtIndexSwitch") and abs(last["angle_deg"] - submission["target_deg"]) <= 0.06:
                consecutive += 1
                if consecutive >= 2:
                    self.controller.logger(f"PPMS motor VERIFIED: {last}; submission={submission}")
                    return dict(last, **submission)
            else:
                consecutive = 0
            time.sleep(interval)
        raise RuntimeError(f"Motor arrival confirmation timed out ({timeout:g}s); last readback {last}; MOVE not resent, please check MultiVu")
class PPMSRemoteReadbackController:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.active = None
        self.backend = ""
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return self.active is not None and self.active.connected
    def connect(self, backend: str, host: str, port: int, dll_path: str='') -> dict[str, object]:
        with self.lock:
            if self.connected:
                return self.active.read_environment()
            if backend == PPMS_QDINSTRUMENT_BACKEND:
                controller = PPMSQDInstrumentReadbackController(self.logger)
                result = controller.connect(host, port, dll_path)
            elif backend == PPMS_MULTIPYVU_BACKEND:
                controller = PPMSMultiVuReadbackController(self.logger)
                result = controller.connect(host, port)
            else:
                raise ValueError(f"Unknown PPMS interface: {backend}")
            self.active = controller
            self.backend = backend
            return result
    def read_environment(self) -> dict[str, object]:
        with self.lock:
            if not self.connected:
                raise RuntimeError("PPMS remote interface is not connected")
            return self.active.read_environment()
    def set_temperature(self, target_k: float, rate_k_min: float, approach_code: int) -> dict[str, object]:
        with self.lock:
            if not self.connected:
                raise RuntimeError("PPMS remote interface is not connected")
            return self.active.set_temperature(target_k, rate_k_min, approach_code)
    def set_field(self, target_oe: float, rate_oe_s: float, approach_code: int, mode_code: int) -> dict[str, object]:
        with self.lock:
            if not self.connected:
                raise RuntimeError("PPMS remote interface is not connected")
            return self.active.set_field(target_oe, rate_oe_s, approach_code, mode_code)
    def disconnect(self) -> None:
        with self.lock:
            controller = self.active
            self.active = None
            self.backend = ""
            if controller is not None:
                controller.disconnect()
def _clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))
def calculate_window_layout(root: tk.Tk):
    screen_width = max(640, int(root.winfo_screenwidth()))
    screen_height = max(480, int(root.winfo_screenheight()))
    if sys.platform.startswith("win"):
        taskbar_reserve = 48
    elif sys.platform == "darwin":
        taskbar_reserve = 30
    else:
        taskbar_reserve = 42
    usable_height = max(400, screen_height - taskbar_reserve)
    edge = max(4, int(round(min(screen_width, screen_height) * 0.008)))
    gap = max(6, int(round(WINDOW_GAP)))
    wide_split = screen_width >= 1700
    if wide_split:
        control_width = int(round(screen_width * CONTROL_WIDTH_FRACTION))
        control_width = max(720, min(control_width, screen_width - 620 - gap))
        control_x = max(edge, screen_width - control_width - edge)
        camera_x = edge
        camera_width = max(600, control_x - gap - camera_x)
    else:
        control_x = edge
        camera_x = edge
        control_width = max(480, screen_width - 2 * edge)
        camera_width = control_width
    window_height = max(380, usable_height - edge)
    ui_scale = _clamp(min(control_width / 960.0, window_height / 1000.0), 0.72, 1.18)
    canvas_scale = _clamp(window_height / 1000.0, 0.62, 1.22)
    return {
        "camera": (camera_width, window_height, camera_x, edge),
        "control": (control_width, window_height, control_x, edge),
        "screen": (screen_width, screen_height),
        "usable_height": usable_height,
        "ui_scale": ui_scale,
        "canvas_scale": canvas_scale,
        "compact": not wide_split or window_height < 850,
    }
def geometry_string(geometry) -> str:
    width, height, x, y = geometry
    return f"{width}x{height}+{x}+{y}"
def nice_linear_ticks(data_min: float, data_max: float, target_intervals: int=4, *, include_zero: bool=False, expand_limits: bool=True):
    low = float(data_min)
    high = float(data_max)
    if not math.isfinite(low) or not math.isfinite(high):
        low, high = 0.0, 1.0
    if low > high:
        low, high = high, low
    if include_zero:
        low = min(low, 0.0)
        high = max(high, 0.0)
    if math.isclose(low, high, rel_tol=0.0, abs_tol=1e-15):
        magnitude = abs(low) if abs(low) > 0.0 else 1.0
        half_span = max(magnitude * 0.05, 1e-12)
        low -= half_span
        high += half_span
    raw_step = (high - low) / max(int(target_intervals), 1)
    exponent = math.floor(math.log10(raw_step))
    scale = 10.0 ** exponent
    fraction = raw_step / scale
    if fraction <= 1.5:
        nice_fraction = 1.0
    elif fraction <= 2.25:
        nice_fraction = 2.0
    elif fraction <= 3.75:
        nice_fraction = 2.5
    elif fraction <= 7.5:
        nice_fraction = 5.0
    else:
        nice_fraction = 10.0
    step = nice_fraction * scale
    epsilon = abs(step) * 1e-10
    if expand_limits:
        axis_min = math.floor((low + epsilon) / step) * step
        axis_max = math.ceil((high - epsilon) / step) * step
        if axis_max <= axis_min:
            axis_max = axis_min + step
    else:
        axis_min, axis_max = low, high
    first_index = int(math.ceil((axis_min - epsilon) / step))
    last_index = int(math.floor((axis_max + epsilon) / step))
    ticks = [index * step for index in range(first_index, last_index + 1)]
    if len(ticks) < 2:
        ticks = [axis_min, axis_max]
    ticks = [0.0 if abs(value) < epsilon else value for value in ticks]
    return axis_min, axis_max, ticks, step
def angle_axis_ticks(low: float, high: float):
    low, high = float(low), float(high)
    if low > high:
        low, high = high, low
    span = high - low
    if not math.isfinite(span) or span <= 0.0:
        return nice_linear_ticks(low, high)
    if span >= 4.0:
        step = next((step for step in (1, 2, 5, 10, 15, 30, 45, 90, 180) if span / step <= 6), 360)
        epsilon = step * 1e-9
        ticks = [float(index * step) for index in range(math.ceil((low - epsilon) / step), math.floor((high + epsilon) / step) + 1)]
        if len(ticks) >= 2:
            return low, high, ticks, float(step)
    return nice_linear_ticks(low, high, expand_limits=False)
def format_nice_tick(value: float, step: float) -> str:
    if abs(value) < abs(step) * 1e-9:
        return "0"
    if abs(step) < 1e-6 or abs(value) >= 1e7:
        return f"{value:.4g}"
    if abs(step) >= 1.0:
        if math.isclose(step, round(step), rel_tol=0.0, abs_tol=1e-12):
            return f"{value:.0f}"
        return f"{value:.1f}"
    decimals = min(8, max(0, int(math.ceil(-math.log10(abs(step))))))
    while decimals < 8 and (not math.isclose(abs(step) * 10.0 ** decimals, round(abs(step) * 10.0 ** decimals), rel_tol=0.0, abs_tol=1e-09)):
        decimals += 1
    return f"{value:.{decimals}f}"
def nonlocal_prime_frequencies(start_hz, stop_hz) -> tuple[float, ...]:
    try:
        start, stop = float(start_hz), float(stop_hz)
    except (TypeError, ValueError) as error:
        raise ValueError("f start and f stop must be whole numbers of Hz") from error
    if not all(math.isfinite(value) and value.is_integer() for value in (start, stop)):
        raise ValueError("f start and f stop must be whole numbers of Hz")
    start, stop = int(start), int(stop)
    if not 2 <= start <= stop <= NONLOCAL_FSCAN_MAX_HZ:
        raise ValueError(f'The frequency scan needs 2 ≤ f start ≤ f stop ≤ {NONLOCAL_FSCAN_MAX_HZ} Hz')
    sieve = bytearray(b"\x01") * (stop + 1)
    sieve[:2] = b"\x00\x00"
    for number in range(2, math.isqrt(stop) + 1):
        if sieve[number]:
            sieve[number * number::number] = bytes(len(range(number * number, stop + 1, number)))
    values = tuple(float(number) for number in range(start, stop + 1) if sieve[number])
    if not values:
        raise ValueError(f"No prime from {start} to {stop} Hz; widen the range")
    return values
def shade_color(color: str, fraction: float) -> str:
    fraction = min(max(float(fraction), 0.0), 1.0)
    rgb = [int(color[index:index + 2], 16) for index in (1, 3, 5)]
    if fraction < 0.5:
        mix = (0.5 - fraction) / 0.5 * 0.4
        rgb = [channel + (255 - channel) * mix for channel in rgb]
    else:
        mix = (fraction - 0.5) / 0.5 * 0.45
        rgb = [channel * (1 - mix) for channel in rgb]
    return "#" + "".join(f"{round(channel):02x}" for channel in rgb)
def ppms_prime_frequencies(start_hz, end_hz) -> tuple[float, ...]:
    try:
        start, end = float(start_hz), float(end_hz)
    except (TypeError, ValueError):
        raise ValueError("Frequency Start and End must be whole numbers of Hz") from None
    if not all(math.isfinite(value) and value.is_integer() for value in (start, end)):
        raise ValueError("Frequency Start and End must be whole numbers of Hz")
    if not 2 <= start <= end <= NONLOCAL_FSCAN_MAX_HZ:
        raise ValueError(f"A frequency scan needs 2 ≤ Start ≤ End ≤ {NONLOCAL_FSCAN_MAX_HZ} Hz (the 6221's sine)")
    return nonlocal_prime_frequencies(start, end)
def ppms_frequency_count_text(frequencies) -> str:
    values = tuple(frequencies)
    if len(values) == 1:
        return f"1 prime: {values[0]:g} Hz"
    return f"{len(values)} primes: {values[0]:g}–{values[-1]:g} Hz"
def ppms_frequency_scan_note(start_hz, end_hz) -> str:
    try:
        return ppms_frequency_count_text(ppms_prime_frequencies(start_hz, end_hz))
    except ValueError as error:
        return str(error)
def parse_ppms_macro(text):
    commands = []
    targets = {}
    last_temp_k = None
    for line, raw in enumerate(text.splitlines(), 1):
        tokens = raw.strip().split()
        if not tokens or tokens[0].upper() in ("REM", "#") or raw.lstrip().startswith("#"):
            continue
        try:
            op = tokens.pop(0).upper()
            if op in ("TMP", "FLD", "WAI"):
                expected = {"TMP": "TEMP", "FLD": "FIELD", "WAI": "WAITFOR"}[op]
                if not tokens or tokens.pop(0).upper() != expected:
                    raise ValueError("Command format error")
                op = expected
            values = tuple(float(x) for x in tokens)
            if not all(math.isfinite(x) for x in values):
                raise ValueError("Parameters must be finite values")
            if op == "TEMP" and len(values) in (1, 2, 3):
                target = values[0]
                rate = values[1] if len(values) > 1 else None
                approach = values[2] if len(values) > 2 else 0.
                validate_ppms_temperature_command(target, PPMS_TEMPERATURE_LOW_MAX_RATE_K_MIN if rate is None else rate, last_temp_k)
                if approach not in (0, 1):
                    raise ValueError("Temperature approach only supports 0/1")
                values = (target, rate, int(approach))
                targets["TEMP"] = target
                last_temp_k = target
            elif op == "FIELD" and len(values) in (2, 4):
                target, rate = validate_ppms_field_command(*values[:2])
                approach, mode = values[2:] if len(values) == 4 else (0, 1)
                if approach not in (0, 1, 2) or mode not in (0, 1):
                    raise ValueError("Field approach is 0/1/2, mode is 0(Persistent)/1(Driven)")
                values = (target, rate, int(approach), int(mode))
                targets["FIELD"] = target
                targets["FIELD_MODE"] = int(mode)
            elif op == "WAIT" and len(values) == 1:
                if not 0 <= values[0] <= 86400:
                    raise ValueError("Wait time range is 0–86400 s")
            elif op == "WAITFOR" and len(values) == 6:
                delay, temp, field, *unsupported = values
                if not 0 <= delay <= 86400 or temp not in (0, 1) or field not in (0, 1) or any(unsupported):
                    raise ValueError("WAITFOR supports: seconds temperature(0/1) field(0/1) 0 0 0")
                if (temp and "TEMP" not in targets) or (field and "FIELD" not in targets):
                    raise ValueError("Please specify the corresponding TEMP/FIELD target before waiting")
                values = (delay, targets.get('TEMP') if temp else None, targets.get('FIELD') if field else None, targets.get('FIELD_MODE') if field else None)
            elif op == "SCAN" and not values:
                last_temp_k = None
            else:
                raise ValueError("Unsupported command or parameter count; VSMDF/VSMMH/VSMMT cannot be used for transport measurements")
            commands.append((line, op, values))
        except ValueError as error:
            raise ValueError(f"Line {line}: {error}") from None
    if not commands:
        raise ValueError("No runnable commands")
    return commands
def ppms_lockin_settle_s(settle_s, time_constants_s) -> float:
    """The wait before a scan point is read: Settle s, or LOCKIN_SETTLE_TAUS
    time constants of the slowest lock-in measured if that is longer."""
    return calculate_lockin_settle_s(settle_s, time_constants_s, settle_taus=LOCKIN_SETTLE_TAUS)
def ppms_settle_status_text(seconds) -> str:
    """The wait before each reading, as a status line shows it."""
    return format_settle_status_text(seconds)
def ppms_lockin_settle_text(settle_s, effective_s, slowest_tc_s, meter) -> str:
    """How the wait before each reading was chosen, in words."""
    return format_lockin_settle_text(settle_s, effective_s, slowest_tc_s, meter, settle_taus=LOCKIN_SETTLE_TAUS)
def validate_ppms_transport_scan_settings(
    current_rms_ma: float,
    frequency_hz: float,
    compliance_v: float,
    harmonic_a: int,
    harmonic_b: int,
    active_lockins: tuple[str, ...] = ("830_a", "830_b"),
    allow_no_lockins: bool = False,
    harmonic_c: int = 1,
) -> dict[str, object]:
    """Validate 6221/SR830 settings used by the PPMS field scan."""
    return validate_transport_scan_settings(
        current_rms_ma, frequency_hz, compliance_v, harmonic_a, harmonic_b,
        active_lockins=active_lockins, allow_no_lockins=allow_no_lockins, harmonic_c=harmonic_c,
        max_abs_current_a=K6221_MAX_ABS_CURRENT_A, min_compliance_v=K6221_MIN_COMPLIANCE_V,
        max_compliance_v=K6221_MAX_COMPLIANCE_V, valid_sr830_keys=PPMS_SR830_KEYS)
class Keithley6221Controller:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.resource_manager = None
        self.instrument = None
        self.resource_name = ""
        self.identity = ""
        self.output_enabled = False
        self.current_a = 0.0
        self.pulse_width_s = K6221_DEFAULT_PULSE_WIDTH_US / 1_000_000.0
        self.pulse_count = K6221_DEFAULT_PULSE_COUNT
        self.compliance_v = K6221_DEFAULT_COMPLIANCE_V
        self.output_mode = "OFF"
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    def _query_error(self, command: str) -> None:
        response = self.instrument.query("SYST:ERR?").strip()
        try:
            code = int(response.split(",", 1)[0].strip())
        except ValueError as error:
            raise RuntimeError(f"6221 returned an unparsable error status: {response}") from error
        if code != 0:
            raise RuntimeError(f"6221 SCPI error after '{command}': {response}")
    def _write_checked(self, command: str) -> None:
        self.instrument.write(command)
        self._query_error(command)
    def _read_output_low_to_earth(self) -> int:
        text = self.instrument.query(K6221_OUTPUT_LOW_QUERY).strip().upper()
        if text in ("0", "OFF"):
            return 0
        if text in ("1", "ON"):
            return 1
        raise RuntimeError(f"6221 returned an unexpected OUTP:LTE state: {text!r}")
    def _set_output_low_floating(self) -> None:
        if self._read_output_low_to_earth() == 0:
            return
        self._write_checked(K6221_OUTPUT_LOW_FLOATING)
        if self._read_output_low_to_earth() != 0:
            raise RuntimeError('6221 output low stayed earth-grounded; set TRIAX -> OUTPUT LOW -> FLOATING on the front panel')
    @staticmethod
    def _validate(current_a: float, pulse_width_s: float, compliance_v: float, pulse_count: int):
        current_a = float(current_a)
        pulse_width_s = float(pulse_width_s)
        compliance_v = float(compliance_v)
        try:
            pulse_count_numeric = float(pulse_count)
        except (TypeError, ValueError) as error:
            raise ValueError("6221 pulse count must be an integer") from error
        if not math.isfinite(pulse_count_numeric) or not pulse_count_numeric.is_integer():
            raise ValueError("6221 pulse count must be an integer")
        pulse_count = int(pulse_count_numeric)
        if not all((math.isfinite(value) for value in (current_a, pulse_width_s, compliance_v))):
            raise ValueError("6221 current, pulse width and compliance voltage must be finite values")
        if abs(current_a) > K6221_MAX_ABS_CURRENT_A:
            raise ValueError(f'6221 current exceeds the software limit ±{K6221_MAX_ABS_CURRENT_A * 1000:g} mA')
        if 0.0 < abs(current_a) < K6221_MIN_NONZERO_CURRENT_A:
            raise ValueError("6221 non-zero pulse current magnitude cannot be less than 4 pA")
        if not K6221_MIN_PULSE_WIDTH_S <= pulse_width_s <= K6221_MAX_PULSE_WIDTH_S:
            raise ValueError(f'6221 pulse width must be between {K6221_MIN_PULSE_WIDTH_S * 1000000.0:g} us–{K6221_MAX_PULSE_WIDTH_S:g} s')
        if not K6221_MIN_COMPLIANCE_V <= compliance_v <= K6221_MAX_COMPLIANCE_V:
            raise ValueError(f'6221 compliance voltage must be between {K6221_MIN_COMPLIANCE_V:g}–{K6221_MAX_COMPLIANCE_V:g} V')
        if not 1 <= pulse_count <= K6221_MAX_PULSE_COUNT:
            raise ValueError(f'6221 pulse count must be between 1 and {K6221_MAX_PULSE_COUNT}')
        total_time_s = 2.0 * pulse_width_s * pulse_count
        if total_time_s > K6221_MAX_WAVEFORM_TIME_S:
            raise ValueError(f'Total waveform time (pulse width × pulse count) exceeds {K6221_MAX_WAVEFORM_TIME_S:g} s')
        return current_a, pulse_width_s, compliance_v, pulse_count
    def connect(self, resource_name: str, compliance_v: float) -> str:
        if pyvisa is None:
            raise RuntimeError("pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py")
        _, _, compliance_v, _ = self._validate(0.0, self.pulse_width_s, compliance_v, self.pulse_count)
        with self.lock:
            if self.instrument is not None:
                return self.identity
            acquire_instrument_lease(resource_name, self, "Keithley 6221 pulse")
            manager = None
            instrument = None
            try:
                manager = acquire_shared_visa_manager()
                instrument = manager.open_resource(resource_name)
                instrument.timeout = 5000
                instrument.write_termination = "\n"
                instrument.read_termination = "\n"
                identity = instrument.query("*IDN?").strip()
                if "6221" not in identity.upper():
                    raise RuntimeError(f'The device returned by {resource_name} is not a Keithley 6221: {identity}')
                self.resource_manager = manager
                self.instrument = instrument
                self.resource_name = resource_name
                self.identity = identity
                self.compliance_v = compliance_v
                instrument.write("*RST")
                instrument.write("*CLS")
                self._set_output_low_floating()
                self._write_checked(f"CURR:COMP {compliance_v:.12g}")
                self._write_checked("OUTP OFF")
                self.output_enabled = False
                self.current_a = 0.0
                self.output_mode = "OFF"
                self.logger(f"Keithley 6221 connected: {identity}")
                return identity
            except BaseException:
                if instrument is not None:
                    for command in ("SOUR:WAVE:ABOR", "CURR 0", "OUTP OFF"):
                        try:
                            instrument.write(command)
                        except BaseException:
                            pass
                    try:
                        instrument.close()
                    except BaseException:
                        pass
                release_shared_visa_manager(manager)
                self.resource_manager = None
                self.instrument = None
                release_instrument_lease(resource_name, self)
                raise
    def set_continuous_output(self, mode: str, current_a: float, frequency_hz: float, compliance_v: float) -> dict[str, object]:
        mode = str(mode).strip().upper()
        current_a = float(current_a)
        frequency_hz = float(frequency_hz)
        compliance_v = float(compliance_v)
        if mode not in {"AC", "DC"}:
            raise ValueError("6221 continuous output mode can only be AC or DC")
        if not all((math.isfinite(value) for value in (current_a, frequency_hz, compliance_v))):
            raise ValueError("6221 continuous output parameters must be finite values")
        if not K6221_MIN_COMPLIANCE_V <= compliance_v <= K6221_MAX_COMPLIANCE_V:
            raise ValueError(f'6221 compliance voltage must be between {K6221_MIN_COMPLIANCE_V:g}–{K6221_MAX_COMPLIANCE_V:g} V')
        if mode == "AC":
            if current_a < 0:
                raise ValueError("6221 AC current uses the RMS amplitude and cannot be negative")
            peak_a = math.sqrt(2.0) * current_a
            if peak_a > K6221_MAX_ABS_CURRENT_A:
                raise ValueError(f'6221 AC peak exceeds the hardware range; RMS maximum is about {K6221_MAX_ABS_CURRENT_A / math.sqrt(2) * 1000:g} mA')
            if 0.0 < current_a < K6221_MIN_NONZERO_CURRENT_A:
                raise ValueError("6221 non-zero AC RMS current cannot be less than 4 pA")
            if not 1e-3 <= frequency_hz <= 1e5:
                raise ValueError("6221 AC frequency must be within 0.001–100000 Hz")
        else:
            peak_a = 0.0
            if abs(current_a) > K6221_MAX_ABS_CURRENT_A:
                raise ValueError(f'6221 DC current exceeds ±{K6221_MAX_ABS_CURRENT_A * 1000:g} mA')
            if 0.0 < abs(current_a) < K6221_MIN_NONZERO_CURRENT_A:
                raise ValueError("6221 non-zero DC current magnitude cannot be less than 4 pA")
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("Keithley 6221 is not connected")
            if current_a == 0.0:
                self.output_off()
                return self.read_output_state()
            if mode == "AC":
                commands = (
                    "SOUR:WAVE:ABOR",
                    f"CURR:COMP {compliance_v:.12g}",
                    "SOUR:WAVE:FUNC SIN",
                    f"SOUR:WAVE:FREQ {frequency_hz:.12g}",
                    f"SOUR:WAVE:AMPL {peak_a:.12e}",
                    "SOUR:WAVE:OFFS 0",
                    "SOUR:WAVE:RANG BEST",
                    "SOUR:WAVE:PMAR:STAT OFF",
                    "SOUR:WAVE:DUR:CYCL INF",
                    "SOUR:WAVE:ARM",
                    "OUTP ON",
                    "SOUR:WAVE:INIT",
                )
            else:
                commands = ('SOUR:WAVE:ABOR', f'CURR:COMP {compliance_v:.12g}', 'SOUR:CURR:RANG:AUTO ON', f'SOUR:CURR {current_a:.12e}', 'OUTP ON')
            for command in commands:
                self._write_checked(command)
            actual_compliance = float(self.instrument.query('CURR:COMP?').strip())
            output_state = int(round(float(self.instrument.query('OUTP?').strip())))
            if mode == "AC":
                actual_peak = float(self.instrument.query('SOUR:WAVE:AMPL?').strip())
                actual_frequency = float(self.instrument.query('SOUR:WAVE:FREQ?').strip())
                actual_current = actual_peak / math.sqrt(2.0)
                if not math.isclose(actual_peak, peak_a, rel_tol=0.0005, abs_tol=1e-12):
                    self.output_off()
                    raise RuntimeError(f'6221 AC amplitude readback mismatch: requested {peak_a:g} Apeak, readback {actual_peak:g} Apeak')
                if not math.isclose(actual_frequency, frequency_hz, rel_tol=0.0005, abs_tol=1e-06):
                    self.output_off()
                    raise RuntimeError(f'6221 AC frequency readback mismatch: requested {frequency_hz:g} Hz, readback {actual_frequency:g} Hz')
            else:
                actual_current = float(self.instrument.query('SOUR:CURR?').strip())
                actual_frequency = math.nan
                if not math.isclose(actual_current, current_a, rel_tol=0.0005, abs_tol=1e-12):
                    self.output_off()
                    raise RuntimeError(f'6221 DC current readback mismatch: requested {current_a:g} A, readback {actual_current:g} A')
            if not math.isclose(actual_compliance, compliance_v, rel_tol=0.0005, abs_tol=1e-06) or output_state != 1:
                self.output_off()
                raise RuntimeError(f'6221 continuous output start readback mismatch: compliance={actual_compliance:g} V, output={output_state}')
            self.current_a = actual_current
            self.compliance_v = actual_compliance
            self.output_enabled = True
            self.output_mode = mode
            return self.read_output_state()
    def read_output_state(self) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("Keithley 6221 is not connected")
            output_on = bool(round(float(self.instrument.query('OUTP?').strip())))
            compliance_v = float(self.instrument.query('CURR:COMP?').strip())
            measurement_condition = int(round(float(self.instrument.query('STAT:MEAS:COND?').strip())))
            mode = self.output_mode if output_on else "OFF"
            frequency_hz = math.nan
            if mode in {"AC", "PULSE"}:
                amplitude_a = float(self.instrument.query('SOUR:WAVE:AMPL?').strip())
                offset_a = float(self.instrument.query('SOUR:WAVE:OFFS?').strip())
                frequency_hz = float(self.instrument.query('SOUR:WAVE:FREQ?').strip())
                if mode == "AC":
                    current_a = amplitude_a / math.sqrt(2.0)
                else:
                    sign_source = offset_a if offset_a != 0 else 1.0
                    current_a = math.copysign(abs(offset_a) + abs(amplitude_a), sign_source)
            else:
                current_a = float(self.instrument.query('SOUR:CURR?').strip())
            self.output_enabled = output_on
            self.current_a = current_a if output_on else 0.0
            self.compliance_v = compliance_v
            if not output_on:
                self.output_mode = "OFF"
            return {
                "mode": mode,
                "current_a": current_a,
                "frequency_hz": frequency_hz,
                "compliance_v": compliance_v,
                "output_on": output_on,
                "measurement_condition": measurement_condition,
                "in_compliance": bool(measurement_condition & 8),
                "sample_monotonic": time.monotonic(),
            }
    def set_dc_pulse(self, current_a: float, pulse_width_s: float, compliance_v: float, pulse_count: int) -> dict[str, object]:
        current_a, pulse_width_s, compliance_v, pulse_count = self._validate(current_a, pulse_width_s, compliance_v, pulse_count)
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("Keithley 6221 is not connected")
            if current_a == 0.0:
                self.output_off()
                return {
                    "mode": "OFF",
                    "current_a": 0.0,
                    "pulse_width_s": pulse_width_s,
                    "frequency_hz": 1.0 / (2.0 * pulse_width_s),
                    "compliance_v": compliance_v,
                    "pulse_count": pulse_count,
                    "total_time_s": 0.0,
                    "output_on": False,
                    "measurement_condition": 0,
                    "in_compliance": False,
                    "sample_monotonic": time.monotonic(),
                }
            frequency_hz = 1.0 / (2.0 * pulse_width_s)
            amplitude_a = abs(current_a) / 2.0
            offset_a = current_a / 2.0
            commands = (
                "SOUR:WAVE:ABOR",
                f"CURR:COMP {compliance_v:.12g}",
                "SOUR:WAVE:FUNC SQU",
                "SOUR:WAVE:DCYC 50",
                f"SOUR:WAVE:AMPL {amplitude_a:.12e}",
                f"SOUR:WAVE:OFFS {offset_a:.12e}",
                f"SOUR:WAVE:FREQ {frequency_hz:.12g}",
                "SOUR:WAVE:RANG BEST",
                "SOUR:WAVE:PMAR:STAT OFF",
                "SOUR:WAVE:EXTR OFF",
                f"SOUR:WAVE:DUR:CYCL {pulse_count}",
                "SOUR:WAVE:ARM",
                "OUTP ON",
                "SOUR:WAVE:INIT",
            )
            for command in commands:
                self._write_checked(command)
            actual_amplitude = float(self.instrument.query("SOUR:WAVE:AMPL?").strip())
            actual_offset = float(self.instrument.query("SOUR:WAVE:OFFS?").strip())
            actual_frequency = float(self.instrument.query("SOUR:WAVE:FREQ?").strip())
            actual_compliance = float(self.instrument.query("CURR:COMP?").strip())
            actual_cycles = int(round(float(self.instrument.query('SOUR:WAVE:DUR:CYCL?').strip())))
            output_state = int(round(float(self.instrument.query("OUTP?").strip())))
            measurement_condition = int(round(float(self.instrument.query('STAT:MEAS:COND?').strip())))
            checks = (
                ("amplitude", actual_amplitude, amplitude_a, 5e-4, 1e-12),
                ("offset", actual_offset, offset_a, 5e-4, 1e-12),
                ("frequency", actual_frequency, frequency_hz, 5e-4, 1e-6),
                ("compliance voltage", actual_compliance, compliance_v, 5e-4, 1e-6),
            )
            for label, actual, requested, rel_tol, abs_tol in checks:
                if not math.isfinite(actual) or not math.isclose(actual, requested, rel_tol=rel_tol, abs_tol=abs_tol):
                    self.output_off()
                    raise RuntimeError(f'6221 {label} readback mismatch: requested {requested:g}, readback {actual:g}')
            if actual_cycles != pulse_count:
                self.output_off()
                raise RuntimeError(f'6221 pulse count readback mismatch: requested {pulse_count}, readback {actual_cycles}')
            completed_before_readback = output_state == 0
            self.current_a = math.copysign(abs(actual_offset) + abs(actual_amplitude), current_a)
            self.pulse_width_s = 1.0 / (2.0 * actual_frequency)
            self.compliance_v = actual_compliance
            self.pulse_count = pulse_count
            self.output_enabled = bool(output_state)
            self.output_mode = "PULSE" if output_state else "OFF"
            return {
                "mode": "PULSE",
                "current_a": self.current_a,
                "pulse_width_s": self.pulse_width_s,
                "frequency_hz": actual_frequency,
                "compliance_v": actual_compliance,
                "pulse_count": pulse_count,
                "total_time_s": 2.0 * self.pulse_width_s * pulse_count,
                "output_on": bool(output_state),
                "completed_before_readback": completed_before_readback,
                "measurement_condition": measurement_condition,
                "in_compliance": bool(measurement_condition & 8),
                "sample_monotonic": time.monotonic(),
            }
    def output_off(self) -> None:
        with self.lock:
            if self.instrument is None:
                return
            errors = []
            for command in ("SOUR:WAVE:ABOR", "CURR 0", "OUTP OFF"):
                try:
                    self.instrument.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            self.output_enabled = False
            self.current_a = 0.0
            self.output_mode = "OFF"
            if errors:
                raise RuntimeError("6221 failed to turn output off: " + "; ".join(errors))
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            manager = self.resource_manager
            resource_name = self.resource_name
            if instrument is None and manager is None:
                return
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            if instrument is not None:
                for command in ("*CLS", "SYST:LOC"):
                    try:
                        instrument.write(command)
                    except BaseException:
                        pass
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = None
            self.resource_manager = None
            self.resource_name = ""
            self.identity = ""
            self.output_enabled = False
            self.current_a = 0.0
            release_instrument_lease(resource_name, self)
            self.logger("Keithley 6221 disconnected")
            if shutdown_error is not None:
                raise shutdown_error
_MFLI_BRIDGE_PREFIX = "MOKE_MFLI_JSON:"
_MFLI_BRIDGE_SOURCE = r'''
from __future__ import print_function

import json
import math
import sys
import time
import traceback

PREFIX = "MOKE_MFLI_JSON:"
DEVICE_REQUEST = sys.argv[1]
API_LEVEL = int(sys.argv[2])
DEMOD = int(sys.argv[3])
EXTREF_DEMOD = 1
EXTREF = 0
# The id of the request being answered, echoed in its reply, so a reply that
# arrives after its request timed out is never taken for the next one's.
REQUEST_ID = None


def emit(payload):
    if REQUEST_ID is not None and "id" not in payload:
        payload["id"] = REQUEST_ID
    sys.stdout.write(PREFIX + json.dumps(payload, ensure_ascii=True) + "\n")
    sys.stdout.flush()


def scalar(sample, field, required=True):
    try:
        value = sample[field]
    except (KeyError, TypeError):
        if required:
            raise RuntimeError("MFLI sample missing field: " + field)
        return None
    try:
        value = value[-1]
    except (IndexError, KeyError, TypeError):
        pass
    result = float(value)
    if not math.isfinite(result):
        raise RuntimeError("MFLI sample has non-finite field: " + field)
    return result


def input_state(reset_extrema=False):
    range_node = "/%s/sigins/0/range" % device
    max_node = "/%s/sigins/0/max" % device
    min_node = "/%s/sigins/0/min" % device
    result = {"input_range_v": float(daq.getDouble(range_node))}
    try:
        result["input_max_normalized"] = float(daq.getDouble(max_node))
        result["input_min_normalized"] = float(daq.getDouble(min_node))
        if reset_extrema:
            daq.setDouble(max_node, 0.0)
            daq.setDouble(min_node, 0.0)
    except Exception:
        result["input_max_normalized"] = None
        result["input_min_normalized"] = None
    return result


def run_autorange(timeout_s=8.0):
    old_range = float(daq.getDouble("/%s/sigins/0/range" % device))
    autorange_node = "/%s/sigins/0/autorange" % device
    daq.setInt(autorange_node, 1)
    # As zhinst.utils.sigin_autorange: the set must take effect before the
    # poll, or a stale 0 ends it at once.
    daq.sync()
    deadline = time.monotonic() + float(timeout_s)
    while int(daq.getInt(autorange_node)) != 0:
        if time.monotonic() >= deadline:
            raise RuntimeError("MFLI Signal Input 1 autorange timed out")
        time.sleep(0.02)
    daq.sync()
    result = input_state(reset_extrema=True)
    result["old_input_range_v"] = old_range
    return result


daq = None
device = ""
configured_extref_demod = DEMOD
try:
    import zhinst.utils as zi_utils

    session = zi_utils.create_api_session(DEVICE_REQUEST, API_LEVEL)
    if not isinstance(session, tuple) or len(session) < 3:
        raise RuntimeError("Unexpected create_api_session result: %r" % (session,))
    daq, discovered, props = session[:3]
    device = str(discovered).strip().lower()
    if not device:
        raise RuntimeError("LabOne Discovery returned an empty device name")
    try:
        zi_utils.api_server_version_check(daq)
    except AttributeError:
        pass
    enable_node = "/%s/demods/%d/enable" % (device, DEMOD)
    daq.setInt(enable_node, 1)
    daq.sync()
    daq.getSample("/%s/demods/%d/sample" % (device, DEMOD))
    version = ""
    options = ""
    if isinstance(props, dict):
        version = str(props.get("serverversion") or props.get("version") or "")
        raw_options = props.get("options") or ""
        if isinstance(raw_options, (tuple, list)):
            options = ",".join(str(item) for item in raw_options)
        else:
            options = str(raw_options)
    if not options:
        try:
            options = str(daq.getString("/%s/features/options" % device))
        except Exception:
            pass
    try:
        daq.getInt("/%s/demods/1/enable" % device)
        has_demod_2 = True
    except Exception:
        has_demod_2 = False
    try:
        daq.getInt("/%s/demods/3/enable" % device)
        daq.getInt("/%s/extrefs/1/demodselect" % device)
        has_demod_4 = True
    except Exception:
        has_demod_4 = False
    identity = "Zurich Instruments MFLI - " + device
    if version:
        identity += " - LabOne " + version
    emit({"ok": True, "event": "ready", "device": device,
          "version": version, "options": options,
          "has_demod_2": has_demod_2, "has_demod_4": has_demod_4, "identity": identity})
except BaseException:
    emit({"ok": False, "event": "ready", "error": traceback.format_exc()})
    try:
        if daq is not None:
            daq.disconnect()
    except BaseException:
        pass
    sys.exit(2)

for request_line in sys.stdin:
    REQUEST_ID = None
    try:
        request = json.loads(request_line)
        REQUEST_ID = request.get("id")
        command = request.get("command")
        if command in ("configure_second_harmonic", "configure_third_harmonic"):
            harmonic = 2 if command == "configure_second_harmonic" else 3
            measurement_demod = harmonic - 1 if configured_extref_demod == 3 else harmonic
            base = "/%s/demods/%d/" % (device, measurement_demod)
            if configured_extref_demod not in (1, 3) or measurement_demod == configured_extref_demod:
                raise RuntimeError("Measurement demodulator conflicts with external reference")
            for name, value in (("adcselect", 0), ("oscselect", 0), ("harmonic", harmonic),
                                ("order", int(request["order"])), ("enable", 1)):
                daq.setInt(base + name, value)
            for name in ("timeconstant", "rate"):
                daq.setDouble(base + name, float(request[name]))
            daq.sync()
            for name, value in (("adcselect", 0), ("oscselect", 0), ("harmonic", harmonic), ("enable", 1)):
                if daq.getInt(base + name) != value:
                    raise RuntimeError("Additional harmonic readback mismatch: " + name)
            emit({"ok": True})
        elif command == "disable_unused_demods":
            for index in request["indices"]:
                if index not in (1, 2, 3) or index == configured_extref_demod:
                    raise RuntimeError("Cannot disable active reference demodulator")
                node = "/%s/demods/%d/enable" % (device, index)
                daq.setInt(node, 0)
                daq.sync()
                if daq.getInt(node) != 0:
                    raise RuntimeError("Unused demodulator disable readback mismatch")
            emit({"ok": True})
        elif command == "configure":
            requested_ac = 1 if str(request["coupling"]).upper() == "AC" else 0
            requested_imp50 = int(request.get("input_imp50", 0))
            requested_scaling = float(request.get("input_scaling", 1.0))
            requested_harmonic = int(request["harmonic"])
            requested_reference_input = int(request["reference_adcselect"])
            requested_timeconstant = float(request["timeconstant_s"])
            requested_order = int(request["filter_order"])
            requested_rate = float(request["sample_rate_hz"])
            extref_demod = int(request.get("extref_demod", EXTREF_DEMOD))
            if extref_demod == 3:
                routes = [i for i in range(2)
                          if int(daq.getInt("/%s/extrefs/%d/demodselect" % (device, i))) == 3]
                if len(routes) != 1:
                    raise RuntimeError("Cannot identify external reference controller for Demod 4")
                EXTREF = routes[0]
            else:
                EXTREF = 0
            for other in range(2):
                # Only the chosen reference PLL: another left on (an earlier
                # session) would drive oscillator 0 as well.
                if other != EXTREF:
                    try:
                        daq.setInt("/%s/extrefs/%d/enable" % (device, other), 0)
                    except Exception:
                        pass
            configured_extref_demod = extref_demod
            ac_node = "/%s/sigins/0/ac" % device
            imp50_node = "/%s/sigins/0/imp50" % device
            scaling_node = "/%s/sigins/0/scaling" % device
            harmonic_node = "/%s/demods/%d/harmonic" % (device, DEMOD)
            enable_node = "/%s/demods/%d/enable" % (device, DEMOD)
            osc_node = "/%s/demods/%d/oscselect" % (device, DEMOD)
            extref_demod_node = "/%s/extrefs/%d/demodselect" % (device, EXTREF)
            extref_auto_node = "/%s/extrefs/%d/automode" % (device, EXTREF)
            extref_enable_node = "/%s/extrefs/%d/enable" % (device, EXTREF)
            extref_adc_node = "/%s/extrefs/%d/adcselect" % (device, EXTREF)
            measurement_adc_node = "/%s/demods/%d/adcselect" % (device, DEMOD)
            timeconstant_node = "/%s/demods/%d/timeconstant" % (device, DEMOD)
            order_node = "/%s/demods/%d/order" % (device, DEMOD)
            rate_node = "/%s/demods/%d/rate" % (device, DEMOD)
            daq.setInt(ac_node, requested_ac)
            daq.setInt(imp50_node, requested_imp50)
            daq.setDouble(scaling_node, requested_scaling)
            ext_demod_node = "/%s/demods/%d/adcselect" % (device, extref_demod)
            ext_osc_node = "/%s/demods/%d/oscselect" % (device, extref_demod)
            ext_harmonic_node = "/%s/demods/%d/harmonic" % (device, extref_demod)
            ext_demod_enable_node = "/%s/demods/%d/enable" % (device, extref_demod)
            daq.setInt(ext_demod_node, requested_reference_input)
            daq.setInt(ext_osc_node, 0)
            if extref_demod != DEMOD:
                daq.setInt(ext_harmonic_node, 1)
            daq.setInt(ext_demod_enable_node, 1)
            selected_extref_input = int(daq.getInt(ext_demod_node))
            try:
                daq.setInt(extref_demod_node, extref_demod)
            except Exception:
                pass
            # automode/demodselect/locked were exposed as dedicated nodes in
            # newer LabOne releases.  LabOne 18.12 can still enable ExtRef,
            # but does not necessarily expose all three nodes to the API.
            try:
                daq.setInt(extref_auto_node, 4)
            except Exception:
                pass
            daq.setInt(extref_enable_node, 1)
            if extref_demod == 3:
                daq.sync()
                if daq.getInt(extref_demod_node) != 3:
                    raise RuntimeError("External reference Demod 4 readback mismatch")
            # A base MFLI temporarily uses Demod 1 to select/latch the chosen
            # external reference, then returns its measurement input to
            # Signal In 1.
            if extref_demod == DEMOD:
                daq.sync()
                if selected_extref_input != requested_reference_input:
                    raise RuntimeError(
                        "Requested external reference was not selected: "
                        "%d != %d" %
                        (selected_extref_input, requested_reference_input)
                    )
                daq.setInt(measurement_adc_node, 0)
            daq.setInt(osc_node, 0)
            daq.setInt(harmonic_node, requested_harmonic)
            daq.setDouble(timeconstant_node, requested_timeconstant)
            daq.setInt(order_node, requested_order)
            daq.setDouble(rate_node, requested_rate)
            daq.setInt(enable_node, 1)
            daq.sync()
            if extref_demod != DEMOD:
                try:
                    selected_extref_input = int(daq.getInt(extref_adc_node))
                except Exception:
                    pass
            configured_input = input_state(reset_extrema=True)
            emit({"ok": True, "extref_channel": EXTREF, "actual_ac": int(daq.getInt(ac_node)),
                  "actual_imp50": int(daq.getInt(imp50_node)),
                  "actual_scaling": float(daq.getDouble(scaling_node)),
                  "actual_harmonic": int(daq.getInt(harmonic_node)),
                  "actual_extref_harmonic": (
                      int(daq.getInt(ext_harmonic_node))
                      if extref_demod != DEMOD else 1),
                  "extref_enabled": int(daq.getInt(extref_enable_node)),
                  "extref_adcselect": selected_extref_input,
                  "timeconstant_s": float(daq.getDouble(timeconstant_node)),
                  "filter_order": int(daq.getInt(order_node)),
                  "sample_rate_hz": float(daq.getDouble(rate_node)),
                  "input_range_v": configured_input["input_range_v"]})
        elif command == "read":
            sample = daq.getSample("/%s/demods/%d/sample" % (device, DEMOD))
            payload = {"x": scalar(sample, "x"), "y": scalar(sample, "y")}
            frequency = scalar(sample, "frequency", required=False)
            flags = scalar(sample, "flags", required=False)
            if frequency is not None:
                payload["frequency"] = frequency
            if flags is not None:
                payload["flags"] = flags
            try:
                payload["extref_locked"] = int(daq.getInt(
                    "/%s/extrefs/%d/locked" % (device, EXTREF)))
            except Exception:
                payload["extref_locked"] = None
            payload.update(input_state(reset_extrema=True))
            try:
                payload["device_status_flags"] = int(daq.getInt(
                    "/%s/status/flags/binary" % device))
            except Exception:
                payload["device_status_flags"] = None
            emit({"ok": True, "sample": payload})
        elif command == "read_demods":
            channels = []
            for index in range(int(request.get("count", 4))):
                node = "/%s/demods/%d" % (device, index)
                enabled = int(daq.getInt(node + "/enable"))
                if not enabled:
                    channels.append({"enabled": 0})
                    continue
                raw = daq.getSample(node + "/sample")
                channels.append({"x": scalar(raw, "x"), "y": scalar(raw, "y"),
                    "frequency": scalar(raw, "frequency"),
                    "timestamp": scalar(raw, "timestamp", required=False),
                    "harmonic": int(daq.getInt(node + "/harmonic")),
                    "adcselect": int(daq.getInt(node + "/adcselect")), "enabled": enabled})
            emit({"ok": True, "demods": channels})
        elif command == "autorange":
            emit({"ok": True, "autorange": run_autorange()})
        elif command == "close":
            try:
                daq.setInt("/%s/extrefs/%d/enable" % (device, EXTREF), 0)
                daq.setInt("/%s/demods/%d/enable" % (device, DEMOD), 0)
                if configured_extref_demod != DEMOD:
                    daq.setInt("/%s/demods/%d/enable" %
                               (device, configured_extref_demod), 0)
                daq.sync()
            finally:
                daq.disconnect()
            emit({"ok": True})
            break
        else:
            raise ValueError("Unknown bridge command: %r" % (command,))
    except BaseException:
        emit({"ok": False, "error": traceback.format_exc()})
'''
def _find_mfli_legacy_python() -> Path:
    configured = os.environ.get(NONLOCAL_MFLI_LEGACY_PYTHON_ENV, "").strip()
    candidates = []
    if configured:
        candidates.append(Path(configured.strip('"')))
    system_drive = os.environ.get("SystemDrive", "C:")
    drive_root = Path(system_drive + os.sep if system_drive.endswith(':') else system_drive)
    user_profile = os.environ.get("USERPROFILE", "")
    local_app_data = os.environ.get("LOCALAPPDATA", "")
    if local_app_data:
        candidates.append(Path(local_app_data) / 'NBB/MOKE_MFLI_PY37/python.exe')
    candidates.append(PROGRAM_DIRECTORY / '.mfli_py37/python.exe')
    candidates.extend((drive_root / 'ProgramData/miniconda3/envs/GMS_VENV_PYTHON/python.exe', drive_root / 'ProgramData/anaconda3/envs/GMS_VENV_PYTHON/python.exe'))
    if user_profile:
        candidates.extend((Path(user_profile) / 'miniconda3/envs/GMS_VENV_PYTHON/python.exe', Path(user_profile) / 'anaconda3/envs/GMS_VENV_PYTHON/python.exe'))
    rejected = []
    validation_code = (
        "import sys,pkg_resources,numpy,zhinst,zhinst.utils;"
        "v=pkg_resources.get_distribution('zhinst').version;"
        "assert sys.version_info[:2]==(3,7),sys.version;"
        "assert v=='18.12.59443',v;"
        "assert numpy.__version__=='1.21.6',numpy.__version__;print(v)"
    )
    for candidate in candidates:
        try:
            if not candidate.is_file():
                continue
            check = subprocess.run(
                [str(candidate), "-c", validation_code],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8.0,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            if check.returncode == 0:
                return candidate
            detail = (check.stderr or check.stdout or "verification failed").strip()
            rejected.append(f"{candidate} ({short_status_error(detail, 160)})")
        except (OSError, subprocess.SubprocessError) as error:
            rejected.append(f"{candidate} ({short_status_error(error, 160)})")
            continue
    searched = "; ".join(str(path) for path in candidates)
    rejected_text = "; ".join(rejected) if rejected else "none"
    raise RuntimeError(
        "No verified Python 3.7 + zhinst 18.12.59443 environment was found. Please run "
        r"INSTALL_MFLI_LABONE_18_12.bat first, or confirm that "
        r"C:\ProgramData\miniconda3\envs\GMS_VENV_PYTHON\python.exe "
        f"exists, or set the environment variable {NONLOCAL_MFLI_LEGACY_PYTHON_ENV}."
        f"Checked: {searched}. Rejected environments: {rejected_text}"
    )
class LegacyMFLIBridge:
    def __init__(self, device_id: str, timeout_s: float = 20.0) -> None:
        self.python_path = _find_mfli_legacy_python()
        self.process = None
        self.responses: queue.Queue = queue.Queue()
        self.diagnostics: list[str] = []
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        command = [str(self.python_path), '-u', '-c', _MFLI_BRIDGE_SOURCE, str(device_id), str(NONLOCAL_MFLI_API_LEVEL), str(NONLOCAL_MFLI_DEMODULATOR)]
        try:
            self.process = subprocess.Popen(
                command,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                bufsize=1,
                creationflags=creationflags,
            )
            threading.Thread(target=self._read_stdout, name='MFLI-bridge-stdout', daemon=True).start()
            threading.Thread(target=self._read_stderr, name='MFLI-bridge-stderr', daemon=True).start()
            ready = self._receive(timeout_s)
            if ready.get("event") != "ready":
                raise RuntimeError(f"MFLI bridge start reply is abnormal: {ready!r}")
            self.device = str(ready.get("device", device_id)).strip().lower()
            self.version = str(ready.get("version", ""))
            self.options = str(ready.get("options", ""))
            self.has_demod_2 = bool(ready.get("has_demod_2", False))
            self.has_demod_4 = bool(ready.get("has_demod_4", False))
            self.identity = str(ready.get("identity", self.device))
        except BaseException:
            self.close(force=True)
            raise
    def _append_diagnostic(self, line: str) -> None:
        line = str(line).strip()
        if not line:
            return
        self.diagnostics.append(line)
        del self.diagnostics[:-12]
    def _read_stdout(self) -> None:
        stream = self.process.stdout if self.process is not None else None
        if stream is None:
            self.responses.put({"_eof": True})
            return
        try:
            for raw_line in stream:
                line = raw_line.rstrip("\r\n")
                if line.startswith(_MFLI_BRIDGE_PREFIX):
                    try:
                        self.responses.put(json.loads(line[len(_MFLI_BRIDGE_PREFIX):]))
                    except BaseException as error:
                        self._append_diagnostic(f"JSON parse failed: {error}: {line}")
                else:
                    self._append_diagnostic(line)
        finally:
            self.responses.put({"_eof": True})
    def _read_stderr(self) -> None:
        stream = self.process.stderr if self.process is not None else None
        if stream is None:
            return
        for line in stream:
            self._append_diagnostic(line)
    def _diagnostic_suffix(self) -> str:
        if not self.diagnostics:
            return ""
        return "; legacy environment output: " + " | ".join(self.diagnostics[-5:])
    def _receive(self, timeout_s: float, request_id: int | None = None) -> dict[str, object]:
        deadline = time.monotonic() + max(0.1, float(timeout_s))
        while True:
            try:
                reply = self.responses.get(timeout=max(0.01, deadline - time.monotonic()))
            except queue.Empty as error:
                raise RuntimeError(f'The legacy LabOne bridge did not reply within {timeout_s:g} s' + self._diagnostic_suffix()) from error
            if request_id is None or reply.get('_eof') or reply.get('id') in (None, request_id):
                break
            self._append_diagnostic(f"dropped a late reply to request {reply.get('id')}")
        if reply.get("_eof"):
            exit_code = self.process.poll() if self.process is not None else None
            raise RuntimeError(f'The legacy LabOne bridge exited unexpectedly (code={exit_code})' + self._diagnostic_suffix())
        if not reply.get("ok"):
            detail = str(reply.get("error", "unknown error")).strip()
            raise RuntimeError('Legacy LabOne bridge failed: ' + detail + self._diagnostic_suffix())
        return reply
    def request(self, command: str, timeout_s: float=10.0, **parameters) -> dict[str, object]:
        if self.process is None or self.process.poll() is not None:
            raise RuntimeError('Legacy LabOne bridge is not running' + self._diagnostic_suffix())
        if self.process.stdin is None:
            raise RuntimeError("Legacy LabOne bridge stdin is unavailable")
        self.request_id = getattr(self, "request_id", 0) + 1
        payload = {"command": str(command), "id": self.request_id}
        payload.update(parameters)
        try:
            self.process.stdin.write(json.dumps(payload, ensure_ascii=True) + "\n")
            self.process.stdin.flush()
        except (BrokenPipeError, OSError) as error:
            raise RuntimeError('Cannot send a command to the legacy LabOne bridge' + self._diagnostic_suffix()) from error
        return self._receive(timeout_s, self.request_id)
    def close(self, force: bool = False) -> None:
        process = self.process
        if process is None:
            return
        if process.poll() is None and not force:
            try:
                self.request("close", timeout_s=5.0)
                try:
                    process.wait(timeout=2.0)
                except subprocess.TimeoutExpired:
                    force = True
            except BaseException:
                force = True
        if process.poll() is None and force:
            try:
                process.terminate()
                process.wait(timeout=2.0)
            except BaseException:
                try:
                    process.kill()
                except BaseException:
                    pass
        for stream in (process.stdin, process.stdout, process.stderr):
            try:
                if stream is not None:
                    stream.close()
            except BaseException:
                pass
        self.process = None
class NonLocalACController:
    CLEAR_ON_READ_QUERIES = ("LIAS?", "*ESR?", "ERRS?")
    MFLI_RANGE_FRESH_REASONS = ("initial", "STFMR frequency start")
    SR830_LIAS_UNREADABLE = 0x0F
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.resource_manager = None
        self.source = None
        self.lockins: dict[str, object] = {}
        self.mfli_daq = None
        self.mfli_bridge: LegacyMFLIBridge | None = None
        self.mfli_device = ""
        self.mfli_props: dict[str, object] = {}
        self.mfli_config: dict[str, object] = {}
        self.nanovoltmeter = None
        self.source_identity = ""
        self.lockin_identities: dict[str, str] = {}
        self.mfli_identity = ""
        self.nanovoltmeter_identity = ""
        self.source_resource = ""
        self.lockin_resources: dict[str, str] = {}
        self.nanovoltmeter_resource = ""
        self.mfli_lease_resource = ""
        self.output_enabled = False
        self.source_output_mode = "AC"
        self.lock = threading.RLock()
        self.sensitivity_indices: dict[str, int] = {}
        self.low_range_counts: dict[str, int] = {}
        self.range_cooldowns: dict[str, int] = {}
        self.overload_floors: dict[str, int] = {}
        self.overload_floor_memory: dict[tuple[str, int], int] = {}
        self.lockin_harmonics: dict[str, int] = {}
        self.mfli_low_range_count = 0
        self.mfli_range_cooldown = 0
        self.mfli_low_floor_v = 0.0
        self.mfli_stepped_down = False
        self.mfli_low_readings_needed = LOCKIN_DOWNRANGE_READINGS
        self.mfli_initial_autorange_pending = False
        self.mfli_auto_range_enabled = True
        self.mfli_in_scan = False
        self.lias_clear_pending: dict[str, bool] = {}
    @property
    def connected(self) -> bool:
        return self.source is not None and (bool(self.lockins) or self.mfli_connected or self.nanovoltmeter is not None)
    @property
    def source_connected(self) -> bool:
        return self.source is not None
    @property
    def any_connected(self) -> bool:
        return self.source is not None or bool(self.lockins) or self.mfli_connected or (self.nanovoltmeter is not None)
    @property
    def shared_source_lockin_connected(self) -> bool:
        return self.source is not None or bool(self.lockins)
    @property
    def nanovoltmeter_connected(self) -> bool:
        return self.nanovoltmeter is not None
    @property
    def mfli_connected(self) -> bool:
        return self.mfli_daq is not None or self.mfli_bridge is not None
    def lockin_connected(self, key: str) -> bool:
        return str(key) in self.lockins
    @property
    def connected_lockin_keys(self) -> tuple[str, ...]:
        return tuple(sorted(self.lockins, key=int))
    @staticmethod
    def _configure_transport(instrument) -> None:
        instrument.timeout = 5000
        instrument.write_termination = "\n"
        instrument.read_termination = "\n"
        try:
            instrument.query_delay = 0.05
        except (AttributeError, ValueError):
            pass
    @staticmethod
    def _query_float(instrument, command: str) -> float:
        return float(instrument.query(command).strip())
    def _write_6221(self, command: str) -> None:
        self.source.write(command)
        time.sleep(0.03)
        response = self.source.query("SYST:ERR?").strip()
        try:
            code = int(response.split(",", 1)[0].strip())
        except ValueError as error:
            raise RuntimeError(f"6221 error status cannot be parsed: {response}") from error
        if code != 0:
            raise RuntimeError(f"6221 reported an error after {command!r}: {response}")
    def _read_6221_output_low_to_earth(self) -> int:
        text = self.source.query(K6221_OUTPUT_LOW_QUERY).strip().upper()
        if text in ("0", "OFF"):
            return 0
        if text in ("1", "ON"):
            return 1
        raise RuntimeError(f"6221 returned an unexpected OUTP:LTE state: {text!r}")
    def _set_6221_output_low_floating(self) -> None:
        if self._read_6221_output_low_to_earth() == 0:
            return
        self._write_6221(K6221_OUTPUT_LOW_FLOATING)
        if self._read_6221_output_low_to_earth() != 0:
            raise RuntimeError('6221 output low stayed earth-grounded; set TRIAX -> OUTPUT LOW -> FLOATING on the front panel')
    def _write_sr830(self, key: str, command: str) -> None:
        lockin = self.lockins[key]
        for attempt in (1, 2):
            lockin.write(command)
            time.sleep(0.03)
            response = ""
            try:
                response = lockin.query("*ESR?").strip()
                event_status = int(float(response))
            except Exception as error:
                if attempt == 2:
                    raise RuntimeError(f'SR830 #{key} status after {command!r} is unreadable: {response!r}') from error
                self.logger(f'SR830 #{key} *ESR? after {command!r} gave {response!r}; clearing the buffer and sending the command again')
                try:
                    lockin.clear()
                except Exception:
                    pass
                time.sleep(0.08)
                continue
            if event_status & 0x30:
                raise RuntimeError(f'SR830 #{key} rejected {command!r}; *ESR?={event_status}')
            return
    def _write_2182(self, command: str) -> None:
        meter = self.nanovoltmeter
        if meter is None:
            raise RuntimeError("Keithley 2182A is not connected")
        meter.write(command)
        time.sleep(0.03)
        response = meter.query("SYST:ERR?").strip()
        try:
            code = int(response.split(",", 1)[0].strip())
        except ValueError as error:
            raise RuntimeError(f"2182A error status cannot be parsed: {response}") from error
        if code != 0:
            raise RuntimeError(f"2182A reported an error after {command!r}: {response}")
    def configure_nanovoltmeter(self, channel: int=1, nplc: float=1.0) -> dict[str, object]:
        with self.lock:
            if self.nanovoltmeter is None:
                raise RuntimeError("Keithley 2182A is not connected")
            if channel not in (1, 2):
                raise ValueError("2182A channel must be 1 or 2")
            if not 0.01 <= float(nplc) <= 60.0:
                raise ValueError("2182A NPLC must be within 0.01–60")
            meter = self.nanovoltmeter
            meter.timeout = 10000
            meter.write("*RST")
            meter.write("*CLS")
            for command in (
                ":SENS:FUNC 'VOLT'",
                f":SENS:CHAN {channel}",
                f":SENS:VOLT:NPLC {float(nplc):.12g}",
                ":SYST:AZER:STAT ON",
                ":SYST:FAZ:STAT ON",
                ":FORM:ELEM READ",
                f":SENS:VOLT:CHAN{channel}:RANG:AUTO ON",
            ):
                self._write_2182(command)
            time.sleep(0.5)
            return {
                "resource": self.nanovoltmeter_resource or NONLOCAL_2182_RESOURCE,
                "channel": channel,
                "nplc": float(nplc),
                "autozero": True,
                "front_autozero": True,
                "measurement_mode": "DC voltage (not phase-sensitive)",
            }
    def read_nanovoltmeter(self) -> float:
        with self.lock:
            if self.nanovoltmeter is None:
                raise RuntimeError("Keithley 2182A is not connected")
            response = self.nanovoltmeter.query(":READ?").strip()
            try:
                value = float(response.split(",", 1)[0].strip())
            except ValueError as error:
                raise RuntimeError(f'2182A :READ? response cannot be parsed: {response!r}') from error
            if not math.isfinite(value):
                raise RuntimeError(f"2182A returned a non-finite voltage: {response!r}")
            return value
    def _query_sr830_numbers(self, key: str, command: str, expected_count: int) -> tuple[float, ...]:
        lockin = self.lockins[key]
        last_response = ""
        last_error: BaseException | None = None
        attempts = 1 if command.strip().upper() in self.CLEAR_ON_READ_QUERIES else 3
        for attempt in range(1, attempts + 1):
            try:
                last_response = lockin.query(command).strip()
                values = tuple((float(part.strip()) for part in last_response.split(',')))
                if len(values) != expected_count:
                    raise ValueError(f'expected {expected_count} values, received {len(values)}')
                return values
            except Exception as error:
                last_error = error
                if attempt >= attempts:
                    break
                self.logger(f'SR830 #{key} query {command!r} received a misaligned reply {last_response!r}; clearing the buffer and retrying {attempt}/2')
                try:
                    lockin.clear()
                except Exception:
                    pass
                time.sleep(0.08)
        raise RuntimeError(f'SR830 #{key} query {command!r} repeatedly returned non-numeric/abnormal replies: {last_response!r}') from last_error
    def _query_sr830_status(self, key: str) -> int | None:
        try:
            value = self._query_sr830_numbers(key, "LIAS?", 1)[0]
            if not (math.isfinite(value) and float(value).is_integer() and 0 <= value <= 255):
                raise ValueError(f"not a status byte: {value!r}")
            return int(value)
        except Exception as error:
            self.logger(f'SR830 #{key} LIAS? reply unreadable ({error}); not asked again (it clears as it is read): the reading counts as overloaded')
            try:
                self.lockins[key].clear()
            except Exception:
                pass
            time.sleep(0.08)
            return None
    def read_sr830_time_constants(self, keys) -> dict[str, float]:
        values = {}
        with self.lock:
            for key in keys:
                key = str(key)
                if key not in self.lockins:
                    raise RuntimeError(f"SR830 #{key} is not connected")
                code = int(self._query_sr830_numbers(key, "OFLT?", 1)[0])
                if not 0 <= code < len(SR830_TIME_CONSTANTS_S):
                    raise RuntimeError(f"SR830 #{key} time-constant readback is invalid: OFLT {code}")
                values[key] = SR830_TIME_CONSTANTS_S[code]
        return values
    def read_sr830_filter_slopes(self, keys) -> dict[str, float]:
        values = {}
        with self.lock:
            for key in keys:
                key = str(key)
                if key not in self.lockins:
                    raise RuntimeError(f"SR830 #{key} is not connected")
                code = int(self._query_sr830_numbers(key, "OFSL?", 1)[0])
                if not 0 <= code <= 3:
                    raise RuntimeError(f"SR830 #{key} filter-slope readback is invalid: OFSL {code}")
                values[key] = 6.0 * (code + 1)
        return values
    def _ensure_resource_manager(self):
        if pyvisa is None:
            raise RuntimeError("pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py")
        if self.resource_manager is None:
            self.resource_manager = acquire_shared_visa_manager()
        return self.resource_manager
    def _close_manager_if_unused(self) -> None:
        if self.source is not None or self.lockins or self.nanovoltmeter is not None or (self.resource_manager is None):
            return
        manager = self.resource_manager
        self.resource_manager = None
        release_shared_visa_manager(manager)
    def connect_source(self, resource: str) -> str:
        with self.lock:
            if self.source is not None:
                return self.source_identity
            acquire_instrument_lease(resource, self, "Non-local 6221")
            source = None
            try:
                manager = self._ensure_resource_manager()
                source = manager.open_resource(resource)
                self._configure_transport(source)
                identity = source.query("*IDN?").strip()
                if "6221" not in identity.upper():
                    raise RuntimeError(f"{resource} is not a Keithley 6221: {identity}")
                try:
                    source.clear()
                except Exception:
                    pass
                source.write("OUTP OFF")
                self.source = source
                self.source_identity = identity
                self.source_resource = resource
                self.output_enabled = False
                self.logger(f"Non-local IV 6221 connected: {identity}")
                return identity
            except BaseException:
                if source is not None:
                    try:
                        source.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise
    def connect_lockin(self, key: str, resource: str) -> str:
        key = str(key)
        if key not in ("8", "9"):
            raise ValueError(f"Unsupported SR830 number: {key}")
        with self.lock:
            if key in self.lockins:
                return self.lockin_identities[key]
            acquire_instrument_lease(resource, self, f"Non-local SR830 #{key}")
            lockin = None
            try:
                manager = self._ensure_resource_manager()
                lockin = manager.open_resource(resource)
                self._configure_transport(lockin)
                lockin.write("OUTX 1")
                identity = lockin.query("*IDN?").strip()
                if "SR830" not in identity.upper():
                    raise RuntimeError(f"{resource} is not an SR830: {identity}")
                try:
                    lockin.clear()
                except Exception:
                    pass
                lockin.write("OUTX 1")
                time.sleep(0.05)
                show_sr830_x_and_y(lockin, self.logger, f"Non-local IV SR830 #{key}")
                self.lockins[key] = lockin
                self.lockin_identities[key] = identity
                self.lockin_resources[key] = resource
                self.sensitivity_indices.pop(key, None)
                self.low_range_counts.pop(key, None)
                self.range_cooldowns.pop(key, None)
                self.__dict__.setdefault("overload_floors", {}).pop(key, None)
                self.__dict__.setdefault("lockin_harmonics", {}).pop(key, None)
                self.logger(f"Non-local IV SR830 #{key} connected: {identity}")
                return identity
            except BaseException:
                if lockin is not None:
                    try:
                        lockin.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise
    def connect_nanovoltmeter(self, resource: str) -> str:
        with self.lock:
            if self.nanovoltmeter is not None:
                return self.nanovoltmeter_identity
            acquire_instrument_lease(resource, self, "Non-local Keithley 2182A")
            meter = None
            try:
                manager = self._ensure_resource_manager()
                meter = manager.open_resource(resource)
                self._configure_transport(meter)
                identity = meter.query("*IDN?").strip()
                if "2182" not in identity.upper():
                    raise RuntimeError(f"{resource} is not a Keithley 2182A: {identity}")
                try:
                    meter.clear()
                except Exception:
                    pass
                meter.write("*CLS")
                self.nanovoltmeter = meter
                self.nanovoltmeter_identity = identity
                self.nanovoltmeter_resource = resource
                self.logger(f"Non-local IV Keithley 2182A connected: {identity}")
                return identity
            except BaseException:
                if meter is not None:
                    try:
                        meter.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise
    @staticmethod
    def _mfli_reachable_servers(timeout_s: float=1.2, candidates=None) -> tuple[list[tuple[str, int]], list[str]]:
        reachable = []
        diagnostics = []
        for host, port in (NONLOCAL_MFLI_SERVER_CANDIDATES if candidates is None else candidates):
            try:
                with socket.create_connection((host, int(port)), timeout_s):
                    reachable.append((host, int(port)))
                    diagnostics.append(f"{host}:{port}=TCP reachable")
            except OSError as error:
                diagnostics.append(f"{host}:{port}=unreachable ({error})")
        return reachable, diagnostics
    def configure_second_harmonic(self, tau, rate=NONLOCAL_SAMPLE_HZ):
        with self.lock:
            if self.mfli_config.get('extref_demodulator') not in (1, 3) or self.mfli_config.get('harmonic') != 1:
                raise RuntimeError('Simultaneous measurement requires MF-MD: Demod 1 measures 1st harmonic, Demod 2 external reference, Demod 3 measures 2nd harmonic')
            if self.mfli_bridge is not None:
                self.mfli_bridge.request('configure_second_harmonic', timeconstant=tau, rate=rate, order=NONLOCAL_LOCKIN_FILTER_ORDER)
                return
            index = 1 if self.mfli_config['extref_demodulator'] == 3 else 2
            base = f'/{self.mfli_device}/demods/{index}/'
            for name, value in (('adcselect', 0), ('oscselect', 0), ('harmonic', 2), ('order', NONLOCAL_LOCKIN_FILTER_ORDER), ('enable', 1)):
                self.mfli_daq.setInt(base + name, value)
            self.mfli_daq.setDouble(base + 'timeconstant', tau)
            self.mfli_daq.setDouble(base + 'rate', rate)
            self.mfli_daq.sync()
            for name, value in (('adcselect', 0), ('oscselect', 0), ('harmonic', 2), ('enable', 1)):
                if self.mfli_daq.getInt(base + name) != value:
                    raise RuntimeError('Zurich 2nd-harmonic configuration readback mismatch: ' + name)
    def configure_third_harmonic(self, tau, rate=NONLOCAL_SAMPLE_HZ):
        with self.lock:
            if self.mfli_config.get('extref_demodulator') not in (1, 3) or self.mfli_config.get('harmonic') != 1:
                raise RuntimeError('Simultaneous measurement requires MF-MD: Demod 1 measures 1st harmonic, Demod 2 external reference, Demod 4 measures 3rd harmonic')
            if self.mfli_bridge is not None:
                self.mfli_bridge.request('configure_third_harmonic', timeconstant=tau, rate=rate, order=NONLOCAL_LOCKIN_FILTER_ORDER)
                return
            index = 2 if self.mfli_config['extref_demodulator'] == 3 else 3
            base = f'/{self.mfli_device}/demods/{index}/'
            for name, value in (('adcselect', 0), ('oscselect', 0), ('harmonic', 3), ('order', NONLOCAL_LOCKIN_FILTER_ORDER), ('enable', 1)):
                self.mfli_daq.setInt(base + name, value)
            self.mfli_daq.setDouble(base + 'timeconstant', tau)
            self.mfli_daq.setDouble(base + 'rate', rate)
            self.mfli_daq.sync()
            for name, value in (('adcselect', 0), ('oscselect', 0), ('harmonic', 3), ('enable', 1)):
                if self.mfli_daq.getInt(base + name) != value:
                    raise RuntimeError('Zurich 3rd-harmonic configuration readback mismatch: ' + name)
    def disable_unused_ppms_demods(self, mode):
        extref = self.mfli_config.get('extref_demodulator')
        measuring = (0, 1, 2) if extref == 3 else (0, 2, 3) if extref == 1 and self.mfli_has_multi_demod() else (0,)
        used = len(PPMS_ZURICH_MODE_ORDERS.get(str(mode), (1,)))
        indices = tuple(measuring[used:])
        with self.lock:
            if self.mfli_bridge is not None:
                if indices:
                    self.mfli_bridge.request('disable_unused_demods', indices=list(indices))
                return
            for index in indices:
                if index == self.mfli_config.get('extref_demodulator'):
                    raise RuntimeError('Cannot disable the external-reference demodulator that is in use')
                node = f'/{self.mfli_device}/demods/{index}/enable'
                self.mfli_daq.setInt(node, 0)
                self.mfli_daq.sync()
                if self.mfli_daq.getInt(node) != 0:
                    raise RuntimeError('Unused demodulator disable readback mismatch')
    def connect_mfli(self, device_id: str) -> str:
        requested = str(device_id).strip().lower()
        if not requested:
            raise ValueError("Please enter the Zurich MFLI API device name, e.g. dev4435")
        if requested.startswith("mf-"):
            requested = requested[3:]
        with self.lock:
            if self.mfli_connected:
                return self.mfli_identity
            direct_errors: list[str] = []
            server_reports: dict[tuple[str, int], str] = {}
            server_override = getattr(self, 'mfli_server_candidates', None)
            reachable_servers, tcp_diagnostics = self._mfli_reachable_servers(candidates=server_override) if server_override is not None else self._mfli_reachable_servers()
            self.logger("MFLI network pre-check: " + "; ".join(tcp_diagnostics))
            if not reachable_servers:
                diagnostic_text = "; ".join(tcp_diagnostics)
                if server_override is not None:
                    checks = '\n'.join((f'Test-NetConnection {host} -Port {port}' for host, port in server_override))
                    raise RuntimeError(
                        f'Zurich {requested}: configured Data Server is unreachable; '
                        'the LabOne API handshake has not started.\n\n'
                        f'Quick check: {diagnostic_text}\n\n'
                        'Verify the device address in MF Device Finder, its power and Ethernet/USB connection. '
                        'Run on the measurement PC:\n' + checks + '\n\n'
                        'TCP reachability is required but does not prove API compatibility. '
                        'Do not change the PC IP based on settings for another instrument.\n\n'
                        + zurich_choice_hint(requested)
                    )
                raise RuntimeError(
                    "The Zurich MFLI Data Server is currently unreachable; the program has not entered the "
                    "LabOne API handshake.\n\n"
                    f"Quick check: {diagnostic_text}\n\n"
                    "Please check in order:\n"
                    "1. The MFLI is powered on and connected to the PC via the rear-panel USB Device port;\n"
                    "2. The Windows USB/RNDIS network adapter is enabled and the PC address should be "
                    "192.168.69.77;\n"
                    "3. Run in PowerShell: ping 192.168.69.78;\n"
                    "4. Run: Test-NetConnection 192.168.69.78 -Port 8004.\n\n"
                    "Only after TcpTestSucceeded=True can the Python API connect.\n\n"
                    + zurich_choice_hint(requested)
                )
            mfli_lease_resource = f"LABONE::{requested}"
            acquire_instrument_lease(mfli_lease_resource, self, 'Non-local Zurich MFLI')
            self.mfli_lease_resource = mfli_lease_resource
            if sys.platform == "win32":
                native_adapters = (('LabOne C API', LabOneCAPIAdapter, 'current-python-labone-c-api'), ('LabOne .NET', LabOneDotNetAdapter, 'current-python-labone-dotnet'))
                for adapter_label, adapter_class, connection_name in native_adapters:
                    missing = [name for name in NONLOCAL_MFLI_DAQ_METHODS if not callable(getattr(adapter_class, name, None))]
                    if missing:
                        note = f"{adapter_label}: skipped, it has no {', '.join(missing)} (the MFLI set-up and reads need them)"
                        direct_errors.append(note)
                        self.logger(f"Zurich MFLI {note}")
                        continue
                    for server_host, server_port in reachable_servers:
                        daq = None
                        try:
                            daq = adapter_class(server_host, server_port, NONLOCAL_MFLI_API_LEVEL)
                            sample_node = f'/{requested}/demods/{NONLOCAL_MFLI_DEMODULATOR}/sample'
                            enable_node = f'/{requested}/demods/{NONLOCAL_MFLI_DEMODULATOR}/enable'
                            try:
                                daq.setInt(enable_node, 1)
                                daq.sync()
                                daq.getSample(sample_node)
                            except BaseException as initial_error:
                                attachment_errors = [f"attached read: {initial_error}"]
                                for interface in ("PCIe", "1GbE", "USB"):
                                    try:
                                        daq.connectDevice(requested, interface)
                                        daq.setInt(enable_node, 1)
                                        daq.sync()
                                        daq.getSample(sample_node)
                                        break
                                    except BaseException as attach_error:
                                        attachment_errors.append(f'{interface}: {attach_error}')
                                else:
                                    report = self._mfli_server_devices(daq)
                                    if report:
                                        server_reports[(server_host, server_port)] = report
                                    raise RuntimeError(f'Data Server connected, but {requested} cannot be read' + (f' (server sees {report})' if report else '') + ': ' + ' | '.join(attachment_errors))
                            version = ""
                            for version_node in ('/zi/about/version', '/zi/about/revision'):
                                try:
                                    version = str(daq.getString(version_node)).strip()
                                except BaseException:
                                    continue
                                if version:
                                    break
                            identity_parts = ["Zurich Instruments MFLI", requested]
                            if version:
                                identity_parts.append(f"LabOne {version}")
                            identity = " · ".join(identity_parts)
                            self.mfli_daq = daq
                            self.mfli_bridge = None
                            self.mfli_device = requested
                            self.mfli_props = {'serveraddress': server_host, 'serverport': server_port, 'serverversion': version, 'connection': connection_name, 'api_dll': str(daq.api_dll)}
                            self.mfli_config = {}
                            self.mfli_identity = identity
                            self.logger(f'Non-local Zurich MFLI loaded by the current Python {adapter_label}: {identity} @ {server_host}:{server_port}')
                            return identity
                        except BaseException as error:
                            direct_errors.append(f'{adapter_label} {server_host}:{server_port}: {error}')
                            if daq is not None:
                                try:
                                    daq.disconnect()
                                except BaseException:
                                    pass
                            self.logger(f'The current Python loaded {adapter_label} but connecting to {server_host}:{server_port} failed: {error}')
            if zi_core is not None:
                for server_host, server_port in reachable_servers:
                    daq = None
                    try:
                        daq = zi_core.ziDAQServer(server_host, server_port, NONLOCAL_MFLI_API_LEVEL, allow_version_mismatch=True)
                        sample_node = f'/{requested}/demods/{NONLOCAL_MFLI_DEMODULATOR}/sample'
                        try:
                            visible_nodes = daq.listNodes(f'/{requested}', recursive=False, absolute=True)
                        except TypeError:
                            visible_nodes = daq.listNodes(f"/{requested}", 0)
                        if not visible_nodes:
                            attachment_errors = []
                            for interface in ("PCIe", "1GbE", "USB"):
                                try:
                                    daq.connectDevice(requested, interface)
                                    break
                                except BaseException as attach_error:
                                    attachment_errors.append(f'{interface}: {attach_error}')
                            else:
                                report = self._mfli_server_devices(daq)
                                if report:
                                    server_reports[(server_host, server_port)] = report
                                raise RuntimeError(f'Data Server connected, but {requested} cannot be attached' + (f' (server sees {report})' if report else '') + ': ' + ' | '.join(attachment_errors))
                        daq.setInt(f'/{requested}/demods/{NONLOCAL_MFLI_DEMODULATOR}/enable', 1)
                        daq.sync()
                        daq.getSample(sample_node)
                        version = ""
                        for version_node in ('/zi/about/version', '/zi/about/revision'):
                            try:
                                version = str(daq.getString(version_node)).strip()
                            except BaseException:
                                continue
                            if version:
                                break
                        identity_parts = ["Zurich Instruments MFLI", requested]
                        if version:
                            identity_parts.append(f"LabOne {version}")
                        identity = " · ".join(identity_parts)
                        self.mfli_daq = daq
                        self.mfli_bridge = None
                        self.mfli_device = requested
                        self.mfli_props = {'serveraddress': server_host, 'serverport': server_port, 'serverversion': version, 'connection': 'current-python-core', 'allow_version_mismatch': True}
                        self.mfli_config = {}
                        self.mfli_identity = identity
                        self.logger(f'Non-local Zurich MFLI connected directly by the current Python Core API: {identity} @ {server_host}:{server_port}')
                        return identity
                    except BaseException as error:
                        direct_errors.append(f'Core {server_host}:{server_port}: {error}')
                        if daq is not None:
                            try:
                                daq.disconnect()
                            except BaseException:
                                pass
                        self.logger(f'The current Python Core API connection to {server_host}:{server_port} failed: {error}')
            bridge = None
            try:
                bridge = LegacyMFLIBridge(requested)
                self.mfli_daq = None
                self.mfli_bridge = bridge
                self.mfli_device = bridge.device
                self.mfli_props = {
                    "serverversion": bridge.version,
                    "connection": "labone-18.12-python37-bridge",
                    "python": str(bridge.python_path),
                    "options": bridge.options,
                    "has_demod_2": bridge.has_demod_2,
                    "has_demod_4": bridge.__dict__.get("has_demod_4", False),
                }
                self.mfli_config = {}
                self.mfli_identity = bridge.identity
                self.logger(f'Non-local Zurich MFLI connected through the legacy LabOne 18.12 environment: {bridge.identity}')
                return bridge.identity
            except BaseException as bridge_error:
                if bridge is not None:
                    bridge.close(force=True)
                direct_errors.append(f"18.12 Python 3.7 bridge: {bridge_error}")
                self.logger(f'The legacy LabOne 18.12 bridge is unavailable, continuing to try Discovery: {bridge_error}')
            if zi_core is None and zi_utils is not None and reachable_servers:
                daq = None
                try:
                    session = zi_utils.create_api_session(requested, NONLOCAL_MFLI_API_LEVEL)
                    if not isinstance(session, tuple) or len(session) < 3:
                        raise RuntimeError(f'create_api_session returned an unexpected format: {session!r}')
                    daq, discovered, props = session[:3]
                    device = str(discovered).strip().lower()
                    if not device:
                        raise RuntimeError("LabOne Discovery did not return an MFLI device name")
                    daq.setInt(f'/{device}/demods/{NONLOCAL_MFLI_DEMODULATOR}/enable', 1)
                    daq.sync()
                    daq.getSample(f'/{device}/demods/{NONLOCAL_MFLI_DEMODULATOR}/sample')
                    identity_parts = ["Zurich Instruments MFLI", device]
                    if isinstance(props, dict):
                        version = props.get("serverversion") or props.get("version")
                        if version:
                            identity_parts.append(f"LabOne {version}")
                    identity = " · ".join(identity_parts)
                    self.mfli_daq = daq
                    self.mfli_bridge = None
                    self.mfli_device = device
                    self.mfli_props = dict(props) if isinstance(props, dict) else {}
                    self.mfli_props["connection"] = "current-python-discovery"
                    self.mfli_config = {}
                    self.mfli_identity = identity
                    self.logger(f'Non-local Zurich MFLI connected by the current Python Discovery: {identity}')
                    return identity
                except BaseException as error:
                    direct_errors.append(f"Discovery: {error}")
                    if daq is not None:
                        try:
                            daq.disconnect()
                        except BaseException:
                            pass
                    self.logger(f'The current Python Discovery failed; trying the legacy environment bridge as a last resort: {error}')
            direct_detail = " | ".join(direct_errors)
            release_instrument_lease(self.mfli_lease_resource, self)
            self.mfli_lease_resource = ""
            raise RuntimeError(self._mfli_connect_failure_message(requested, reachable_servers, direct_errors, server_reports))
    @staticmethod
    def _mfli_server_devices(daq) -> str:
        parts = []
        for label, node in (('visible', '/zi/devices/visible'), ('connected', '/zi/devices/connected')):
            try:
                value = str(daq.getString(node)).strip()
            except BaseException:
                continue
            if value:
                parts.append(f"{label}={value}")
        return "; ".join(parts)
    @staticmethod
    def _mfli_connect_failure_message(requested: str, reachable_servers, direct_errors, server_reports) -> str:
        servers_text = ', '.join((f'{host}:{port}' for host, port in reachable_servers)) or '8004'
        reports_text = '; '.join((f'{host}:{port} → {report}' for (host, port), report in server_reports.items() if report))
        device_missing = bool(reports_text) and requested not in reports_text.lower()
        if device_missing:
            headline = f'Zurich MFLI {requested}: Data Server {servers_text} is reachable, but {requested} is not on that server (devices visible to the server: {reports_text}).'
            advice = (
                "Check the device name in the panel (it must be this MFLI's own DEV number) and make sure it is "
                "connected to this PC by USB or Ethernet and attached to this PC's Data Server in LabOne; "
                "the other MFLI's built-in 192.168.69.78 server can only see itself. "
                + zurich_choice_hint(requested)
            )
        else:
            last_error = short_status_error(RuntimeError(direct_errors[-1]), 160) if direct_errors else 'the current Python has no usable LabOne API'
            headline = f'Zurich MFLI {requested}: Data Server {servers_text} is reachable, but the LabOne API handshake failed ({last_error}).'
            advice = (
                "Make sure the LabOne / zhinst version on this PC matches the instrument firmware; if this instrument runs "
                "LabOne 18.12, close this program, run "
                "INSTALL_MFLI_LABONE_18_12.bat from the same folder, and restart the program after installation."
            )
        direct_detail = " | ".join(direct_errors) or "no API attempt recorded"
        sections = [headline, f"Connection diagnostics: {direct_detail}"]
        if reports_text:
            sections.append(f"Server device list: {reports_text}")
        sections.append(advice)
        return "\n\n".join(sections)
    @staticmethod
    def _mfli_scalar(value, field: str) -> float:
        try:
            candidate = value[field]
        except (KeyError, TypeError) as error:
            raise RuntimeError(f"MFLI sample lacks the {field!r} field") from error
        if np is not None:
            array = np.asarray(candidate).reshape(-1)
            if array.size == 0:
                raise RuntimeError(f"MFLI sample field {field!r} is empty")
            result = float(array[-1])
        elif isinstance(candidate, (tuple, list)):
            if not candidate:
                raise RuntimeError(f"MFLI sample field {field!r} is empty")
            result = float(candidate[-1])
        else:
            result = float(candidate)
        if not math.isfinite(result):
            raise RuntimeError(f"MFLI sample field {field!r} is not a finite value")
        return result
    @staticmethod
    def _mfli_phase_degrees(x: float, y: float) -> float:
        return math.degrees(math.atan2(float(y), float(x)))
    def configure_mfli(
        self,
        coupling: str,
        harmonic: int,
        channel: str,
        reference_source: str = NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT,
        sample_rate_hz: float = NONLOCAL_SAMPLE_HZ,
        input_impedance: str = "10 MΩ",
        input_scaling: float = NONLOCAL_MFLI_INPUT_SCALING,
        timeconstant_s: float = NONLOCAL_LOCKIN_TIME_CONSTANT_S,
        external_reference_demodulator=None,
    ) -> dict[str, object]:
        if not self.mfli_connected:
            raise RuntimeError("Zurich MFLI is not connected")
        coupling = str(coupling).strip().upper()
        channel = str(channel).strip().upper()
        reference_source = str(reference_source).strip()
        harmonic = int(harmonic)
        sample_rate_hz = float(sample_rate_hz)
        input_impedance = str(input_impedance).strip()
        input_scaling = float(input_scaling)
        timeconstant_s = float(timeconstant_s)
        if coupling not in {"AC", "DC"}:
            raise ValueError("MFLI input coupling can only be AC or DC")
        if harmonic < 1:
            raise ValueError("MFLI harmonic must be a positive integer")
        if not math.isfinite(sample_rate_hz) or sample_rate_hz <= 0:
            raise ValueError("MFLI sampling rate must be a finite positive number")
        transfer_rate_hz = max(10.0, min(1000.0, sample_rate_hz * 5.0))
        if channel not in {"X", "Y", "R"}:
            raise ValueError("MFLI read channel can only be X, Y or R")
        if reference_source not in NONLOCAL_MFLI_REFERENCE_INPUTS:
            choices = ", ".join(NONLOCAL_MFLI_REFERENCE_INPUTS)
            raise ValueError(f"MFLI external reference input must be one of: {choices}")
        impedance_choices = {"10 MΩ": 0, "50 Ω": 1}
        if input_impedance not in impedance_choices:
            raise ValueError("MFLI Signal Input 1 input impedance can only be 10 MΩ or 50 Ω")
        requested_imp50 = impedance_choices[input_impedance]
        if not math.isfinite(input_scaling) or input_scaling <= 0:
            raise ValueError("MFLI Signal Input 1 Scaling must be a finite positive number")
        if not math.isfinite(timeconstant_s) or timeconstant_s <= 0:
            raise ValueError("MFLI time constant must be a finite positive number")
        reference_adcselect = NONLOCAL_MFLI_REFERENCE_INPUTS[reference_source]
        options_text = str(self.mfli_props.get("options", "")).upper()
        has_demod_2 = bool(self.mfli_props.get("has_demod_2", False))
        if self.mfli_bridge is None and not options_text:
            try:
                options_text = str(self.mfli_daq.getString(f'/{self.mfli_device}/features/options')).upper()
                self.mfli_props["options"] = options_text
            except BaseException:
                pass
        if self.mfli_bridge is None and not has_demod_2:
            try:
                self.mfli_daq.getInt(f'/{self.mfli_device}/demods/{NONLOCAL_MFLI_EXTREF_DEMODULATOR}/enable')
                has_demod_2 = True
            except BaseException:
                has_demod_2 = False
            self.mfli_props["has_demod_2"] = has_demod_2
        has_multi_demod = 'MD' in options_text if options_text else has_demod_2
        extref_demod = NONLOCAL_MFLI_EXTREF_DEMODULATOR if has_multi_demod else NONLOCAL_MFLI_DEMODULATOR
        if external_reference_demodulator is not None:
            if external_reference_demodulator != 3 or not self.mfli_has_multi_demod():
                raise RuntimeError('Demod 4 external reference requires MF-MD multi-demodulator support')
            extref_demod = 3
        extref = NONLOCAL_MFLI_EXTREF_CHANNEL
        if self.mfli_bridge is None and extref_demod == 3:
            routes = [i for i in range(2) if int(self.mfli_daq.getInt(f'/{self.mfli_device}/extrefs/{i}/demodselect')) == 3]
            if len(routes) != 1:
                raise RuntimeError('Cannot identify the external-reference controller for Demod 4')
            extref = routes[0]
        if self.mfli_bridge is None:
            for other in range(2):
                if other == extref:
                    continue
                try:
                    self.mfli_daq.setInt(f'/{self.mfli_device}/extrefs/{other}/enable', 0)
                except BaseException:
                    pass
        if self.mfli_bridge is not None:
            reply = self.mfli_bridge.request(
                "configure",
                coupling=coupling,
                harmonic=harmonic,
                extref_demod=extref_demod,
                reference_adcselect=reference_adcselect,
                timeconstant_s=timeconstant_s,
                filter_order=NONLOCAL_LOCKIN_FILTER_ORDER,
                sample_rate_hz=transfer_rate_hz,
                input_imp50=requested_imp50,
                input_scaling=input_scaling,
            )
            actual_ac = int(reply["actual_ac"])
            actual_imp50 = int(reply["actual_imp50"])
            actual_scaling = float(reply["actual_scaling"])
            actual_harmonic = int(reply["actual_harmonic"])
            actual_extref_harmonic = int(reply["actual_extref_harmonic"])
            extref_enabled = int(reply["extref_enabled"])
            extref_adcselect = int(reply["extref_adcselect"])
            actual_timeconstant = float(reply["timeconstant_s"])
            actual_filter_order = int(reply["filter_order"])
            actual_sample_rate = float(reply["sample_rate_hz"])
            input_range_v = float(reply["input_range_v"])
        else:
            device = self.mfli_device
            demod = NONLOCAL_MFLI_DEMODULATOR
            ac_node = f"/{device}/sigins/0/ac"
            imp50_node = f"/{device}/sigins/0/imp50"
            scaling_node = f"/{device}/sigins/0/scaling"
            harmonic_node = f"/{device}/demods/{demod}/harmonic"
            enable_node = f"/{device}/demods/{demod}/enable"
            osc_node = f"/{device}/demods/{demod}/oscselect"
            extref_demod_node = f"/{device}/extrefs/{extref}/demodselect"
            extref_auto_node = f"/{device}/extrefs/{extref}/automode"
            extref_enable_node = f"/{device}/extrefs/{extref}/enable"
            extref_adc_node = f"/{device}/extrefs/{extref}/adcselect"
            measurement_adc_node = f"/{device}/demods/{demod}/adcselect"
            timeconstant_node = f"/{device}/demods/{demod}/timeconstant"
            order_node = f"/{device}/demods/{demod}/order"
            rate_node = f"/{device}/demods/{demod}/rate"
            self.mfli_daq.setInt(ac_node, 1 if coupling == "AC" else 0)
            self.mfli_daq.setInt(imp50_node, requested_imp50)
            self.mfli_daq.setDouble(scaling_node, input_scaling)
            ext_demod_node = f'/{device}/demods/{extref_demod}/adcselect'
            ext_osc_node = f'/{device}/demods/{extref_demod}/oscselect'
            ext_harmonic_node = f'/{device}/demods/{extref_demod}/harmonic'
            ext_demod_enable_node = f'/{device}/demods/{extref_demod}/enable'
            self.mfli_daq.setInt(ext_demod_node, reference_adcselect)
            self.mfli_daq.setInt(ext_osc_node, 0)
            if extref_demod != demod:
                self.mfli_daq.setInt(ext_harmonic_node, 1)
            self.mfli_daq.setInt(ext_demod_enable_node, 1)
            selected_extref_input = int(self.mfli_daq.getInt(ext_demod_node))
            try:
                self.mfli_daq.setInt(extref_demod_node, extref_demod)
            except BaseException:
                pass
            try:
                self.mfli_daq.setInt(extref_auto_node, 4)
            except BaseException:
                pass
            self.mfli_daq.setInt(extref_enable_node, 1)
            if external_reference_demodulator is not None:
                self.mfli_daq.sync()
                if self.mfli_daq.getInt(extref_demod_node) != extref_demod:
                    raise RuntimeError('Zurich external reference Demod 4 routing readback mismatch')
            if extref_demod == demod:
                self.mfli_daq.sync()
                if selected_extref_input != reference_adcselect:
                    raise RuntimeError(f'MFLI single-demodulator external reference failed to select {reference_source}: expected {reference_adcselect}, readback {selected_extref_input}')
                self.mfli_daq.setInt(measurement_adc_node, 0)
            self.mfli_daq.setInt(osc_node, 0)
            self.mfli_daq.setInt(harmonic_node, harmonic)
            self.mfli_daq.setDouble(timeconstant_node, timeconstant_s)
            self.mfli_daq.setInt(order_node, NONLOCAL_LOCKIN_FILTER_ORDER)
            self.mfli_daq.setDouble(rate_node, transfer_rate_hz)
            self.mfli_daq.setInt(enable_node, 1)
            self.mfli_daq.sync()
            actual_ac = int(self.mfli_daq.getInt(ac_node))
            actual_imp50 = int(self.mfli_daq.getInt(imp50_node))
            actual_scaling = float(self.mfli_daq.getDouble(scaling_node))
            actual_harmonic = int(self.mfli_daq.getInt(harmonic_node))
            actual_extref_harmonic = int(self.mfli_daq.getInt(ext_harmonic_node)) if extref_demod != demod else 1
            extref_enabled = int(self.mfli_daq.getInt(extref_enable_node))
            input_range_v = float(self.mfli_daq.getDouble(f'/{device}/sigins/0/range'))
            actual_timeconstant = float(self.mfli_daq.getDouble(timeconstant_node))
            actual_filter_order = int(self.mfli_daq.getInt(order_node))
            actual_sample_rate = float(self.mfli_daq.getDouble(rate_node))
            if extref_demod != demod:
                try:
                    selected_extref_input = int(self.mfli_daq.getInt(extref_adc_node))
                except BaseException:
                    pass
            extref_adcselect = selected_extref_input
        if actual_ac != (1 if coupling == "AC" else 0):
            raise RuntimeError(f"MFLI AC/DC readback mismatch: {actual_ac}")
        if actual_imp50 != requested_imp50:
            raise RuntimeError(f'MFLI Signal Input 1 input impedance readback mismatch: expected {input_impedance}, imp50={actual_imp50}')
        if not math.isclose(actual_scaling, input_scaling, rel_tol=1e-09, abs_tol=1e-12):
            raise RuntimeError(f'MFLI Signal Input 1 Scaling readback mismatch: expected {input_scaling:g}, readback {actual_scaling:g}')
        if actual_harmonic != harmonic:
            raise RuntimeError(f'MFLI harmonic readback mismatch: requested {harmonic}, readback {actual_harmonic}')
        if actual_extref_harmonic != 1:
            raise RuntimeError(f'MFLI external-reference PLL harmonic must be 1: readback {actual_extref_harmonic}')
        if extref_enabled != 1:
            raise RuntimeError(f'MFLI {reference_source} external reference was not enabled successfully')
        if extref_adcselect != reference_adcselect:
            raise RuntimeError(f'MFLI external reference input readback mismatch: expected {reference_source}({reference_adcselect}), readback {extref_adcselect}')
        if not math.isclose(actual_timeconstant, timeconstant_s, rel_tol=0.05, abs_tol=1e-06):
            raise RuntimeError(f'MFLI time constant readback mismatch: requested {timeconstant_s:g} s, readback {actual_timeconstant:g} s')
        if actual_filter_order != NONLOCAL_LOCKIN_FILTER_ORDER:
            raise RuntimeError(f'MFLI filter order readback mismatch: {actual_filter_order}')
        if not math.isfinite(actual_sample_rate) or actual_sample_rate < sample_rate_hz:
            raise RuntimeError(f'MFLI data transfer rate is insufficient: {actual_sample_rate:g} Sa/s')
        self.mfli_config = {
            "meter_type": "MFLI",
            "resource": self.mfli_device,
            "coupling": "AC" if actual_ac else "DC",
            "harmonic": actual_harmonic,
            "channel": channel,
            "reference_source": reference_source,
            "reference_adcselect": reference_adcselect,
            "extref_channel": (int(reply.get("extref_channel", 0)) if self.mfli_bridge is not None else extref),
            "extref_demodulator": extref_demod,
            "extref_harmonic": actual_extref_harmonic,
            "input_range_v": input_range_v,
            "input_impedance": input_impedance,
            "input_scaling": actual_scaling,
            "auto_range": True,
            "timeconstant_s": actual_timeconstant,
            "filter_order": actual_filter_order,
            "sample_rate_hz": actual_sample_rate,
        }
        self.mfli_low_range_count = 0
        self.mfli_range_cooldown = 0
        self.mfli_initial_autorange_pending = True
        self.forget_mfli_range_guard()
        return dict(self.mfli_config)
    def forget_mfli_range_guard(self) -> None:
        self.mfli_low_floor_v = 0.0
        self.mfli_stepped_down = False
        self.mfli_low_readings_needed = LOCKIN_DOWNRANGE_READINGS
    def read_mfli(self, expected_frequency_hz: float) -> dict[str, object]:
        if not self.mfli_connected:
            raise RuntimeError("Zurich MFLI is not connected")
        if self.mfli_bridge is not None:
            sample = self.mfli_bridge.request("read")["sample"]
        else:
            sample = self.mfli_daq.getSample(f'/{self.mfli_device}/demods/{NONLOCAL_MFLI_DEMODULATOR}/sample')
            sample = dict(sample)
            try:
                sample['device_status_flags'] = int(self.mfli_daq.getInt(f'/{self.mfli_device}/status/flags/binary'))
            except Exception:
                sample["device_status_flags"] = None
            try:
                sample['extref_locked'] = int(self.mfli_daq.getInt(f"/{self.mfli_device}/extrefs/{self.mfli_config.get('extref_channel', NONLOCAL_MFLI_EXTREF_CHANNEL)}/locked"))
            except BaseException:
                sample["extref_locked"] = None
            range_node = f"/{self.mfli_device}/sigins/0/range"
            max_node = f"/{self.mfli_device}/sigins/0/max"
            min_node = f"/{self.mfli_device}/sigins/0/min"
            sample['input_range_v'] = float(self.mfli_daq.getDouble(range_node))
            try:
                sample['input_max_normalized'] = float(self.mfli_daq.getDouble(max_node))
                sample['input_min_normalized'] = float(self.mfli_daq.getDouble(min_node))
                self.mfli_daq.setDouble(max_node, 0.0)
                self.mfli_daq.setDouble(min_node, 0.0)
            except BaseException:
                sample["input_max_normalized"] = None
                sample["input_min_normalized"] = None
        x = self._mfli_scalar(sample, "x")
        y = self._mfli_scalar(sample, "y")
        r = math.hypot(x, y)
        phase_deg = self._mfli_phase_degrees(x, y)
        harmonic = int(self.mfli_config.get("harmonic", 1))
        reported_frequency = math.nan
        try:
            reported_frequency = self._mfli_scalar(sample, "frequency")
            candidates = (reported_frequency, reported_frequency / max(harmonic, 1))
            reference_frequency = min(candidates, key=lambda value: abs(value - expected_frequency_hz))
        except RuntimeError:
            reference_frequency = float(expected_frequency_hz)
        frequency_valid = math.isclose(reference_frequency, expected_frequency_hz, rel_tol=0.005, abs_tol=0.1)
        raw_extref_locked = sample.get("extref_locked")
        extref_locked = None if raw_extref_locked is None else bool(round(float(raw_extref_locked)))
        reference_valid = frequency_valid and extref_locked is not False
        try:
            flags = int(round(self._mfli_scalar(sample, "flags")))
        except RuntimeError:
            flags = 0
        status_parts = []
        raw_device_flags = sample.get("device_status_flags")
        try:
            device_flags = int(raw_device_flags) if raw_device_flags is not None else None
            if device_flags is not None and device_flags < 0:
                device_flags = None
        except (TypeError, ValueError, OverflowError):
            device_flags = None
        input_overload = None if device_flags is None else bool(device_flags & 0x3)
        if input_overload:
            status_parts.append("MFLI input OVERLOAD")
        if flags:
            status_parts.append(f"LabOne flags={flags}")
        if extref_locked is False:
            reference_source = str(self.mfli_config.get('reference_source', NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT))
            status_parts.append(f"{reference_source} external reference not locked")
        elif extref_locked is None and frequency_valid:
            status_parts.append("LabOne 18.12 judges LOCK by reference-frequency convergence")
        if not frequency_valid:
            status_parts.append("reference frequency mismatch")
        input_range_v = self._mfli_scalar(sample, "input_range_v")
        input_extrema = []
        for field in ("input_max_normalized", "input_min_normalized"):
            try:
                input_extrema.append(abs(self._mfli_scalar(sample, field)))
            except (RuntimeError, TypeError, ValueError):
                pass
        input_utilization = max(input_extrema) if input_extrema else min(1.0, abs(r) / max(input_range_v, 1e-30))
        return {
            "meter_type": "MFLI",
            "voltage": {"X": x, "Y": y, "R": r}.get(
                str(self.mfli_config.get("channel", "R")), r
            ),
            "X": x,
            "Y": y,
            "R": r,
            "phase_deg": phase_deg,
            "reference_frequency_hz": reference_frequency,
            "demodulation_frequency_hz": reported_frequency,
            "reference_source": str(
                self.mfli_config.get(
                    "reference_source",
                    NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT,
                )
            ),
            "extref_locked": extref_locked,
            "lia_status": flags | (0 if reference_valid else 8),
            "status_text": "; ".join(status_parts) if status_parts else "OK",
            "reference_valid": reference_valid,
            "sensitivity_index": "",
            "input_range_v": input_range_v,
            "input_utilization": input_utilization,
            "input_extrema_valid": len(input_extrema) == 2 and all(
                math.isfinite(value) for value in input_extrema
            ),
            "device_status_flags": device_flags,
            "input_overload": input_overload,
            "auto_range": "",
        }
    def read_mfli_four_demods(self):
        with self.lock:
            if not self.mfli_connected:
                raise RuntimeError("Zurich MFLI is not connected")
            count = 4 if self.mfli_has_multi_demod() else 2 if self.mfli_props.get("has_demod_2") else 1
            if self.mfli_bridge is not None:
                channels = self.mfli_bridge.request("read_demods", count=count)["demods"]
            else:
                channels = []
                for index in range(count):
                    node = f"/{self.mfli_device}/demods/{index}"
                    enabled = int(self.mfli_daq.getInt(node + "/enable"))
                    if not enabled:
                        channels.append(dict(enabled=0))
                        continue
                    raw = self.mfli_daq.getSample(node + "/sample")
                    try:
                        timestamp = self._mfli_scalar(raw, "timestamp")
                    except (RuntimeError, KeyError):
                        timestamp = None
                    channels.append(dict(x=self._mfli_scalar(raw, "x"), y=self._mfli_scalar(raw, "y"),
                        frequency=self._mfli_scalar(raw, "frequency"), timestamp=timestamp,
                        harmonic=int(self.mfli_daq.getInt(node + "/harmonic")),
                        adcselect=int(self.mfli_daq.getInt(node + "/adcselect")), enabled=enabled))
            channels = list(channels) + [dict(enabled=0)] * (4 - len(channels))
            if len(channels) != 4:
                raise RuntimeError("Zurich must read back all four Demod channels")
            fields = {}
            for index, channel in enumerate(channels, 1):
                prefix = f'zurich_demod{index}_'
                if not channel['enabled']:
                    fields.update({prefix + key: '' for key in ('x_v', 'y_v', 'r_v', 'theta_deg', 'frequency_hz', 'timestamp_ticks', 'harmonic', 'input')})
                    fields.update({prefix+'enabled': 0, prefix+'status': 'disabled'})
                    continue
                x, y, frequency = (float(channel[k]) for k in ('x', 'y', 'frequency'))
                if not all(math.isfinite(v) for v in (x, y, frequency)):
                    raise RuntimeError(f"Zurich Demod {index} readback is invalid")
                prefix = f'zurich_demod{index}_'
                fields.update({prefix+'x_v': x, prefix+'y_v': y, prefix+'r_v': math.hypot(x, y),
                    prefix+'theta_deg': math.degrees(math.atan2(y, x)), prefix+'frequency_hz': frequency,
                    prefix+'timestamp_ticks': channel.get('timestamp') if channel.get('timestamp') is not None else '',
                    prefix+'harmonic': channel['harmonic'], prefix+'input': channel['adcselect'],
                    prefix+'enabled': channel['enabled'], prefix+'status': 'enabled'})
            return fields
    def connect(self, source_resource: str, lockin_resources: dict[str, str]) -> tuple[str, dict[str, str]]:
        if not lockin_resources:
            raise ValueError("Select at least one SR830")
        source_was_connected = self.source_connected
        existing_keys = set(self.connected_lockin_keys)
        try:
            source_identity = self.connect_source(source_resource)
            for key, resource in lockin_resources.items():
                self.connect_lockin(key, resource)
            identities = {key: self.lockin_identities[key] for key in lockin_resources}
            return source_identity, identities
        except BaseException:
            for key in set(self.connected_lockin_keys) - existing_keys:
                try:
                    self.disconnect_lockin(key)
                except BaseException:
                    pass
            if not source_was_connected and self.source_connected:
                try:
                    self.disconnect_source()
                except BaseException:
                    pass
            raise
    def configure(
        self,
        initial_rms_ma: float,
        frequency_hz: float,
        compliance_v: float,
        lockin_configs: dict[str, dict],
        marker_line: int = NONLOCAL_MARKER_LINE,
        mfli_config: dict[str, object] | None = None,
        use_nanovoltmeter: bool = False,
        sample_hz: float = NONLOCAL_SAMPLE_HZ,
        output_mode: str = "AC",
        sr830_front_panel_time_constant: bool = False,
        sweep_peak_a: float | None = None,
    ) -> tuple[float, dict[str, dict]]:
        with self.lock:
            output_mode = str(output_mode).strip().upper()
            if output_mode not in {"AC", "DC"}:
                raise ValueError("6221 output mode can only be AC or DC")
            if not self.connected:
                raise RuntimeError("Non-local IV instruments are not connected")
            if not set(lockin_configs).issubset(self.lockins):
                raise RuntimeError("The lock-in configuration includes an SR830 that is not connected")
            if not lockin_configs and not mfli_config and not use_nanovoltmeter:
                raise RuntimeError("Select at least one voltage measurement instrument")
            if mfli_config and not self.mfli_connected:
                raise RuntimeError("Zurich MFLI is selected, but the instrument is not connected")
            if use_nanovoltmeter and self.nanovoltmeter is None:
                raise RuntimeError("2182A is selected, but the instrument is not connected")
            if output_mode == "DC" and (lockin_configs or mfli_config):
                raise ValueError('6221 DC output has no lock-in reference; DC mode can only use the 2182A DC measurement')
            if output_mode == "DC" and not use_nanovoltmeter:
                raise ValueError("6221 DC output mode requires the 2182A to participate in the scan")
            numeric = (initial_rms_ma, compliance_v, marker_line)
            if not all(math.isfinite(float(value)) for value in numeric):
                raise ValueError("6221 parameters must be finite values")
            if output_mode == "AC" and initial_rms_ma <= 0:
                raise ValueError("6221 AC RMS current must be greater than 0 mA")
            if output_mode == "DC" and abs(initial_rms_ma) > 105.0:
                raise ValueError("6221 DC current must be within ±105 mA")
            if output_mode == "AC" and not 1e-3 <= frequency_hz <= 1e5:
                raise ValueError("6221 waveform frequency must be within 0.001–100000 Hz")
            if not K6221_MIN_COMPLIANCE_V <= compliance_v <= K6221_MAX_COMPLIANCE_V:
                raise ValueError("6221 compliance voltage must be within 0.1–105 V")
            if not 1 <= int(marker_line) <= 6:
                raise ValueError("6221 Trigger Link output line must be within 1–6")
            peak_a = math.sqrt(2.0) * initial_rms_ma * 1e-3
            if output_mode == "AC" and peak_a > NONLOCAL_MAX_PEAK_A:
                raise ValueError('6221 sine-wave peak exceeds 105 mA; the GUI current unit is RMS')
            if sweep_peak_a is not None:
                sweep_peak_a = float(sweep_peak_a)
                if output_mode != 'AC' or not (math.isfinite(sweep_peak_a) and peak_a <= sweep_peak_a * (1 + 1e-09) and (sweep_peak_a <= NONLOCAL_MAX_PEAK_A)):
                    raise ValueError('6221 sweep range must cover the first current and stay within the 105 mA sine peak')
            for key, requested in lockin_configs.items():
                harmonic = int(requested["harmonic"])
                if not 1 <= harmonic <= 19999:
                    raise ValueError(f"SR830 #{key} harmonic must be within 1–19999")
                if frequency_hz * harmonic > 102000.0:
                    raise ValueError(f'SR830 #{key} demodulation frequency exceeds 102 kHz')
            if mfli_config:
                mfli_harmonic = int(mfli_config["harmonic"])
                if mfli_harmonic < 1:
                    raise ValueError("MFLI harmonic must be a positive integer")
                if frequency_hz * mfli_harmonic > 500000.0:
                    raise ValueError("MFLI demodulation frequency exceeds the base model's 500 kHz limit")
            self.source.write("*RST")
            self.source.write("*CLS")
            self._set_6221_output_low_floating()
            self.sweep_peak_a = None
            if output_mode == "AC" and sweep_peak_a is not None:
                self._write_6221(f"SOUR:CURR:RANG {sweep_peak_a:.12e}")
                actual_range = self._query_float(self.source, "SOUR:CURR:RANG?")
                if actual_range * 1.05 + 1e-12 < sweep_peak_a:
                    raise RuntimeError(f'6221 current range is too small for the sweep: {actual_range:g} A')
            if output_mode == "AC":
                commands = (
                    f"CURR:COMP {compliance_v:.12g}", "SOUR:WAVE:FUNC SIN",
                    f"SOUR:WAVE:FREQ {frequency_hz:.12g}",
                    f"SOUR:WAVE:AMPL {peak_a:.12e}", "SOUR:WAVE:OFFS 0",
                    *(
                        ("SOUR:WAVE:RANG FIX", "SOUR:WAVE:DUR:CYCL INF")
                        if sweep_peak_a is not None
                        else ("SOUR:WAVE:RANG BEST",)
                    ),
                    f"SOUR:WAVE:PMAR {NONLOCAL_MARKER_PHASE_DEG:g}",
                    f"SOUR:WAVE:PMAR:OLIN {marker_line}",
                    "SOUR:WAVE:PMAR:STAT ON", "OUTP OFF",
                )
            else:
                commands = (f'CURR:COMP {compliance_v:.12g}', 'SOUR:CURR:RANG:AUTO ON', 'SOUR:CURR 0', 'OUTP OFF')
            for command in commands:
                self._write_6221(command)
            actual_compliance = self._query_float(self.source, "CURR:COMP?")
            if not math.isclose(actual_compliance, compliance_v, rel_tol=0.0005, abs_tol=1e-06):
                raise RuntimeError(f'6221 compliance voltage readback mismatch: requested {compliance_v:g} V, readback {actual_compliance:g} V')
            if output_mode == "AC":
                actual_frequency = self._query_float(self.source, 'SOUR:WAVE:FREQ?')
                actual_peak = self._query_float(self.source, 'SOUR:WAVE:AMPL?')
                actual_offset = self._query_float(self.source, 'SOUR:WAVE:OFFS?')
                marker_enabled = int(self._query_float(self.source, 'SOUR:WAVE:PMAR:STAT?'))
                actual_marker_line = int(self._query_float(self.source, 'SOUR:WAVE:PMAR:OLIN?'))
                marker_phase = self._query_float(self.source, 'SOUR:WAVE:PMAR?')
                if not math.isclose(actual_frequency, frequency_hz, rel_tol=0.005, abs_tol=0.1):
                    raise RuntimeError(f'6221 frequency readback mismatch: requested {frequency_hz:g} Hz, readback {actual_frequency:g} Hz')
                if not math.isclose(actual_peak, peak_a, rel_tol=0.0005, abs_tol=1e-12):
                    raise RuntimeError(f'6221 amplitude readback mismatch: requested {peak_a:g} Apeak, readback {actual_peak:g} Apeak')
                if not math.isclose(actual_offset, 0.0, abs_tol=1e-12):
                    raise RuntimeError(f'6221 waveform offset is not zero: {actual_offset:g} A')
                if marker_enabled != 1 or actual_marker_line != int(marker_line):
                    raise RuntimeError(f'6221 Trigger Link phase marker readback mismatch: enabled={marker_enabled}, line={actual_marker_line}')
                if not math.isclose(marker_phase, NONLOCAL_MARKER_PHASE_DEG, abs_tol=1e-06):
                    raise RuntimeError(f'6221 phase marker readback mismatch: {marker_phase:g}°')
            else:
                actual_frequency = math.nan
                auto_range = int(self._query_float(self.source, 'SOUR:CURR:RANG:AUTO?'))
                actual_current = self._query_float(self.source, "SOUR:CURR?")
                output_state = int(self._query_float(self.source, "OUTP?"))
                if auto_range != 1 or not math.isclose(actual_current, 0.0, abs_tol=1e-12) or output_state != 0:
                    raise RuntimeError(f'6221 DC initialization readback mismatch: auto_range={auto_range}, current={actual_current:g} A, output={output_state}')
            self.source_output_mode = output_mode
            if output_mode == "AC":
                self.sweep_peak_a = sweep_peak_a
                self.configured_frequency_hz = actual_frequency
            readbacks = {}
            for key in sorted(lockin_configs, key=int):
                lockin = self.lockins[key]
                requested = lockin_configs[key]
                harmonic = int(requested["harmonic"])
                coupling = str(requested["coupling"]).upper()
                coupling_code = 0 if coupling == "AC" else 1
                lockin.write("*CLS")
                time_constant = () if sr830_front_panel_time_constant else (f'OFLT {NONLOCAL_VI_SR830_TIME_CONSTANT_CODE}', 'OFSL 1')
                for command in (
                    "FMOD 0", "RSLP 2", f"HARM {harmonic}", "ISRC 1",
                    "IGND 0", f"ICPL {coupling_code}", "ILIN 0", "SYNC 0", "SENS 9",
                    *time_constant, "RMOD 1", "PHAS 0",
                    *SR830_DISPLAY_XY_COMMANDS,
                ):
                    self._write_sr830(key, command)
                actual_harmonic = int(self._query_sr830_numbers(key, 'HARM?', 1)[0])
                actual_coupling = int(self._query_sr830_numbers(key, 'ICPL?', 1)[0])
                reference_mode = int(self._query_sr830_numbers(key, 'FMOD?', 1)[0])
                reference_slope = int(self._query_sr830_numbers(key, 'RSLP?', 1)[0])
                channel_1 = tuple((int(value) for value in self._query_sr830_numbers(key, 'DDEF? 1', 2)))
                channel_2 = tuple((int(value) for value in self._query_sr830_numbers(key, 'DDEF? 2', 2)))
                if actual_harmonic != harmonic or actual_coupling != coupling_code:
                    raise RuntimeError(f'SR830 #{key} configuration readback mismatch: HARM={actual_harmonic}, ICPL={actual_coupling}')
                if reference_mode != 0 or reference_slope != 2:
                    raise RuntimeError(f'SR830 #{key} external reference readback mismatch: FMOD={reference_mode}, RSLP={reference_slope}')
                if channel_1 != (0, 0) or channel_2 != (0, 0):
                    raise RuntimeError(f'SR830 #{key} front-panel display readback mismatch: CH1={channel_1}, CH2={channel_2}')
                sensitivity = int(self._query_sr830_numbers(key, 'SENS?', 1)[0])
                self.sensitivity_indices[key] = sensitivity
                self.low_range_counts[key] = 0
                self.range_cooldowns[key] = 0
                self.__dict__.setdefault("overload_floors", {})[key] = 0
                memory = self.__dict__.setdefault("overload_floor_memory", {})
                for name in [name for name in memory if name[0] == key]:
                    del memory[name]
                self.__dict__.setdefault("lockin_harmonics", {})[key] = harmonic
                self.lias_clear_pending[key] = True
                time_constant_code = int(self._query_sr830_numbers(key, "OFLT?", 1)[0])
                readbacks[key] = {
                    "meter_type": "SR830",
                    "time_constant_s": (
                        SR830_TIME_CONSTANTS_S[time_constant_code]
                        if 0 <= time_constant_code < len(SR830_TIME_CONSTANTS_S)
                        else math.nan
                    ),
                    "harmonic": actual_harmonic,
                    "coupling": "AC" if actual_coupling == 0 else "DC",
                    "channel": requested["channel"],
                    "resource": self.lockin_resources.get(key, f"GPIB {key}"),
                }
            self.mfli_in_scan = False
            if mfli_config:
                extref_demodulator = mfli_config.get("external_reference_demodulator")
                single_on_demod_4 = extref_demodulator is None and self.mfli_has_multi_demod()
                if single_on_demod_4:
                    extref_demodulator = 3
                readbacks["mfli"] = self.configure_mfli(
                    str(mfli_config["coupling"]),
                    int(mfli_config["harmonic"]),
                    str(mfli_config["channel"]),
                    str(mfli_config["reference_source"]),
                    sample_rate_hz=sample_hz,
                    input_impedance=str(mfli_config["input_impedance"]),
                    input_scaling=float(mfli_config["input_scaling"]),
                    timeconstant_s=float(
                        mfli_config.get("timeconstant_s", NONLOCAL_LOCKIN_TIME_CONSTANT_S)
                    ),
                    external_reference_demodulator=extref_demodulator,
                )
                if single_on_demod_4:
                    self.disable_unused_ppms_demods("1")
                self.mfli_auto_range_enabled = bool(mfli_config.get("auto_range", True))
                if not self.mfli_auto_range_enabled:
                    self.mfli_initial_autorange_pending = False
                self.mfli_in_scan = True
            if use_nanovoltmeter:
                readbacks['2182'] = {'meter_type': '2182A', **self.configure_nanovoltmeter(channel=1, nplc=1.0)}
            return actual_frequency, readbacks
    def set_current(self, rms_ma: float, frequency_hz: float) -> float:
        with self.lock:
            if not math.isfinite(float(rms_ma)):
                raise ValueError("6221 current must be a finite value")
            if self.source_output_mode == "DC":
                if abs(float(rms_ma)) > 105.0:
                    raise ValueError("6221 DC current must be within ±105 mA")
                requested_a = float(rms_ma) * 1e-3
                self.output_enabled = True
                for command in (f'SOUR:CURR {requested_a:.12e}', 'OUTP ON'):
                    self._write_6221(command)
                output_state = int(self._query_float(self.source, "OUTP?"))
                readback_a = self._query_float(self.source, "SOUR:CURR?")
                if output_state != 1:
                    raise RuntimeError("6221 DC output did not turn on successfully")
                if not math.isclose(readback_a, requested_a, rel_tol=0.0005, abs_tol=1e-12):
                    raise RuntimeError(f'6221 DC current readback mismatch: {readback_a:g} A')
                self.output_enabled = True
                return readback_a * 1e3
            if float(rms_ma) <= 0:
                raise ValueError("6221 AC RMS current must be a finite positive number")
            if not 1e-3 <= float(frequency_hz) <= 1e5:
                raise ValueError("6221 waveform frequency must be within 0.001–100000 Hz")
            peak_a = math.sqrt(2.0) * float(rms_ma) * 1e-3
            if peak_a > NONLOCAL_MAX_PEAK_A:
                raise ValueError("6221 sine-wave peak exceeds 105 mA")
            self.output_enabled = True
            for command in ('SOUR:WAVE:ABOR', f'SOUR:WAVE:AMPL {peak_a:.12e}', 'SOUR:WAVE:ARM', 'SOUR:WAVE:INIT'):
                self._write_6221(command)
            if int(self._query_float(self.source, "OUTP?")) != 1:
                raise RuntimeError("6221 sine wave did not turn on successfully")
            actual_frequency = self._query_float(self.source, "SOUR:WAVE:FREQ?")
            if not math.isclose(actual_frequency, frequency_hz, rel_tol=5e-3, abs_tol=0.1):
                raise RuntimeError(f'6221 frequency readback mismatch: {actual_frequency:g} Hz')
            self.output_enabled = True
            peak_readback = self._query_float(self.source, "SOUR:WAVE:AMPL?")
            if not math.isclose(peak_readback, peak_a, rel_tol=5e-4, abs_tol=1e-12):
                raise RuntimeError(f'6221 current amplitude readback mismatch: {peak_readback:g} Apeak')
            return peak_readback / math.sqrt(2.0) * 1e3
    def wait_references(self, frequency_hz: float, stop_event: threading.Event, lockin_keys: tuple[str, ...] | None=None) -> dict[str, dict]:
        keys = tuple(lockin_keys) if lockin_keys is not None else self.connected_lockin_keys
        results = {key: self._wait_reference_one(key, frequency_hz, stop_event) for key in keys}
        if self.mfli_connected and self.mfli_config and self.__dict__.get("mfli_in_scan"):
            results['mfli'] = self._wait_mfli_reference(frequency_hz, stop_event)
        return results
    def _wait_mfli_reference(self, frequency_hz: float, stop_event: threading.Event) -> dict:
        if self.mfli_initial_autorange_pending and not stop_event.is_set():
            with self.lock:
                action = self._run_mfli_autorange("initial")
            self.logger(f"Non-local MFLI auto-range: {action}")
        deadline = time.monotonic() + 5.0
        last_sample = {
            "reference_valid": False,
            "reference_frequency_hz": math.nan,
            "lia_status": 8,
            "status_text": (
                f"{self.mfli_config.get('reference_source', NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT)} "
                "external reference not locked"
            ),
        }
        while time.monotonic() < deadline and not stop_event.is_set():
            with self.lock:
                last_sample = self.read_mfli(frequency_hz)
            if last_sample["reference_valid"]:
                break
            stop_event.wait(0.1)
        return {
            "valid": bool(last_sample["reference_valid"]),
            "frequency_hz": float(last_sample["reference_frequency_hz"]),
            "status": int(last_sample["lia_status"]),
            "status_text": str(last_sample["status_text"]),
            "reference_source": str(
                self.mfli_config.get(
                    "reference_source",
                    NONLOCAL_MFLI_DEFAULT_REFERENCE_INPUT,
                )
            ),
        }
    def _wait_reference_one(self, key: str, frequency_hz: float, stop_event: threading.Event) -> dict:
        deadline = time.monotonic() + 5.0
        last_frequency = math.nan
        last_status = 8
        while time.monotonic() < deadline and not stop_event.is_set():
            with self.lock:
                lockin = self.lockins[key]
                last_frequency = self._query_sr830_numbers(key, "FREQ?", 1)[0]
                status = self._query_sr830_status(key)
                last_status = self.SR830_LIAS_UNREADABLE if status is None else status
            if not last_status & 8 and math.isclose(last_frequency, frequency_hz, rel_tol=0.005, abs_tol=0.1):
                return {"valid": True, "frequency_hz": last_frequency, "status": last_status}
            stop_event.wait(0.1)
        return {"valid": False, "frequency_hz": last_frequency, "status": last_status}
    @staticmethod
    def _status_text(status: int) -> str:
        labels = []
        if status & 1:
            labels.append("input/Reserve overload")
        if status & 2:
            labels.append("filter overload")
        if status & 4:
            labels.append("output overload")
        if status & 8:
            labels.append("reference not locked")
        return "; ".join(labels) if labels else "OK"
    def _run_mfli_autorange(self, reason: str) -> str:
        if not self.mfli_connected:
            raise RuntimeError("Zurich MFLI is not connected")
        configured_old = float(self.mfli_config.get("input_range_v", math.nan))
        if self.mfli_bridge is not None:
            result = self.mfli_bridge.request("autorange")["autorange"]
            old_range = float(result["old_input_range_v"])
            new_range = float(result["input_range_v"])
        else:
            device = self.mfli_device
            range_node = f"/{device}/sigins/0/range"
            autorange_node = f"/{device}/sigins/0/autorange"
            old_range = float(self.mfli_daq.getDouble(range_node))
            self.mfli_daq.setInt(autorange_node, 1)
            self.mfli_daq.sync()
            deadline = time.monotonic() + 8.0
            while int(self.mfli_daq.getInt(autorange_node)) != 0:
                if time.monotonic() >= deadline:
                    raise RuntimeError("MFLI Signal Input 1 auto-range timed out")
                time.sleep(0.02)
            self.mfli_daq.sync()
            new_range = float(self.mfli_daq.getDouble(range_node))
            for suffix in ("max", "min"):
                try:
                    self.mfli_daq.setDouble(f'/{device}/sigins/0/{suffix}', 0.0)
                except BaseException:
                    pass
        if not math.isfinite(old_range) or old_range <= 0:
            old_range = configured_old
        if not math.isfinite(new_range) or new_range <= 0:
            raise RuntimeError(f"MFLI auto-range readback is invalid: {new_range!r}")
        self.mfli_config["input_range_v"] = new_range
        self.mfli_low_range_count = 0
        self.mfli_range_cooldown = 3
        self.mfli_initial_autorange_pending = False
        if reason in self.MFLI_RANGE_FRESH_REASONS:
            self.forget_mfli_range_guard()
        elif reason == "low":
            if new_range < old_range * (1.0 - 1e-6):
                self.mfli_stepped_down = True
            else:
                self.mfli_low_floor_v = new_range
        elif new_range > old_range * (1.0 + 1e-6) and self.__dict__.get("mfli_stepped_down", False):
            self.mfli_stepped_down = False
            needed = int(self.__dict__.get("mfli_low_readings_needed") or LOCKIN_DOWNRANGE_READINGS)
            self.mfli_low_readings_needed = min(2 * needed, MFLI_DOWNRANGE_READINGS_LIMIT)
        return f"RANGE {old_range:.6g}->{new_range:.6g} V ({reason})"
    def _auto_range_mfli(self, sample: dict[str, object]) -> str:
        if not self.__dict__.get("mfli_auto_range_enabled", True):
            return ""
        utilization = float(sample.get("input_utilization", 0.0))
        if not math.isfinite(utilization):
            return ""
        if utilization >= LOCKIN_UPRANGE_FRACTION:
            return self._run_mfli_autorange("overload/high")
        if self.mfli_range_cooldown > 0:
            self.mfli_range_cooldown -= 1
            self.mfli_low_range_count = 0
            return ""
        floor = float(self.__dict__.get("mfli_low_floor_v") or 0.0)
        try:
            in_use = float((self.__dict__.get("mfli_config") or {}).get("input_range_v", math.nan))
        except (TypeError, ValueError):
            in_use = math.nan
        kept_here = floor > 0.0 and math.isfinite(in_use) and in_use <= floor * (1.0 + 1e-6)
        if utilization < LOCKIN_DOWNRANGE_FRACTION and not kept_here:
            self.mfli_low_range_count += 1
            needed = int(self.__dict__.get("mfli_low_readings_needed") or LOCKIN_DOWNRANGE_READINGS)
            if self.mfli_low_range_count >= needed:
                return self._run_mfli_autorange("low")
        else:
            self.mfli_low_range_count = 0
        return ""
    def read_stfmr_mfli(self, expected_frequency_hz: float, *, auto_range: bool, initial: bool=False, attempts: int=0) -> dict[str, object]:
        sample = self.read_mfli(expected_frequency_hz)
        if not auto_range:
            return sample
        utilization = float(sample.get("input_utilization", math.nan))
        raw_valid = bool(sample.get("input_extrema_valid", False))
        overloaded = sample.get("input_overload") is True
        high = raw_valid and math.isfinite(utilization) and utilization >= LOCKIN_UPRANGE_FRACTION
        if attempts >= 3:
            if overloaded or high or initial:
                raise RuntimeError('MFLI auto-range still overloaded or near full scale after 3 retries; the current point was not saved; please check the input signal and wiring')
            return sample
        if overloaded:
            action = self._run_mfli_autorange("STFMR input overload")
        elif initial:
            action = self._run_mfli_autorange("STFMR frequency start")
        elif raw_valid:
            action = self._auto_range_mfli(sample)
        else:
            action = ""
        if action:
            sample["auto_range"] = action
            sample["input_range_after_v"] = self.mfli_config["input_range_v"]
        return sample
    def _auto_range(self, key: str, r_v: float, status: int) -> str:
        old = self.sensitivity_indices[key]
        utilization = abs(r_v) / NONLOCAL_SR830_FULL_SCALE_V[old]
        requested = old
        reason = ""
        overloaded = bool(status & 0x07)
        floors = self.__dict__.setdefault("overload_floors", {})
        floor = int(floors.get(key) or 0)
        if overloaded or utilization >= LOCKIN_UPRANGE_FRACTION:
            requested = min(old + 1, len(NONLOCAL_SR830_FULL_SCALE_V) - 1)
            reason = "overload/high"
            self.low_range_counts[key] = 0
        elif self.range_cooldowns[key] > 0:
            self.range_cooldowns[key] -= 1
            self.low_range_counts[key] = 0
        elif utilization < LOCKIN_DOWNRANGE_FRACTION and old > floor and not status & 0x08:
            self.low_range_counts[key] += 1
            if self.low_range_counts[key] >= 3:
                requested = old - 1
                reason = "low"
                self.low_range_counts[key] = 0
        else:
            self.low_range_counts[key] = 0
        if requested != old:
            self._write_sr830(key, f"SENS {requested}")
            actual = int(self._query_sr830_numbers(key, "SENS?", 1)[0])
            if actual != requested:
                raise RuntimeError(f"SR830 #{key} auto-range readback is inconsistent")
            self.sensitivity_indices[key] = actual
            self.range_cooldowns[key] = 3
            self.lias_clear_pending[key] = True
            if overloaded and actual > old and utilization < LOCKIN_UPRANGE_FRACTION:
                floors[key] = max(floor, actual)
            return f"SENS {old}->{actual} ({reason})"
        return ""
    def read_samples(self, expected_frequency_hz: float, measurement_keys: tuple[str, ...] | None=None) -> dict[str, dict]:
        with self.lock:
            keys = tuple(measurement_keys) if measurement_keys is not None else self.connected_lockin_keys
            output_on = int(self._query_float(self.source, "OUTP?")) == 1
            measurement_condition = int(self._query_float(self.source, 'STAT:MEAS:COND?'))
            samples = {}
            for key in keys:
                if key == "2182":
                    voltage = self.read_nanovoltmeter()
                    samples[key] = {
                        "meter_type": "2182A",
                        "voltage": voltage,
                        "X": math.nan,
                        "Y": math.nan,
                        "R": voltage,
                        "phase_deg": math.nan,
                        "reference_frequency_hz": math.nan,
                        "lia_status": 0,
                        "status_text": "2182A DC sample (not AC lock-in)",
                        "reference_valid": True,
                        "measurement_valid": not bool(measurement_condition & 8),
                        "output_on": output_on,
                        "measurement_condition": measurement_condition,
                        "in_compliance": bool(measurement_condition & 8),
                        "sensitivity_index": "",
                        "auto_range": "",
                    }
                elif key == "mfli":
                    sample = self.read_mfli(expected_frequency_hz)
                    if sample.get('input_overload') is True and self.__dict__.get('mfli_auto_range_enabled', True):
                        sample["auto_range"] = self._run_mfli_autorange("input overload")
                    elif sample.get("input_extrema_valid", True):
                        sample["auto_range"] = self._auto_range_mfli(sample)
                    else:
                        sample["auto_range"] = ""
                    sample.update(output_on=output_on, measurement_condition=measurement_condition, in_compliance=bool(measurement_condition & 8))
                    sample["measurement_valid"] = bool(
                        sample["reference_valid"]
                        and not sample["lia_status"]
                        and not sample["in_compliance"]
                        and not sample["auto_range"]
                        and sample.get("input_overload") is not True
                    )
                    samples[key] = sample
                else:
                    sample = self._read_sample_one(key, expected_frequency_hz, output_on, measurement_condition)
                    sample["meter_type"] = "SR830"
                    sample["voltage"] = sample["R"]
                    samples[key] = sample
            return samples
    def _read_sample_one(self, key: str, expected_frequency_hz: float, output_on: bool, measurement_condition: int) -> dict:
        lockin = self.lockins[key]
        values = self._query_sr830_numbers(key, "SNAP? 1,2,3,4,9", 5)
        if self.lias_clear_pending.pop(key, False):
            self._query_sr830_status(key)
        status = self._query_sr830_status(key)
        unreadable = status is None
        if unreadable:
            status = self.SR830_LIAS_UNREADABLE
        sensitivity_used = self.sensitivity_indices[key]
        auto_action = self._auto_range(key, values[2], 0x08 if unreadable else status)
        reference_valid = not status & 8 and math.isclose(values[4], expected_frequency_hz, rel_tol=0.005, abs_tol=0.1)
        in_compliance = bool(measurement_condition & 8)
        return {
            "lockin_key": key,
            "X": values[0], "Y": values[1], "R": values[2],
            "phase_deg": values[3], "reference_frequency_hz": values[4],
            "lia_status": status,
            "status_text": (
                "LIAS? unreadable: counted as overloaded" if unreadable else self._status_text(status)
            ),
            "reference_valid": reference_valid, "output_on": output_on,
            "measurement_condition": measurement_condition,
            "in_compliance": in_compliance,
            "measurement_valid": bool(
                reference_valid
                and not (status & 0x07)
                and not in_compliance
                and not auto_action
            ),
            "sensitivity_index": sensitivity_used, "auto_range": auto_action,
        }
    def mfli_has_multi_demod(self) -> bool:
        with self.lock:
            options = str(self.mfli_props.get("options", "")).upper()
            if self.mfli_bridge is None and self.mfli_daq is not None and not options:
                try:
                    options = str(self.mfli_daq.getString(f'/{self.mfli_device}/features/options')).upper()
                    self.mfli_props["options"] = options
                except BaseException:
                    pass
            if options:
                return "MD" in options
            has_demod_4 = self.mfli_props.get("has_demod_4")
            if not has_demod_4 and self.mfli_bridge is None and self.mfli_daq is not None:
                try:
                    self.mfli_daq.getInt(f'/{self.mfli_device}/demods/3/enable')
                    self.mfli_daq.getInt(f'/{self.mfli_device}/extrefs/1/demodselect')
                    has_demod_4 = self.mfli_props["has_demod_4"] = True
                except BaseException:
                    has_demod_4 = False
            return bool(has_demod_4)
    def update_amplitude(self, rms_ma: float) -> float:
        with self.lock:
            sweep_peak_a = getattr(self, "sweep_peak_a", None)
            if self.source_output_mode != "AC" or sweep_peak_a is None:
                raise RuntimeError("The 6221 is not set up for a continuous current sweep")
            rms_ma = float(rms_ma)
            if not math.isfinite(rms_ma) or rms_ma <= 0:
                raise ValueError("6221 AC RMS current must be a finite positive number")
            peak_a = math.sqrt(2.0) * rms_ma * 1e-3
            if peak_a > sweep_peak_a * (1 + 1e-9):
                raise ValueError("6221 current exceeds the range reserved for the sweep")
            if int(self._query_float(self.source, "OUTP?")) != 1:
                raise RuntimeError("6221 output is off; the current sweep cannot continue")
            self._write_6221(f"SOUR:WAVE:AMPL {peak_a:.12e}")
            actual = self._query_float(self.source, "SOUR:WAVE:AMPL?")
            if not math.isclose(actual, peak_a, rel_tol=5e-4, abs_tol=1e-12):
                raise RuntimeError(f"6221 live amplitude readback mismatch: {actual:g} Apeak")
            if int(self._query_float(self.source, "OUTP?")) != 1:
                raise RuntimeError("6221 output stopped during the amplitude update")
            return actual / math.sqrt(2.0) * 1e3
    def set_lockin_harmonic(self, key: str, harmonic: int, sensitivity_index: int | None=None) -> None:
        harmonic = int(harmonic)
        if not 1 <= harmonic <= 19999:
            raise ValueError(f"SR830 #{key} harmonic must be within 1–19999")
        sensitivity = 9 if sensitivity_index is None else int(sensitivity_index)
        if not 0 <= sensitivity <= 26:
            raise ValueError(f"SR830 #{key} sensitivity index must be within 0–26")
        with self.lock:
            if key not in self.lockins:
                raise RuntimeError(f"SR830 #{key} is not connected")
            self._write_sr830(key, f"HARM {harmonic}")
            actual = int(self._query_sr830_numbers(key, "HARM?", 1)[0])
            if actual != harmonic:
                raise RuntimeError(f'SR830 #{key} harmonic readback mismatch: requested {harmonic}, readback {actual}')
            self._write_sr830(key, f"SENS {sensitivity}")
            self.sensitivity_indices[key] = int(self._query_sr830_numbers(key, "SENS?", 1)[0])
            self.lias_clear_pending[key] = True
            self.low_range_counts[key] = 0
            self.range_cooldowns[key] = 0
            floors = self.__dict__.setdefault("overload_floors", {})
            memory = self.__dict__.setdefault("overload_floor_memory", {})
            harmonics = self.__dict__.setdefault("lockin_harmonics", {})
            if key in harmonics:
                memory[(key, harmonics[key])] = int(floors.get(key) or 0)
            floors[key] = 0 if sensitivity_index is None else int(memory.get((key, harmonic)) or 0)
            harmonics[key] = harmonic
    def output_off(self) -> None:
        with self.lock:
            if self.source is None:
                return
            errors = []
            for command in ("SOUR:WAVE:ABOR", "CURR 0", "OUTP OFF"):
                try:
                    self.source.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            self.output_enabled = False
            if errors:
                raise RuntimeError("6221 failed to turn output off: " + "; ".join(errors))
    def confirm_output_off(self, context: str) -> None:
        with self.lock:
            if self.source is None:
                raise RuntimeError("6221 is not connected")
            output_state = int(round(self._query_float(self.source, "OUTP?")))
            if output_state != 0 or self.output_enabled:
                self.output_off()
                output_state = int(round(self._query_float(self.source, "OUTP?")))
            if output_state != 0:
                raise RuntimeError(f'6221 output is still ON {context}; the Non-local Keithley action is forbidden')
    def disconnect(self) -> None:
        with self.lock:
            source, manager = self.source, self.resource_manager
            lockins = list(self.lockins.values())
            source_resource = self.source_resource
            lockin_resources = tuple(self.lockin_resources.values())
            nanovoltmeter_resource = self.nanovoltmeter_resource
            mfli_lease_resource = self.mfli_lease_resource
            mfli_daq = self.mfli_daq
            mfli_bridge = self.mfli_bridge
            nanovoltmeter = self.nanovoltmeter
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            for instrument in lockins + [nanovoltmeter, source]:
                if instrument is not None:
                    try:
                        instrument.write("*CLS")
                        instrument.close()
                    except BaseException:
                        pass
            if mfli_daq is not None:
                try:
                    mfli_daq.setInt(f"/{self.mfli_device}/extrefs/{self.mfli_config.get('extref_channel', NONLOCAL_MFLI_EXTREF_CHANNEL)}/enable", 0)
                    mfli_daq.setInt(f'/{self.mfli_device}/demods/{NONLOCAL_MFLI_DEMODULATOR}/enable', 0)
                    extref_demod = int(self.mfli_config.get('extref_demodulator', NONLOCAL_MFLI_EXTREF_DEMODULATOR))
                    if extref_demod != NONLOCAL_MFLI_DEMODULATOR:
                        mfli_daq.setInt(f'/{self.mfli_device}/demods/{extref_demod}/enable', 0)
                    mfli_daq.sync()
                except BaseException:
                    pass
                try:
                    mfli_daq.disconnect()
                except BaseException:
                    pass
            if mfli_bridge is not None:
                try:
                    mfli_bridge.close()
                except BaseException:
                    mfli_bridge.close(force=True)
            release_shared_visa_manager(manager)
            self.source = self.nanovoltmeter = self.resource_manager = None
            self.mfli_daq = None
            self.mfli_bridge = None
            self.mfli_device = ""
            self.mfli_props = {}
            self.mfli_config = {}
            self.mfli_identity = ""
            self.lockins = {}
            self.source_identity = ""
            self.lockin_identities = {}
            self.source_resource = ""
            self.lockin_resources = {}
            self.nanovoltmeter_resource = ""
            self.mfli_lease_resource = ""
            self.nanovoltmeter_identity = ""
            self.sensitivity_indices = {}
            self.low_range_counts = {}
            self.range_cooldowns = {}
            self.mfli_low_range_count = 0
            self.mfli_range_cooldown = 0
            self.mfli_initial_autorange_pending = False
            self.output_enabled = False
            self.source_output_mode = "AC"
            release_instrument_lease(source_resource, self)
            for resource in lockin_resources:
                release_instrument_lease(resource, self)
            release_instrument_lease(nanovoltmeter_resource, self)
            release_instrument_lease(mfli_lease_resource, self)
            self.logger("Non-local IV stopped the 6221 output and disconnected all instruments")
            if shutdown_error is not None:
                raise shutdown_error
    def disconnect_source(self) -> None:
        with self.lock:
            source = self.source
            resource = self.source_resource
            if source is None:
                self.source_resource = ""
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            try:
                source.write("*CLS")
            except BaseException:
                pass
            try:
                source.close()
            except BaseException:
                pass
            self.source = None
            self.source_identity = ""
            self.source_resource = ""
            self.source_output_mode = "AC"
            self.output_enabled = False
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger("Non-local IV 6221 output stopped and disconnected")
            if shutdown_error is not None:
                raise shutdown_error
    def disconnect_lockin(self, key: str) -> None:
        key = str(key)
        with self.lock:
            lockin = self.lockins.pop(key, None)
            resource = self.lockin_resources.pop(key, "")
            if lockin is None:
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            try:
                lockin.write("*CLS")
            except BaseException:
                pass
            try:
                lockin.close()
            except BaseException:
                pass
            self.lockin_identities.pop(key, None)
            self.sensitivity_indices.pop(key, None)
            self.low_range_counts.pop(key, None)
            self.range_cooldowns.pop(key, None)
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger(f"Non-local IV SR830 #{key} disconnected")
    def disconnect_nanovoltmeter(self) -> None:
        with self.lock:
            meter = self.nanovoltmeter
            resource = self.nanovoltmeter_resource
            if meter is None:
                self.nanovoltmeter_resource = ""
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            try:
                meter.write("*CLS")
            except BaseException:
                pass
            try:
                meter.close()
            except BaseException:
                pass
            self.nanovoltmeter = None
            self.nanovoltmeter_identity = ""
            self.nanovoltmeter_resource = ""
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger("Non-local IV Keithley 2182A disconnected")
    def disconnect_mfli(self) -> None:
        with self.lock:
            daq = self.mfli_daq
            bridge = self.mfli_bridge
            mfli_lease_resource = self.mfli_lease_resource
            if daq is None and bridge is None:
                self.mfli_lease_resource = ""
                release_instrument_lease(mfli_lease_resource, self)
                self._close_manager_if_unused()
                return
            if daq is not None:
                extref_demod = int(self.mfli_config.get('extref_demodulator', NONLOCAL_MFLI_DEMODULATOR))
                disable_nodes = [
                    f"/{self.mfli_device}/extrefs/"
                    f"{self.mfli_config.get('extref_channel', NONLOCAL_MFLI_EXTREF_CHANNEL)}/enable",
                    f"/{self.mfli_device}/demods/"
                    f"{NONLOCAL_MFLI_DEMODULATOR}/enable",
                ]
                if extref_demod != NONLOCAL_MFLI_DEMODULATOR:
                    disable_nodes.append(f'/{self.mfli_device}/demods/{extref_demod}/enable')
                for node in disable_nodes:
                    try:
                        daq.setInt(node, 0)
                    except BaseException:
                        pass
                try:
                    daq.sync()
                except BaseException:
                    pass
            try:
                if daq is not None:
                    daq.disconnect()
            except BaseException:
                pass
            if bridge is not None:
                try:
                    bridge.close()
                except BaseException:
                    bridge.close(force=True)
            self.mfli_daq = None
            self.mfli_bridge = None
            self.mfli_device = ""
            self.mfli_props = {}
            self.mfli_config = {}
            self.mfli_identity = ""
            self.mfli_lease_resource = ""
            self.mfli_low_range_count = 0
            self.mfli_range_cooldown = 0
            self.mfli_initial_autorange_pending = False
            release_instrument_lease(mfli_lease_resource, self)
            self._close_manager_if_unused()
            self.logger("Non-local Zurich MFLI disconnected")
SCAN_FILE_NAME_PROMPT = "Optional file name (leave blank for a timestamped default):"
def scan_file_stem(name: str) -> str:
    """The shared file-name rule, under the application's own name."""
    return _scan_file_stem(name)
def ask_scan_file_stem(parent, title: str) -> str | None:
    name = simpledialog.askstring(title, SCAN_FILE_NAME_PROMPT, parent=parent)
    if name is None:
        return None
    try:
        return scan_file_stem(name)
    except ValueError as error:
        messagebox.showerror(title, str(error), parent=parent)
        return None
def make_scan_run_folder(parent: Path, stem: str) -> Path:
    """The shared unique-folder allocator, under the application's own name."""
    return _make_scan_run_folder(parent, stem)
def scan_log_line(name: str, details: dict) -> str:
    """The shared log line with the application's clock (tests replace it)."""
    return _scan_log_line(name, details, datetime_class=datetime_module.datetime)
SCAN_PLOT_SNAPSHOT_SETTLE_S = 0.05
class ScanRunRecorder(_CoreScanRunRecorder):
    """The package's recorder bound to this application: its file name and
    version in the log, its own helpers (so replacing app.scan_file_stem,
    make_scan_run_folder or scan_log_line still takes effect), and the list of
    open runs the folder dialog reads."""

    @property
    def PROGRAM_NAME(self):
        return Path(_PROGRAM_FILE).name

    @property
    def APPLICATION_VERSION(self):
        return APP_VERSION

    def _validated_stem(self, stem: str) -> str:
        return scan_file_stem(stem)

    def _make_run_folder(self, parent: Path, stem: str) -> Path:
        return make_scan_run_folder(parent, stem)

    def _format_log(self, name: str, details: dict) -> str:
        return scan_log_line(name, details)

    def _opened(self) -> None:
        _OPEN_SCAN_RUNS.add(self)
class SHHVScanRecorder(ScanRunRecorder):
    def __init__(self, parent: Path, stem: str, page: str = "SHHV") -> None:
        super().__init__(parent, page, stem)
def begin_scan_run(parent, page_label: str, folder_title: str, initial_dir, settings: dict, *, prefix: str | None=None, make=None) -> ScanRunRecorder | None:
    where = {"initialdir": str(initial_dir)} if initial_dir else {}
    folder = filedialog.askdirectory(parent=parent, title=folder_title, **where)
    if not folder:
        return None
    typed = ask_scan_file_stem(parent, f"{page_label} file name")
    if typed is None:
        return None
    try:
        if make is not None:
            return make(Path(folder), typed)
        return ScanRunRecorder(Path(folder), prefix or page_label, typed, settings, label=page_label)
    except Exception as error:
        messagebox.showerror(f'{page_label} run folder', f'Could not create the run folder and its files; the scan was not started: {error}', parent=parent)
        return None
PAIR_FLIP_LIMIT = 8
class CombinedControlApp:
    def __init__(self, root: tk.Tk) -> None:
        self.root = root
        self.root.title(MAIN_WINDOW_TITLE)
        apply_application_identity(self.root)
        self.window_layout = calculate_window_layout(self.root)
        self.ui_scale = float(self.window_layout["ui_scale"])
        self.canvas_scale = float(self.window_layout["canvas_scale"])
        setattr(self.root, "_moke_ui_scale", self.ui_scale)
        self.root.geometry(geometry_string(self.window_layout["control"]))
        control_geometry = self.window_layout["control"]
        self.root.minsize(min(control_geometry[0], max(620, int(760 * self.ui_scale))), min(control_geometry[1], max(500, int(650 * self.ui_scale))))
        screen_width, screen_height = self.window_layout["screen"]
        self.root.maxsize(screen_width, screen_height)
        self.root.bind_all('<FocusIn>', self._enforce_english_input_mode, add='+')
        self.root.after_idle(lambda: force_english_input_mode(self.root))
        self.ui_queue: queue.Queue[Callable[[], None]] = queue.Queue()
        self.executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="led-io")
        self.file_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix='file-export')
        self.closing = False
        self.instrument_connection_indicators: dict[str, tuple[tk.Canvas, int]] = {}
        self.notebook = None
        self._initialize_ppms_state()
        self.newmark_stage_ownership = NewmarkStageOwnership()
        self.build_ui()
        self.notebook.bind('<<NotebookTabChanged>>', self._on_notebook_tab_changed, add='+')
        self._apply_commercial_look()
        self.root.after(20, self.drain_ui_queue)
        self.root.protocol("WM_DELETE_WINDOW", self.request_close)
    def _newmark_stage_ownership(self) -> "NewmarkStageOwnership":
        host = self.__dict__.get("parent_app", self)
        ownership = getattr(host, "__dict__", {}).get("newmark_stage_ownership")
        if not isinstance(ownership, NewmarkStageOwnership):
            ownership = NewmarkStageOwnership()
            host.newmark_stage_ownership = ownership
        return ownership
    def _enforce_english_input_mode(self, event=None) -> None:
        target = getattr(event, "widget", self.root)
        try:
            self.root.after_idle(lambda selected=target: force_english_input_mode(selected))
        except tk.TclError:
            pass
    def _ui_px(self, value: int | float, minimum: int=1, *, canvas: bool=False) -> int:
        scale = self.canvas_scale if canvas else self.ui_scale
        return max(int(minimum), int(round(float(value) * scale)))
    def _arrange_pair_by_width(self, container, left, right, *, gap: int=4, stack_gap: int | None=None, right_width=None, left_width=None, enabled=None):
        def arrange(_event=None) -> None:
            if enabled is not None and not enabled():
                return
            try:
                inset = self._pair_inset(container)
                available = container.winfo_width() - inset
                needed = (self._pair_natural_width(left) if left_width is None else int(left_width())) + (self._pair_natural_width(right) if right_width is None else int(right_width())) + gap
            except (tk.TclError, ValueError):
                return
            container._pair_wide_need = needed + inset
            if available <= 1:
                return
            wide = available >= needed
            if getattr(container, "_pair_side_by_side", None) is wide:
                return
            try:
                window_width = container.winfo_toplevel().winfo_width()
            except (tk.TclError, AttributeError):
                window_width = None
            now = time.monotonic()
            guard = getattr(container, "_pair_flip_guard", None)
            if guard is None or guard["window"] != window_width:
                guard = {"window": window_width, "since": now, "flips": 0, "held": False}
                container._pair_flip_guard = guard
            if guard["held"]:
                return
            if now - guard["since"] > 1.0:
                guard["since"], guard["flips"] = now, 0
            guard["flips"] += 1
            if guard["flips"] > PAIR_FLIP_LIMIT:
                guard["held"] = True
                if getattr(container, "_pair_side_by_side", None) is False:
                    return
                wide = False
            container._pair_side_by_side = wide
            if wide:
                left.grid_configure(row=0, column=0, columnspan=1, padx=(0, gap), pady=0)
                right.grid_configure(row=0, column=1, columnspan=1, padx=0, pady=0)
            else:
                left.grid_configure(row=0, column=0, columnspan=2, padx=0, pady=(0, gap if stack_gap is None else stack_gap))
                right.grid_configure(row=1, column=0, columnspan=2, padx=0, pady=0)
        container.bind("<Configure>", arrange, add="+")
        arrange()
        return arrange
    @staticmethod
    def _pair_inset(container) -> int:
        raw = container.cget("padding") if "padding" in container.keys() else ()
        padding = [int(float(str(v))) for v in container.tk.splitlist(raw)] or [0]
        inset = padding[0] + (padding[2] if len(padding) > 2 else padding[0])
        if container.winfo_class() == "TLabelframe":
            inset += 4
        return inset
    @staticmethod
    def _pair_natural_width(section) -> int:
        extra = 0
        pending = list(section.winfo_children())
        while pending:
            child = pending.pop()
            need = getattr(child, "_pair_wide_need", None)
            if need is not None and getattr(child, "_pair_side_by_side", None) is False:
                extra = max(extra, int(need) - child.winfo_reqwidth())
            pending.extend(child.winfo_children())
        return section.winfo_reqwidth() + max(0, extra)
    def build_ui(self) -> None:
        self.root.rowconfigure(0, weight=1)
        self.root.columnconfigure(0, weight=1)
        self._configure_ui_styles()
        notebook_pad = self._ui_px(3, 2)
        self.notebook = ttk.Notebook(self.root, padding=(notebook_pad, notebook_pad, notebook_pad, 0))
        self.notebook.grid(row=0, column=0, sticky="nsew")
        # One page for every measurement: its tab is the chosen measurement's, the other measurements' tabs are
        # empty frames, and choosing one of them moves the page there (_rte_measurement_tab_changed).
        self.rte_panel_tab = ttk.Frame(self.notebook)
        self.rte_measurement_spare_tabs = []
        for name in RTE_MEASUREMENTS:
            if name == RTE_DEFAULT_MEASUREMENT:
                self.notebook.add(self.rte_panel_tab, text=name)
            else:
                self.rte_measurement_spare_tabs.append(ttk.Frame(self.notebook))
                self.notebook.add(self.rte_measurement_spare_tabs[-1], text=name)
        self.log_tab = ttk.Frame(self.notebook)
        self.notebook.add(self.log_tab, text="Log")
        self.log_tab.rowconfigure(0, weight=1)
        self.log_tab.columnconfigure(0, weight=1)
        self.rte_panel = RTEPanel(self, self.rte_panel_tab)
        self.notebook.select(self.rte_panel_tab)
        self.notebook.bind("<<NotebookTabChanged>>", self._rte_measurement_tab_changed, add="+")
        self.led_log_frame = ttk.LabelFrame(self.log_tab, text="Program communication log", padding=5)
        self.led_log_frame.grid(row=0, column=0, sticky="nsew", padx=8, pady=8)
        self.led_log_frame.rowconfigure(0, weight=1)
        self.led_log_frame.columnconfigure(0, weight=1)
        self.log_text = tk.Text(self.led_log_frame, height=5, wrap="none", state="disabled", font=(self.mono_font_family, self.ui_small_font_size), background="#fbfcfd", relief="flat", padx=5, pady=4)
        self.log_text.grid(row=0, column=0, sticky="nsew")
        scrollbar = ttk.Scrollbar(self.led_log_frame, command=self.log_text.yview)
        scrollbar.grid(row=0, column=1, sticky="ns")
