        metrics_view.grid(row=0, column=0, sticky='nsew')
        metrics_scroll = ttk.Scrollbar(metrics_outer, orient='vertical', command=metrics_view.yview)
        metrics_scroll.grid(row=0, column=1, sticky='ns')
